def highbank_coordinate_live_state_1(state: SceneState, inputs: HighbankCoordinateLiveState1Input) -> HighbankCoordinateLiveState1Result:
    """Historical typed API projects the sole fields; unobserved X/A7 remain a real boundary."""
    checked_state(state)
    if type(inputs) is not HighbankCoordinateLiveState1Input:
        raise ValueError("function-specific typed input required")
    inputs.validate(state)
    frame = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value)
    frame = dispatch_city_result_selection_fields(state, frame)
    return HighbankCoordinateLiveState1Result(value=frame.target_x, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2))

def highbank_select_live_state_1(state: SceneState, inputs: HighbankSelectLiveState1Input) -> HighbankSelectLiveState1Result:
    """Historical typed API projects the sole fields; unobserved X/A7 remain a real boundary."""
    checked_state(state)
    if type(inputs) is not HighbankSelectLiveState1Input:
        raise ValueError("function-specific typed input required")
    inputs.validate(state)
    frame = first_replace(FirstDeploymentFrame.unobserved(), roster=(inputs.destination.cursor() if inputs.destination is not None else None), candidates=(inputs.source.cursor() if inputs.source is not None else None), target_x=inputs.value)
    frame = select_city_result_member_fields(state, frame)
    return HighbankSelectLiveState1Result(destination=frame.roster, source=frame.candidates, value=frame.target_x, carry=bool(frame.status & 1), zero=bool(frame.status & 4), negative=bool(frame.status & 8), overflow=bool(frame.status & 2))

def highbank_select_live_state_2(state: SceneState, inputs: HighbankSelectLiveState2Input) -> HighbankSelectLiveState2Result:
    """Historical projection of one Scene rule; unknown CPU fields stay a boundary."""
    checked_state(state)
    if type(inputs) is not HighbankSelectLiveState2Input:
        raise ValueError('function-specific historical duel-commit input required')
    inputs.validate(state)
    conditions = int(inputs.carry) | (2 if inputs.overflow else 0) | (4 if inputs.zero else 0) | (8 if inputs.negative else 0)
    state.sr = (state.sr & 65520) | conditions
    frame = first_replace(FirstDeploymentFrame.unobserved(), target_x=inputs.value, target_y=inputs.field)
    frame = select_city_engagement_display_side_fields(state, frame)
    return HighbankSelectLiveState2Result(destination=state.table_at(frame.roster.base), value=frame.target_x, field=frame.target_y, carry=bool(state.sr & 1), zero=bool(state.sr & 4), negative=bool(state.sr & 8), overflow=bool(state.sr & 2)).validate(state)

