from dataclasses import replace
from .contexts_highbank import DuelResponseInput, DuelResponseResult

def _checked_response(state, context):
    if type(context) is not DuelResponseInput:
        raise ValueError('explicit actor-response operands required')
    return context.validate(state)



def _choose_duel_guard_response(state: SceneState, context: DuelResponseInput) -> DuelResponseResult:
    """Historical observations of the one actual response core."""
    return _highbank_response_observations(state, context, 0x27bcc)

