from .contexts_highbank import FirstDeploymentFrame, first_replace
from .domain import uint

def count_opposing_battle_roster_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Count the selected live roster and sum troop LONGs without a second State.

    Selection bit1 uses A550 when set, A5A4 when clear. The role name is
    probable; original widths, signed indexed reads and sentinel order are
    confirmed. A leaf preserves every unrelated carrier, current A7 and the
    incoming X when no member is visited. No missing high WORD is fabricated.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('sole retained deployment frame required')
    frame.validate(state, frame.stack_cursor is not None)
    uint(frame.target_x, 32)
    uint(frame.unit, 32)
    primary = bool(state.read(0xFFFFF6D7, 1) & 2)
    roster = state.table_at(0xFFFFA550 if primary else 0xFFFFA5A4).cursor()
    troops = state.table_at(0xFFFFC800).cursor()
    count_carrier = replace_word(frame.target_x, 0)
    total = 0
    status = None if frame.status is None else ((frame.status & 16) | 4)
    frame = first_replace(frame, target_x=count_carrier, target_y=total,
        roster=roster, candidates=troops, status=status)
    while True:
        member = roster.next_word()
        member_carrier = replace_word(frame.unit, member)
        status = None if frame.status is None else ((frame.status & 16) | (8 if member & 32768 else 0) | (4 if member == 0 else 0))
        frame = first_replace(frame, unit=member_carrier, status=status)
        if member & 32768:
            return frame.validate(state, frame.stack_cursor is not None)
        old_count = low16(frame.target_x)
        count = u16(old_count + 1)
        count_overflow = old_count == 32767
        count_status = (17 if old_count == 65535 else 0) | (2 if count_overflow else 0) | (8 if count & 32768 else 0) | (4 if count == 0 else 0)
        frame = first_replace(frame, target_x=replace_word(frame.target_x, count), status=count_status)
        offset = u16(member << 2)
        shift_status = (17 if member & 16384 else 0) | (8 if offset & 32768 else 0) | (4 if offset == 0 else 0)
        frame = first_replace(frame, unit=replace_word(frame.unit, offset), status=shift_status)
        amount = troops.long(offset)
        previous = frame.target_y
        wide = previous + amount
        total = u32(wide)
        overflow = bool(~(previous ^ amount) & (previous ^ total) & 2147483648)
        status = (17 if wide > 4294967295 else 0) | (2 if overflow else 0) | (8 if total & 2147483648 else 0) | (4 if total == 0 else 0)
        frame = first_replace(frame, target_y=total, status=status)


from .contexts_highbank import FirstDeploymentReturnBoundary

def _standard_order_compare(frame: FirstDeploymentFrame, left, right) -> FirstDeploymentFrame:
    difference = u16(left - right)
    overflow = bool((left ^ right) & (left ^ difference) & 32768)
    flags = (1 if left < right else 0) | (2 if overflow else 0) | (8 if difference & 32768 else 0) | (4 if difference == 0 else 0)
    status = None if frame.status is None else ((frame.status & 16) | flags)
    return first_replace(frame, status=status)


def _standard_order_increment(frame: FirstDeploymentFrame, name) -> FirstDeploymentFrame:
    carrier = frame.carrier(name)
    previous = low16(carrier)
    value = u16(previous + 1)
    status = (17 if previous == 65535 else 0) | (2 if previous == 32767 else 0) | (8 if value & 32768 else 0) | (4 if value == 0 else 0)
    return first_replace(frame, **{name:replace_word(carrier, value)}, status=status)


def _standard_order_enter(frame: FirstDeploymentFrame, continuation) -> FirstDeploymentFrame:
    if frame.stack_cursor is None:
        raise Boundary('standard order requires actual current callee-entry SP')
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, continuation)
    return first_replace(frame, stack_cursor=stack)


def _standard_order_leave(frame: FirstDeploymentFrame, continuation) -> FirstDeploymentFrame:
    actual = frame.stack_cursor.long()
    if actual != continuation:
        raise FirstDeploymentReturnBoundary(actual, frame, continuation)
    return first_replace(frame, stack_cursor=frame.stack_cursor.advance(4))


def evaluate_secondary_standard_action_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> FirstDeploymentFrame:
    """236E4: original B600 gate, one RNG and optional 26560 action.

    The game-role name is probable. D1 increments at 23706/23710 remain
    original even though 83D4 then overwrites D1; no success-rate cleanup.
    Complete calls need the real whole caller fields, never projected zeros.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current fields and actual completeness selector required')
    frame.validate(state, complete)
    for carrier in (frame.target_x, frame.target_y, frame.unit, frame.choice):
        uint(carrier, 32)
    rank_table = state.table_at(0xFFFFB600).cursor()
    actor = low16(frame.choice)
    offset = u16(actor << 1)
    status = (17 if actor & 32768 else 0) | (8 if offset & 32768 else 0) | (4 if offset == 0 else 0)
    frame = first_replace(frame, target_x=replace_word(frame.target_x, offset), roster=rank_table, status=status)
    rank = rank_table.word(offset)
    frame = first_replace(frame, target_y=replace_word(frame.target_y, rank), unit=replace_word(frame.unit, 1), status=(frame.status & 16))
    frame = _standard_order_compare(frame, rank, 60)
    if rank >= 60:
        frame = _standard_order_increment(frame, 'unit')
        frame = _standard_order_compare(frame, rank, 80)
        if rank >= 80:
            frame = _standard_order_increment(frame, 'target_y')
            frame = _standard_order_compare(frame, low16(frame.target_y), 100)
            if low16(frame.target_y) >= 100:
                frame = _standard_order_increment(frame, 'target_y')
    # Original JSR 23712 writes 23718 before the one existing RNG call.
    entered = _standard_order_enter(frame, 0x23718)
    from .services import sample_random_pair
    random = sample_random_pair(state)
    extend = low16(random.sample) < low16(random.updated_state)
    random_status = (16 if extend else 0) | (8 if random.updated_state & 2147483648 else 0) | (4 if random.updated_state == 0 else 0)
    frame = _standard_order_leave(first_replace(entered, target_x=random.sample, target_y=random.updated_state, status=random_status), 0x23718)
    sample = random.sample & 65535
    shifted = u32(sample << 2)
    scaled = swap_words(shifted)
    # ANDI makes a 16-bit LONG, so LSL.L #2 clears X/C; SWAP retains X=0.
    frame = first_replace(frame, target_x=scaled, status=(8 if scaled & 2147483648 else 0) | (4 if scaled == 0 else 0))
    threshold = low16(frame.unit)
    frame = _standard_order_compare(frame, low16(scaled), threshold)
    if low16(scaled) >= threshold:
        if not state.sr & 8192:
            raise Boundary('standard-order original full-SR operation requires supervisor')
        if state.sr & 32768:
            raise Boundary('standard-order trace continuation unmodeled')
        frame = first_replace(frame, status=frame.status & 30)
        state.set_status_word((state.sr & 65504) | frame.status)
        return frame.validate(state, complete)
    entered = _standard_order_enter(frame, 0x2372C)
    state.sr = (state.sr & 65504) | entered.status
    if not complete:
        # Preserve the one existing legacy callee rather than copying 26560.
        # That draft currently stops at its genuine 234D2 input boundary and
        # has no actual returned SP; it cannot publish a complete field result.
        highbank_coordinate_live_state_85(state, HighbankCoordinateLiveState85Input(
            destination=state.table_at(entered.roster.base), value=entered.target_x,
            field=entered.target_y, tile=entered.unit, limit=entered.offset_x,
            remaining=entered.choice, stack_cursor=entered.stack_cursor,
            carry=bool(entered.status & 1), zero=bool(entered.status & 4),
            negative=bool(entered.status & 8), overflow=bool(entered.status & 2)))
        raise Boundary('legacy 26560 return does not observe actual SP or full fields')
    result = execute_standard_action_chain_fields(state, entered, True).validate(state, True).frame
    if type(result) is not FirstDeploymentFrame:
        raise Boundary('26560 must return the actual current sole deployment fields')
    result.validate(state, True)
    return _standard_order_leave(result, 0x2372C).validate(state, True)


from .contexts_highbank import StandardPositionOrderFields

def _position_order_move(frame: FirstDeploymentFrame, name, value, bits) -> FirstDeploymentFrame:
    uint(value, bits)
    retained = frame.carrier(name)
    result = replace_byte(retained, value) if bits == 8 else replace_word(retained, value)
    flags = (8 if value & (1 << (bits - 1)) else 0) | (4 if value == 0 else 0)
    status = None if frame.status is None else ((frame.status & 16) | flags)
    return first_replace(frame, **{name:result}, status=status)


def _position_order_shift(frame: FirstDeploymentFrame, name, count, right: bool = False) -> FirstDeploymentFrame:
    if type(right) is not bool or not 1 <= count <= 8:
        raise ValueError('actual bounded WORD shift required')
    carrier = frame.carrier(name)
    original = low16(carrier)
    shifted = original >> count if right else u16(original << count)
    carried = bool(original & (1 << (count - 1 if right else 16 - count)))
    status = (17 if carried else 0) | (8 if shifted & 32768 else 0) | (4 if shifted == 0 else 0)
    return first_replace(frame, **{name:replace_word(carrier, shifted)}, status=status)


def _position_order_carry(state: SceneState, frame: FirstDeploymentFrame, conditions, enabled: bool) -> StandardPositionOrderFields:
    if type(enabled) is not bool:
        raise ValueError('actual carry result required')
    if not state.sr & 8192:
        raise Boundary('position-order original full-SR operation requires supervisor')
    if state.sr & 32768:
        raise Boundary('position-order trace continuation unmodeled')
    conditions = (conditions & 14) | int(enabled)
    status = None if frame.status is None else ((frame.status & 16) | conditions)
    # Keep physical State's unobserved X when the old API did not expose it;
    # never publish that unavailable bit as an input/return Frame observation.
    state.set_status_word(((state.sr & 65520) | conditions) if status is None else ((state.sr & 65504) | status))
    return StandardPositionOrderFields(first_replace(frame, status=status), conditions).validate(state)


def _position_order_submit(state: SceneState, frame: FirstDeploymentFrame, complete: bool) -> StandardPositionOrderFields:
    """Actual236D0 JSR/236D6 return; partial old callee is not a full ABI."""
    if complete:
        entered = _standard_order_enter(frame, 0x236D6)
        state.sr = (state.sr & 65504) | entered.status
        from .business_city import city_calculate_live_quotient_10_fields
        from .services import BattlePolicyMemory
        result = city_calculate_live_quotient_10_fields(BattlePolicyMemory(state), entered)
        if type(result) is not FirstDeploymentFrame:
            raise Boundary('1DCAA must return actual current complete deployment fields')
        result.validate(state, True)
        returned = _standard_order_leave(result, 0x236D6)
        return _position_order_carry(state, returned, returned.status & 15, True)
    # One existing city algorithm remains the legacy authority. It exposes
    # A0/A1/A5 and all eight numeric results, but not complete X/SP/A2/A3/A4/A6.
    # No copy, fabricated token, or partial result promoted into full fields.
    from .business_city import city_calculate_live_quotient_10
    from .contexts_city import CityCalculateLiveQuotient10Input
    result = city_calculate_live_quotient_10(state, CityCalculateLiveQuotient10Input(
        roster=frame.scratch, value=frame.target_x, field=frame.target_y,
        tile=frame.unit, row=frame.count, offset=frame.distance,
        limit=frame.offset_x, member=frame.offset_y, remaining=frame.choice,
        carry=bool(frame.status & 1), zero=bool(frame.status & 4),
        negative=bool(frame.status & 8), overflow=bool(frame.status & 2)))
    returned = first_replace(frame, target_x=result.value, target_y=result.field,
        unit=result.tile, count=result.row, distance=result.offset,
        offset_x=result.limit, offset_y=result.member, choice=result.remaining,
        roster=result.destination.cursor(), candidates=result.source.cursor(),
        scratch=result.roster, status=None)
    flags = int(result.carry) | (2 if result.overflow else 0) | (4 if result.zero else 0) | (8 if result.negative else 0)
    return _position_order_carry(state, returned, flags, True)


def evaluate_standard_position_order_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """Sole2363E gate and target-position update, using live ordered reads."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole real frame and actual completeness selector required')
    frame.validate(state, complete)
    for carrier in (frame.target_x, frame.target_y, frame.unit, frame.choice):
        uint(carrier, 32)
    actor = low16(frame.choice)
    for address, view_name in ((0xFFFFA654, 'roster'), (0xFF3CC2, 'roster'), (0xFF3DC2, 'candidates')):
        table = state.table_at(address).cursor()
        frame = first_replace(frame, **{view_name:table})
        active = table.byte(actor)
        flags = (8 if active & 128 else 0) | (4 if active == 0 else 0)
        frame = first_replace(frame, status=None if frame.status is None else ((frame.status & 16) | flags))
        if active != 0:
            return _position_order_carry(state, frame, flags, False)
    variant = state.table_at(0xFFFF9FFF).cursor()
    frame = first_replace(frame, roster=variant)
    scene = state.read(0xFFFFF68A, 2)
    frame = _position_order_move(frame, 'target_x', scene, 16)
    frame = _position_order_move(frame, 'target_y', 0, 16)
    frame = _position_order_move(frame, 'target_y', variant.byte(scene), 8)
    anchors = state.table_at(0xABDA8).cursor()
    frame = first_replace(frame, roster=anchors)
    scene = state.read(0xFFFFF68A, 2)
    frame = _position_order_move(frame, 'target_x', scene, 16)
    frame = _position_order_shift(frame, 'target_x', 5)
    frame = _position_order_shift(frame, 'target_y', 1)
    left, right = low16(frame.target_x), low16(frame.target_y)
    wide = left + right
    offset = u16(wide)
    overflow = bool(~(left ^ right) & (left ^ offset) & 32768)
    status = (17 if wide > 65535 else 0) | (2 if overflow else 0) | (8 if offset & 32768 else 0) | (4 if offset == 0 else 0)
    frame = first_replace(frame, target_x=replace_word(frame.target_x, offset), status=status)
    frame = _position_order_move(frame, 'target_y', 0, 16)
    frame = _position_order_move(frame, 'target_y', anchors.byte(offset), 8)
    frame = _position_order_shift(_position_order_shift(frame, 'target_y', 3), 'target_y', 7)
    frame = _position_order_move(frame, 'unit', 0, 16)
    frame = _position_order_move(frame, 'unit', anchors.byte(offset, 1), 8)
    frame = _position_order_shift(_position_order_shift(frame, 'unit', 3), 'unit', 7)
    positions = state.table_at(0xFFFFA150).cursor()
    frame = first_replace(frame, roster=positions)
    frame = _position_order_move(frame, 'target_x', actor, 16)
    frame = _position_order_shift(frame, 'target_x', 2)
    offset = low16(frame.target_x)
    current_x = positions.word(offset)
    frame = _standard_order_compare(frame, low16(frame.target_y), current_x)
    if low16(frame.target_y) == current_x:
        current_y = positions.word(offset, 2)
        frame = _standard_order_compare(frame, low16(frame.unit), current_y)
        if low16(frame.unit) == current_y:
            return StandardPositionOrderFields(frame, frame.status & 15).validate(state, complete)
    target = state.table_at(0xFF2C00).cursor()
    frame = first_replace(frame, roster=target)
    frame = _position_order_move(frame, 'target_x', actor, 16)
    frame = _position_order_shift(frame, 'target_x', 2)
    offset = low16(frame.target_x)
    frame = _position_order_shift(frame, 'target_y', 7, True)
    target.set_word(offset, low16(frame.target_y))
    frame = first_replace(frame, status=(frame.status & 16) | (8 if low16(frame.target_y) & 32768 else 0) | (4 if low16(frame.target_y) == 0 else 0))
    frame = _position_order_shift(frame, 'unit', 7, True)
    target.set_word(offset, low16(frame.unit), 2)
    frame = first_replace(frame, status=(frame.status & 16) | (8 if low16(frame.unit) & 32768 else 0) | (4 if low16(frame.unit) == 0 else 0))
    submitted = state.table_at(0xFFFFAE28).cursor()
    frame = first_replace(frame, roster=submitted)
    submitted.set_byte(actor, 1)
    frame = first_replace(frame, status=frame.status & 16)
    return _position_order_submit(state, frame, complete)


def _standard_action_call_fields(state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool) -> FirstDeploymentFrame:
    entered = _standard_order_enter(frame, continuation)
    if entered.status is not None:
        state.sr = (state.sr & 65504) | entered.status
    if target == 0x234D2:
        from .services import BattlePolicyMemory, collect_contacts_in_speed_radius_fields
        result = collect_contacts_in_speed_radius_fields(BattlePolicyMemory(state), entered).frame
    elif target == 0x266D8:
        result = execute_type6_standard_action_fields(state, entered, complete).frame
    elif target == 0x265B0:
        result = evaluate_second_side_attribute_order_fields(state, entered, complete)
    elif target == 0x267DC:
        result = execute_open_terrain_standard_action_fields(state, entered, complete).frame
    elif target == 0x268F8:
        result = execute_second_open_standard_action_fields(state, entered, complete).frame
    elif target == 0x269A6:
        result = execute_ranked_standard_action_fields(state, entered, 1, complete).frame
    elif target == 0x26AAC:
        result = execute_ranked_standard_action_fields(state, entered, 4, complete).frame
    elif target == 0x260E4 and complete:
        from .services import present_battle_message_fields
        result = present_battle_message_fields(state, entered)
    elif target == 0x1A47A and complete:
        from .business_city import city_coordinate_live_state_76_fields
        result = city_coordinate_live_state_76_fields(state, entered)
    else:
        result = call_target(state, target, entered)
    if type(result) is not FirstDeploymentFrame:
        raise Boundary('action callee must return actual current sole deployment fields')
    result.validate(state, complete)
    return _standard_order_leave(result, continuation).validate(state, complete)


def execute_standard_action_chain_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """26560: live initial action selection followed by six ordered attempts.

    The neutral role is probable; exact save width, calls and branch order are
    original facts. No unavailable deep callee result becomes success.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current action fields and actual observation selector required')
    frame.validate(state, complete)
    uint(frame.choice, 32)
    if frame.stack_cursor is None:
        raise Boundary('action chain requires actual current callee-entry A7')
    actor = low16(frame.choice)
    stack = frame.stack_cursor.advance(-2)
    stack.set_word(0, actor)
    flags = (8 if actor & 32768 else 0) | (4 if actor == 0 else 0)
    frame = first_replace(frame, stack_cursor=stack,
        status=None if frame.status is None else ((frame.status & 16) | flags))
    # Real26562 BSR234D2 writes26566 below the saved WORD. The existing
    # draft's first unresolved partial-service stop is now a current full
    # field boundary, not an unconditional invented return or an ABI copy.
    frame = _standard_action_call_fields(state, frame, 0x234D2, 0x26566, complete)
    candidate = state.read(0xFFFFD300, 2)
    flags = (8 if candidate & 32768 else 0) | (4 if candidate == 0 else 0)
    frame = first_replace(frame, status=None if frame.status is None else ((frame.status & 16) | flags))
    selected = False
    if not candidate & 32768:
        for target, continuation in ((0x265B0, 0x26572), (0x266D8, 0x2657A),
                (0x267DC, 0x26582), (0x268F8, 0x2658A),
                (0x269A6, 0x26592), (0x26AAC, 0x2659A)):
            frame = _standard_action_call_fields(state, frame, target, continuation, complete)
            if frame.status is None:
                raise Boundary('action attempt has not observed its actual returned carry')
            if frame.status & 1:
                selected = True
                break
    # Both actual2659E and265A8 consume the current saved slot. A subcallee
    # may have changed the slot or D7.high; never use entrance actor/high/SP.
    stack = frame.stack_cursor
    restored_actor = stack.next_word()
    frame = first_replace(frame, choice=replace_word(frame.choice, restored_actor), stack_cursor=stack,
        status=None if frame.status is None else ((frame.status & 16) | (8 if restored_actor & 32768 else 0) | (4 if restored_actor == 0 else 0)))
    flags = (8 if restored_actor & 32768 else 0) | (4 if restored_actor == 0 else 0)
    return _position_order_carry(state, frame, flags, selected).validate(state, complete)


# Sole22700/22756 city scan and structured retreat fields.
def _retreat_policy_move(state: SceneState, frame: FirstDeploymentFrame, name, value) -> FirstDeploymentFrame:
    uint(value, 16)
    carrier = replace_word(frame.carrier(name), value)
    conditions = (8 if value & 32768 else 0) | (4 if value == 0 else 0)
    status = None if frame.status is None else (frame.status & 16) | conditions
    state.sr = (state.sr & 65520) | conditions
    return first_replace(frame, **{name:carrier}, status=status)


def _retreat_policy_compare(state: SceneState, frame: FirstDeploymentFrame, left, right, bits) -> FirstDeploymentFrame:
    uint(left, bits)
    uint(right, bits)
    mask, sign = (1 << bits) - 1, 1 << (bits - 1)
    difference = (left - right) & mask
    overflow = bool((left ^ right) & (left ^ difference) & sign)
    conditions = (1 if left < right else 0) | (2 if overflow else 0) | (8 if difference & sign else 0) | (4 if difference == 0 else 0)
    status = None if frame.status is None else (frame.status & 16) | conditions
    state.sr = (state.sr & 65520) | conditions
    return first_replace(frame, status=status)


def _retreat_policy_shift(state: SceneState, frame: FirstDeploymentFrame, name, amount, right: bool = False) -> FirstDeploymentFrame:
    if type(right) is not bool or not 1 <= amount <= 8:
        raise ValueError('actual bounded WORD shift required')
    carrier = frame.carrier(name)
    original = low16(carrier)
    result = original >> amount if right else u16(original << amount)
    carry = bool(original & (1 << (amount - 1 if right else 16 - amount)))
    status = (17 if carry else 0) | (8 if result & 32768 else 0) | (4 if result == 0 else 0)
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, **{name:replace_word(carrier, result)}, status=status)


def _retreat_policy_carry(state: SceneState, frame: FirstDeploymentFrame, enabled: bool) -> FirstDeploymentFrame:
    if type(enabled) is not bool or frame.status is None:
        raise ValueError('actual known retreat flags and carry required')
    status = (frame.status & 30) | int(enabled)
    state.set_status_word((state.sr & 65504) | status)
    return first_replace(frame, status=status)


def find_other_owned_city_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> FirstDeploymentFrame:
    """22700: descending live owner scan, excluding F68A minus one.

    The current city subtraction establishes real X even for the historical
    API that did not expose incoming X. DBRA changes only the low scan WORD;
    final CMP flags and full-SR carry operations keep the original semantics.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole city-scan fields and actual completeness required')
    frame.validate(state, complete)
    for carrier in (frame.target_x, frame.count, frame.distance):
        uint(carrier, 32)
    scene = state.read(0xFFFFF68A, 2)
    frame = _retreat_policy_move(state, frame, 'count', scene)
    current_city = u16(scene - 1)
    overflow = scene == 32768
    status = (17 if scene == 0 else 0) | (2 if overflow else 0) | (8 if current_city & 32768 else 0) | (4 if current_city == 0 else 0)
    state.sr = (state.sr & 65504) | status
    frame = first_replace(frame, count=replace_word(frame.count, current_city), status=status)
    frame = _retreat_policy_move(state, frame, 'distance', 39)
    owners = state.table_at(0xFFFFF428).cursor()
    frame = first_replace(frame, roster=owners)
    frame = _retreat_policy_move(state, frame, 'target_x', state.read(0xFFFFF68E, 2))
    side = state.read(0xFFFFF6D7, 1)
    status = (frame.status & 27) | (0 if side & 2 else 4)
    state.sr = (state.sr & 65504) | status
    frame = first_replace(frame, status=status)
    if not side & 2:
        frame = _retreat_policy_move(state, frame, 'target_x', state.read(0xFFFFF68C, 2))
    while True:
        city = low16(frame.distance)
        owner = owners.byte(city)
        frame = _retreat_policy_compare(state, frame, low8(frame.target_x), owner, 8)
        if low8(frame.target_x) == owner:
            frame = _retreat_policy_compare(state, frame, low16(frame.count), city, 16)
            if low16(frame.count) != city:
                return _retreat_policy_carry(state, frame, True).validate(state, complete)
        # DBRA does not overwrite the comparison flags.
        city = u16(city - 1)
        frame = first_replace(frame, distance=replace_word(frame.distance, city))
        if city == 65535:
            return _retreat_policy_carry(state, frame, False).validate(state, complete)


def _retreat_policy_random(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22794 JSR/2279A RTS around the existing sole 83D4 RNG pair."""
    entered = _standard_order_enter(frame, 0x2279A)
    from .services import sample_random_pair
    random = sample_random_pair(state)
    extend = low16(random.sample) < low16(random.updated_state)
    status = (16 if extend else 0) | (8 if random.updated_state & 2147483648 else 0) | (4 if random.updated_state == 0 else 0)
    state.sr = (state.sr & 65504) | status
    result = first_replace(entered, target_x=random.sample, target_y=random.updated_state, status=status)
    return _standard_order_leave(result, 0x2279A)


def _retreat_policy_call(state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool, legacy_kind) -> FirstDeploymentFrame:
    if type(complete) is not bool or legacy_kind not in (
            HighbankCoordinateLiveState51Service1, HighbankCoordinateLiveState51Service2,
            HighbankCoordinateLiveState51Service3, HighbankCoordinateLiveState51Service4,
            HighbankCoordinateLiveState51Service5, HighbankCoordinateLiveState51Service6):
        raise ValueError('one existing retreat child contract required')
    entered = _standard_order_enter(frame, continuation)
    state.sr = (state.sr & 65504) | entered.status
    if not complete:
        # Legacy partial service contracts stay partial after the real push.
        context = legacy_kind(destination=state.table_at(entered.roster.base),
            descriptor=state.table_at(entered.controller.base),
            value=entered.target_x, field=entered.target_y, row=entered.count,
            offset=entered.distance, remaining=entered.choice)
        call_target(state, target, context)
        raise Boundary('legacy retreat child return lacks actual full fields and SP')
    if target == 0x17C8A:
        from .services import ensure_neighbor_capacity_fields
        result = ensure_neighbor_capacity_fields(state, entered)
    elif target == 0x17F30:
        from .services import integrate_selected_officer_into_packed_group_fields
        result = integrate_selected_officer_into_packed_group_fields(state, entered)
    elif target == 0x260E4:
        from .services import present_battle_message_fields
        result = present_battle_message_fields(state, entered)
    else:
        result = call_target(state, target, entered)
    if type(result) is not FirstDeploymentFrame:
        raise Boundary('retreat child requires all actual full fields and SP')
    result.validate(state, True)
    state.sr = (state.sr & 65504) | result.status
    return _standard_order_leave(result, continuation)


def _retreat_policy_modal(state: SceneState, frame: FirstDeploymentFrame, complete: bool, middle_band: bool) -> FirstDeploymentFrame:
    """227AA: actual saved D7 WORD, three real child calls and live toggles."""
    saved = low16(frame.choice)
    stack = frame.stack_cursor.advance(-2)
    stack.set_word(0, saved)
    frame = _retreat_policy_move(state, first_replace(frame, stack_cursor=stack), 'choice', saved)
    frame = _retreat_policy_call(state, frame, 0x17C8A, 0x227B2, complete,
        HighbankCoordinateLiveState51Service4 if middle_band else HighbankCoordinateLiveState51Service1)
    restored = frame.stack_cursor.word()
    frame = _retreat_policy_move(state, first_replace(frame, stack_cursor=frame.stack_cursor.advance(2)), 'choice', restored)
    selected = state.read(0xFFFFF6EC, 2)
    conditions = (8 if selected & 32768 else 0) | (4 if selected == 0 else 0)
    frame = first_replace(frame, status=(frame.status & 16) | conditions)
    state.sr = (state.sr & 65504) | frame.status
    if selected & 32768:
        return _retreat_policy_carry(state, frame, False)
    value = low16(frame.choice)
    frame = _retreat_policy_move(state, frame, 'choice', value)
    state.write(0xFFFFF3A6, 2, value)
    frame = _retreat_policy_call(state, frame, 0x17F30, 0x227C4, complete,
        HighbankCoordinateLiveState51Service5 if middle_band else HighbankCoordinateLiveState51Service2)
    value = state.read(0xFFFFF3A6, 2)
    # These memory MOVE instructions change conditions, not a numeric carrier.
    conditions = (8 if value & 32768 else 0) | (4 if value == 0 else 0)
    frame = first_replace(frame, status=(frame.status & 16) | conditions)
    state.sr = (state.sr & 65504) | frame.status
    state.write(0xFFFFF3D2, 2, value)
    state.write(0xFFFFF740, 2, 302)
    frame = first_replace(frame, status=frame.status & 16)
    state.sr = (state.sr & 65504) | frame.status
    flag = state.read(0xFFFFF6D7, 1)
    frame = first_replace(frame, status=(frame.status & 27) | (0 if flag & 2 else 4))
    state.sr = (state.sr & 65504) | frame.status
    state.write(0xFFFFF6D7, 1, flag ^ 2)
    frame = _retreat_policy_call(state, frame, 0x260E4, 0x227DC, complete,
        HighbankCoordinateLiveState51Service6 if middle_band else HighbankCoordinateLiveState51Service3)
    flag = state.read(0xFFFFF6D7, 1)
    frame = first_replace(frame, status=(frame.status & 27) | (0 if flag & 2 else 4))
    state.sr = (state.sr & 65504) | frame.status
    state.write(0xFFFFF6D7, 1, flag ^ 2)
    return _retreat_policy_carry(state, frame, True)


def evaluate_other_city_retreat_order_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> FirstDeploymentFrame:
    """Sole22756: other-city gate, troop/attribute thresholds and retreat chance.

    The role name is probable; every original operation and read order is
    confirmed. Existing child owners are shared. Missing modal full ABIs stop
    after actual WORD/token writes, never after fabricated successful returns.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole retreat fields and actual completeness required')
    frame.validate(state, complete)
    for carrier in (frame.target_x, frame.target_y, frame.count, frame.distance, frame.choice):
        uint(carrier, 32)
    if frame.stack_cursor is None:
        raise Boundary('22756 requires actual current callee-entry SP')
    entered = _standard_order_enter(frame, 0x22758)
    frame = find_other_owned_city_fields(state, entered, complete)
    frame = _standard_order_leave(frame, 0x22758)
    if not frame.status & 1:
        return _retreat_policy_carry(state, frame, False).validate(state, complete)
    frame = _retreat_policy_move(state, frame, 'target_x', low16(frame.choice))
    frame = _retreat_policy_shift(state, frame, 'target_x', 2)
    offset = low16(frame.target_x)
    troops = state.table_at(0xFFFFC800)
    frame = first_replace(frame, controller=troops)
    strength = troops.long(offset)
    frame = _retreat_policy_compare(state, frame, strength, 200, 32)
    middle_band = strength > 200
    if middle_band:
        strength = troops.long(offset)
        frame = _retreat_policy_compare(state, frame, strength, 500, 32)
        if strength > 500:
            return _retreat_policy_carry(state, frame, False).validate(state, complete)
        frame = _retreat_policy_shift(state, frame, 'target_x', 1, True)
        skills = state.table_at(0xFFFFB000)
        frame = first_replace(frame, controller=skills)
        frame = _retreat_policy_move(state, frame, 'target_y', skills.word(low16(frame.target_x)))
        frame = _retreat_policy_shift(state, frame, 'target_y', 2, True)
        aptitudes = state.table_at(0xFFFFB200)
        frame = first_replace(frame, controller=aptitudes)
        aptitude = aptitudes.word(low16(frame.target_x))
        frame = _retreat_policy_compare(state, frame, low16(frame.target_y), aptitude, 16)
        if low16(frame.target_y) < aptitude:
            return _retreat_policy_carry(state, frame, False).validate(state, complete)
    frame = _retreat_policy_random(state, frame)
    status = (frame.status & 27) | (0 if frame.target_x & 1 else 4)
    state.sr = (state.sr & 65504) | status
    frame = first_replace(frame, status=status)
    if not frame.target_x & 1:
        return _retreat_policy_carry(state, frame, False).validate(state, complete)
    return _retreat_policy_modal(state, frame, complete, middle_band).validate(state, complete)


def execute_type6_standard_action_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """Historical type6 control projected through the one ranked-action flow."""
    return execute_ranked_standard_action_fields(state, frame, 3, complete)

def _attribute_order_compare(frame: FirstDeploymentFrame, left, right, width) -> FirstDeploymentFrame:
    """CMP preserves actual X and applies its original operand width."""
    if width not in (8, 16, 32):
        raise ValueError('original attribute-order compare width required')
    uint(left, width)
    uint(right, width)
    mask = (1 << width) - 1
    sign = 1 << (width - 1)
    value = (left - right) & mask
    status = None if frame.status is None else ((frame.status & 16) |
        (1 if left < right else 0) | (8 if value & sign else 0) |
        (4 if value == 0 else 0) | (2 if (left ^ right) & (left ^ value) & sign else 0))
    return first_replace(frame, status=status)

def _attribute_order_call_fields(state: SceneState, frame: FirstDeploymentFrame, target, continuation, complete: bool) -> FirstDeploymentFrame:
    """Known field cores execute inside the one actual outer return LONG."""
    entered = frame if frame.stack_cursor is None else _standard_order_enter(frame, continuation)
    if entered.status is not None:
        state.sr = (state.sr & 65504) | entered.status
    memory = BattlePolicyMemory(state)
    if target == 0x83D4:
        result = first_deployment_random_fields(memory, entered)
    elif target == 0x26692:
        result = build_non_type6_candidates_fields(memory, entered)
    elif target == 0x26638:
        result = select_lowest_filtered_rating_fields(memory, entered)
    elif target == 0x2665E:
        result = compute_selected_attribute_budget_second_side_fields(memory, entered)
    elif target == 0x1A47A and complete:
        from .business_city import city_coordinate_live_state_76_fields
        result = city_coordinate_live_state_76_fields(state, entered)
    else:
        # Unknown descendants receive the real slot and frame. A partial old
        # return is not enough to invent their successful full continuation.
        result = call_target(state, target, entered)
    if type(result) is not FirstDeploymentFrame:
        raise Boundary('attribute-order child needs actual full return fields')
    result.validate(state, complete or entered.stack_cursor is not None)
    if result.status is None:
        raise Boundary('attribute-order child did not observe its actual CCR')
    if result.status is not None:
        state.sr = (state.sr & 65504) | result.status
    if entered.stack_cursor is not None:
        return _standard_order_leave(result, continuation).validate(state, complete)
    if result.stack_cursor is not None:
        raise Boundary('an unobserved legacy stack cannot acquire a fabricated SP')
    return result

def evaluate_second_side_attribute_order_fields(state: SceneState, frame: FirstDeploymentFrame, complete: bool = False) -> FirstDeploymentFrame:
    """265B0: real rejection and order-submission path, using sole field bodies."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('actual second-side attribute-order frame required')
    frame.validate(state, complete)
    uint(frame.choice, 32)
    frame = _attribute_order_call_fields(state, frame, 0x83D4, 0x265B6, complete)
    sample = low16(frame.target_x)
    shifted = u32(sample << 2)
    swapped = u32((low16(shifted) << 16) | (shifted >> 16))
    # LSL.L #2 on the masked sample clears X; SWAP changes NZVC, not X.
    frame = first_replace(frame, target_x=swapped, status=0)
    frame = _attribute_order_compare(frame, low16(swapped), 3, 16)
    if low16(swapped) == 3:
        return _position_order_carry(state, frame, frame.status & 15, False).frame
    frame = _attribute_order_call_fields(state, frame, 0x26692, 0x265CC, complete)
    first = state.read(0xFFFFD400, 2)
    frame = first_replace(frame, status=(frame.status & 16) |
        (8 if first & 32768 else 0) | (4 if first == 0 else 0))
    if first & 32768:
        return _position_order_carry(state, frame, frame.status & 15, False).frame
    frame = _attribute_order_call_fields(state, frame, 0x26638, 0x265D8, complete)
    readiness = low8(frame.target_x)
    frame = _attribute_order_compare(frame, readiness, 50, 8)
    if readiness > 50:
        return _position_order_carry(state, frame, frame.status & 15, False).frame
    selected = low16(frame.target_y)
    state.write(0xFFFFF3A6, 2, selected)
    frame = _first_memory_word(frame, selected)
    frame = _attribute_order_call_fields(state, frame, 0x2665E, 0x265E8, complete)
    available = state.read(0xFFFFF696, 4)
    frame = _attribute_order_compare(frame, frame.target_x, available, 32)
    if frame.target_x > available:
        return _position_order_carry(state, frame, frame.status & 15, False).frame
    assigned = state.table_at(0xFFFFA754).cursor()
    frame = first_replace(frame, roster=assigned)
    assigned.set_byte(low16(frame.choice), 3)
    frame = first_replace(frame, status=frame.status & 16)
    actor = low16(frame.choice)
    state.write(0xFFFFF3F2, 2, actor)
    frame = _first_memory_word(frame, actor)
    state.write(0xFFFFF6D4, 2, 4)
    frame = _first_memory_word(frame, 4)
    frame = _attribute_order_call_fields(state, frame, 0x1A47A, 0x2660A, complete)
    if not frame.status & 1:
        flag = state.read(0xFFFFF6D7, 1)
        state.write(0xFFFFF6D7, 1, flag ^ 2)
        frame = first_replace(frame, status=(frame.status & 27) | (0 if flag & 2 else 4))
        selected = state.read(0xFFFFF3A6, 2)
        state.write(0xFFFFF3D0, 2, selected)
        frame = _first_memory_word(frame, selected)
        state.write(0xFFFFF740, 2, 300)
        frame = _first_memory_word(frame, 300)
        frame = _attribute_order_call_fields(state, frame, 0x260E4, 0x26624, complete)
        flag = state.read(0xFFFFF6D7, 1)
        state.write(0xFFFFF6D7, 1, flag ^ 2)
        frame = first_replace(frame, status=(frame.status & 27) | (0 if flag & 2 else 4))
    return _position_order_carry(state, frame, frame.status & 15, True).frame


