def execute_ranked_standard_action_fields(state: SceneState, frame: FirstDeploymentFrame, mode: int, complete: bool=False) -> StandardPositionOrderFields:
    """One ranked action flow; five closed original plans retain their actual call sites."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('current action fields and actual completeness selector required')
    frame.validate(state, complete)
    from .services import BattlePolicyMemory, sample_battle_action_random_fields, select_strongest_type6_candidate_fields, compute_type6_budget_from_random_state_fields, select_strongest_open_terrain_candidate_second_side_fields, compute_candidate_budget_base20_fields, compute_candidate_budget_base30_fields
    memory = BattlePolicyMemory(state)
    uint(mode, 16)
    if mode == 3:
        random_return, selection_return, budget_return = (157406, 157428, 157442)
        battle_return, message_return, message_id = (157476, 157502, 299)
        candidate_selector = select_strongest_type6_candidate_fields
        budget_selector = compute_type6_budget_from_random_state_fields
        order_mode = 3
    elif mode == 0:
        random_return, selection_return, budget_return = (157666, 157688, 157702)
        battle_return, message_return, message_id = (157734, 157760, 296)
        candidate_selector = select_strongest_open_terrain_candidate_second_side_fields
        budget_selector = compute_candidate_budget_base20_fields
        order_mode = 0
    elif mode == 2:
        random_return, selection_return, budget_return = (157950, 157972, 157986)
        battle_return, message_return, message_id = (158020, 158046, 298)
        candidate_selector = select_strongest_open_terrain_candidate_second_side_fields
        budget_selector = compute_candidate_budget_base30_fields
        order_mode = 2
    elif mode == 1:
        random_return, selection_return, budget_return = (0x269AC, 0x269C2, 0x269D0)
        battle_return, message_return, message_id = (0x269F2, 0x26A0C, 301)
        candidate_selector = select_strongest_type1_candidate_second_side_fields
        budget_selector = compute_type1_candidate_budget_base20_fields
        order_mode = 5
    elif mode == 4:
        random_return, selection_return, budget_return = (0x26AB2, 0x26AD0, 0x26ADE)
        battle_return, message_return, message_id = (0x26B00, 0x26B1A, 297)
        candidate_selector = select_strongest_type2_candidate_with_map_context_fields
        budget_selector = compute_type2_candidate_budget_base30_fields
        order_mode = 1
    else:
        raise ValueError('only the five original ranked standard-action plans are admitted')
    frame = sample_battle_action_random_fields(memory, frame, random_return)
    value = frame.target_x & 65535
    frame = first_replace(frame, target_x=value, status=frame.status & 16 | (4 if value == 0 else 0))
    value = u32(value << 2)
    frame = first_replace(frame, target_x=value, status=(8 if value & 2147483648 else 0) | (4 if value == 0 else 0))
    value = swap_words(value)
    frame = first_replace(frame, target_x=value, status=(8 if value & 2147483648 else 0) | (4 if value == 0 else 0))
    frame = _standard_order_compare(frame, low16(value), 3)
    if low16(value) == 3:
        return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)
    if mode == 4:
        entered = _standard_order_enter(frame, 0x26AC8) if frame.stack_cursor is not None else frame
        frame = test_actor_map_relative_types_fields(memory, entered)
        if frame.stack_cursor is not None:
            frame = _standard_order_leave(frame, 0x26AC8)
        if frame.status is None:
            raise Boundary('actual actor terrain gate did not observe its CCR')
        if frame.status & 1:
            return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)
    entered = _standard_order_enter(frame, selection_return) if frame.stack_cursor is not None else frame
    frame = candidate_selector(memory, entered)
    if frame.stack_cursor is not None:
        frame = _standard_order_leave(frame, selection_return)
    if frame.status is None:
        raise Boundary('legacy ranked selection did not observe its current CCR')
    uint(frame.offset_x, 32)
    selected = low16(frame.offset_x)
    frame = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))
    if selected & 32768:
        return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)
    state.write(4294964134, 2, selected)
    frame = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))
    entered = _standard_order_enter(frame, budget_return) if frame.stack_cursor is not None else frame
    frame = budget_selector(memory, entered)
    if frame.stack_cursor is not None:
        frame = _standard_order_leave(frame, budget_return)
    ceiling = state.read(4294964886, 4)
    left = frame.unit
    compared = u32(left - ceiling)
    flags = (1 if left < ceiling else 0) | (8 if compared & 2147483648 else 0) | (4 if compared == 0 else 0) | (2 if (left ^ ceiling) & (left ^ compared) & 2147483648 else 0)
    frame = first_replace(frame, status=frame.status & 16 | flags)
    if left > ceiling:
        return _position_order_carry(state, frame, flags, False).validate(state, complete)
    orders = state.table_at(4294944596).cursor()
    frame = first_replace(frame, roster=orders)
    uint(frame.choice, 32)
    actor = low16(frame.choice)
    orders.set_byte(actor, 3)
    frame = first_replace(frame, status=frame.status & 16)
    state.write(4294964210, 2, actor)
    frame = first_replace(frame, status=frame.status & 16 | (8 if actor & 32768 else 0) | (4 if actor == 0 else 0))
    if order_mode == 0:
        state.read(4294964948, 2)
    state.write(4294964948, 2, order_mode)
    frame = first_replace(frame, status=frame.status & 16 | (4 if order_mode == 0 else 0))
    frame = _standard_action_call_fields(state, frame, 107642, battle_return, complete)
    if frame.status is None:
        raise Boundary('actual battle presentation carry has not been observed')
    if not frame.status & 1:
        side = state.read(4294964951, 1)
        state.write(4294964951, 1, side ^ 2)
        frame = first_replace(frame, status=frame.status & 27 | (0 if side & 2 else 4))
        selected = state.read(4294964134, 2)
        state.write(4294964176, 2, selected)
        frame = first_replace(frame, status=frame.status & 16 | (8 if selected & 32768 else 0) | (4 if selected == 0 else 0))
        state.write(4294965056, 2, message_id)
        frame = first_replace(frame, status=frame.status & 16)
        frame = _standard_action_call_fields(state, frame, 155876, message_return, complete)
        if frame.status is None:
            raise Boundary('actual battle message fields have not returned')
        side = state.read(4294964951, 1)
        state.write(4294964951, 1, side ^ 2)
        frame = first_replace(frame, status=frame.status & 27 | (0 if side & 2 else 4))
    return _position_order_carry(state, frame, frame.status & 15, True).validate(state, complete)


def _position_strategy_status(state: SceneState, frame: FirstDeploymentFrame,
        value, width: int, carry: bool = False, overflow: bool = False,
        extend: bool | None = None) -> FirstDeploymentFrame:
    """Publish only actual flags; an old unobserved X remains unobserved."""
    from ..high_level_battle_ai.business_geometry import _contact_status
    frame = _contact_status(frame, value, width, carry, overflow, extend)
    flags = int(carry) | (2 if overflow else 0) | (4 if value == 0 else 0) | (8 if value & (1 << (width - 1)) else 0)
    state.sr = ((state.sr & 65520) | flags) if frame.status is None else ((state.sr & 65504) | frame.status)
    return frame


def _position_strategy_move(state: SceneState, frame: FirstDeploymentFrame,
        name, value, width: int = 16) -> FirstDeploymentFrame:
    frame = _position_order_move(frame, name, value, width)
    return _position_strategy_status(state, frame, value, width)


def _position_strategy_done(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool) -> StandardPositionOrderFields:
    if frame.status is not None:
        state.sr = (state.sr & 65504) | frame.status
    return StandardPositionOrderFields(frame, state.sr & 15).validate(state, complete)


def _position_strategy_actor_gate(state: SceneState, frame: FirstDeploymentFrame) -> tuple:
    """Shared three live BYTE gates; stop at the first actual nonzero flag."""
    actor = low16(frame.choice)
    for address, name in ((0xFFFFA654, 'roster'), (0xFF3CC2, 'roster'), (0xFF3DC2, 'candidates')):
        view = state.table_at(address).cursor()
        frame = first_replace(frame, **{name:view})
        active = view.byte(actor)
        frame = _position_strategy_status(state, frame, active, 8)
        if active != 0:
            return frame, False
    return frame, True


def _position_strategy_call_fields(state: SceneState, frame: FirstDeploymentFrame,
        target, continuation, complete: bool) -> FirstDeploymentFrame:
    """Actual direct child calls, with only the original caller-owned token."""
    from .services import BattlePolicyMemory
    from ..high_level_battle_ai.business_geometry import collect_contacts_in_speed_radius_fields
    from ..high_level_battle_ai.business_formation import (
        compare_actor_shifted_troop_word_to_weakest_contact_fields,
        read_outer_east_staging_anchor_fields,
        select_contact_nearest_deployment_anchor_fields,
        read_formation_relative_position_delta_fields, first_deployment_random_fields,
        read_second_side_staging_anchor_fields, test_second_side_relative_total_shortfall_fields,
        choose_east_center_first_formation_point_fields, choose_west_center_first_formation_point_fields,
        choose_east_flank_first_formation_point_fields, choose_lower_center_first_formation_point_fields,
        read_first_side_staging_anchor_fields,
        choose_east_center_third_formation_point_fields,
        choose_west_center_third_formation_point_fields,
        choose_west_flank_third_formation_point_fields,
        choose_upper_center_third_formation_point_fields,
        read_outer_west_staging_anchor_fields,
        test_first_side_relative_total_shortfall_fields,
        test_second_roster_type6_count_below_four_fields,
        test_second_side_threshold_shortfall_fields,

        choose_east_center_second_formation_point_fields,
        choose_west_center_second_formation_point_fields,
        choose_west_flank_second_formation_point_fields,
        choose_upper_center_second_formation_point_fields,

        test_point_in_battlefield_staging_rectangle_fields,
        sample_battlefield_staging_rectangle_fields,
    )
    entered = _standard_order_enter(frame, continuation)
    if entered.status is not None:
        state.sr = (state.sr & 65504) | entered.status
    if not complete and any(value is None for value in (entered.target_x,
            entered.target_y, entered.unit, entered.count, entered.distance,
            entered.offset_x, entered.offset_y, entered.choice, entered.status)):
        raise Boundary('old position API lacks an actual child CCR or retained carrier; real return slot is already written')
    memory = BattlePolicyMemory(state)
    if target == 0x234D2:
        result = collect_contacts_in_speed_radius_fields(memory, entered).frame
    elif target == 0x243A0:
        result = compare_actor_shifted_troop_word_to_weakest_contact_fields(memory, entered)[0]
    elif target == 0x243DC:
        result = evaluate_selected_contact_position_fields(state, entered, complete).frame
    elif target == 0x2443E:
        result = read_outer_east_staging_anchor_fields(memory, entered)[0]
    elif target == 0x248D2:
        result = evaluate_nearest_anchor_contact_fields(state, entered, complete).frame
    elif target == 0x24926:
        result = select_contact_nearest_deployment_anchor_fields(memory, entered)[0]
    elif target == 0x24990:
        result = read_formation_relative_position_delta_fields(memory, entered)[0]
    elif target == 0x23B08:
        result = test_point_in_battlefield_staging_rectangle_fields(memory, entered)
    elif target == 0x23BA6:
        result = sample_battlefield_staging_rectangle_fields(memory, entered)
    elif target == 0x83D4:
        result = first_deployment_random_fields(memory, entered)
    elif target == 0x26560:
        result = execute_standard_action_chain_fields(state, entered, complete).frame
    elif target == 0x1DCAA:
        from .business_city import city_calculate_live_quotient_10_fields
        result = city_calculate_live_quotient_10_fields(memory, entered)
    elif target == 0x23C9A:
        result = test_second_side_relative_total_shortfall_fields(memory, entered)[0]
    elif target == 0x23C3E:
        result = evaluate_readiness_contact_action_fields(state, entered, complete).frame
    elif target == 0x23CE0:
        result = evaluate_second_staging_position_fields(state, entered, complete).frame
    elif target == 0x23D54:
        result = read_second_side_staging_anchor_fields(memory, entered)[0]
    elif target == 0x23BF4:
        result = read_first_side_staging_anchor_fields(memory, entered)[0]
    elif target == 0x23DC4:
        result = evaluate_first_region_position_fields(state, entered, complete).frame
    elif target == 0x23E68:
        result = choose_east_center_first_formation_point_fields(memory, entered)[0]
    elif target == 0x23EF2:
        result = choose_west_center_first_formation_point_fields(memory, entered)[0]
    elif target == 0x23F80:
        result = choose_east_flank_first_formation_point_fields(memory, entered)[0]
    elif target == 0x24048:
        result = choose_lower_center_first_formation_point_fields(memory, entered)[0]
    elif target == 0x240E4:
        result = evaluate_second_region_position_fields(state, entered, complete).frame
    elif target == 0x24188:
        result = choose_east_center_second_formation_point_fields(memory, entered)[0]
    elif target == 0x2419A:
        result = choose_west_center_second_formation_point_fields(memory, entered)[0]
    elif target == 0x241AE:
        result = choose_west_flank_second_formation_point_fields(memory, entered)[0]
    elif target == 0x24278:
        result = choose_upper_center_second_formation_point_fields(memory, entered)[0]
    elif target == 0x2456E:
        result = choose_east_center_third_formation_point_fields(memory, entered)[0]
    elif target == 0x24580:
        result = choose_west_center_third_formation_point_fields(memory, entered)[0]
    elif target == 0x24594:
        result = choose_west_flank_third_formation_point_fields(memory, entered)[0]
    elif target == 0x245BA:
        result = choose_upper_center_third_formation_point_fields(memory, entered)[0]
    elif target == 0x2467E:
        result = read_outer_west_staging_anchor_fields(memory, entered)[0]
    elif target == 0x24A14:
        result = test_first_side_relative_total_shortfall_fields(memory, entered)[0]
    elif target == 0x24A36:
        result = test_second_roster_type6_count_below_four_fields(memory, entered)[0]
    elif target == 0x24AB6:
        result = test_second_side_threshold_shortfall_fields(memory, entered)[0]
    elif target == 0x23A94:
        result = evaluate_first_staging_position_fields(state, entered, complete).frame
    elif target == 0x244AE:
        result = evaluate_third_region_contact_position_fields(state, entered, complete).frame
    elif target == 0x245F2:
        result = evaluate_west_contact_position_fields(state, entered, complete).frame
    elif target == 0x24AAC:
        result = evaluate_alternate_anchor_position_order_fields(state, entered, complete).frame
    else:
        result = call_target(state, target, entered)
    if type(result) is not FirstDeploymentFrame:
        raise Boundary('position child requires its actual current retained fields')
    result.validate(state, complete)
    returned = _standard_order_leave(result, continuation)
    if returned.status is not None:
        state.sr = (state.sr & 65504) | returned.status
    return returned


def _commit_contact_position_fields(state: SceneState, frame: FirstDeploymentFrame,
        vertical, continuation, complete: bool, horizontal = 'unit') -> StandardPositionOrderFields:
    """One original target/AE28 commit; the1DCAA result is not forced to carry."""
    if horizontal not in ('unit', 'count'):
        raise ValueError('actual target horizontal carrier required')
    targets = state.table_at(0xFF2C00).cursor()
    frame = first_replace(frame, roster=targets)
    frame = _position_strategy_move(state, frame, 'target_y', low16(frame.choice))
    frame = _position_order_shift(frame, 'target_y', 2)
    offset = low16(frame.target_y)
    frame = _position_order_shift(frame, horizontal, 7, True)
    targets.set_word(offset, low16(frame.carrier(horizontal)))
    frame = _position_strategy_status(state, frame, low16(frame.carrier(horizontal)), 16)
    frame = _position_order_shift(frame, vertical, 7, True)
    targets.set_word(offset, low16(frame.carrier(vertical)), 2)
    frame = _position_strategy_status(state, frame, low16(frame.carrier(vertical)), 16)
    submitted = state.table_at(0xFFFFAE28).cursor()
    frame = first_replace(frame, roster=submitted)
    submitted.set_byte(low16(frame.choice), 1)
    frame = _position_strategy_status(state, frame, 1, 8)
    frame = _position_strategy_call_fields(state, frame, 0x1DCAA, continuation, complete)
    return _position_strategy_done(state, frame, complete)


def evaluate_contact_position_order_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """Original24314 entry projects the unique contact/staging core."""
    return _evaluate_contact_staging_position_fields(state, frame, 1, complete)


def _evaluate_position_contact_response_fields(state: SceneState, frame: FirstDeploymentFrame,
        nearest: bool, complete: bool) -> StandardPositionOrderFields:
    """One70/90 readiness gate; each caller keeps its own original continuation."""
    from ..high_level_battle_ai.business_formation import _first_add_word
    if type(nearest) is not bool or type(complete) is not bool:
        raise ValueError('actual response route and completeness selectors required')
    frame.validate(state, complete)
    readiness_table = state.table_at(0xFFFFB600).cursor()
    frame = first_replace(frame, roster=readiness_table)
    actor = low16(frame.choice)
    frame = _position_strategy_move(state, frame, 'target_x', actor)
    frame = _position_order_shift(frame, 'target_x', 1)
    readiness = readiness_table.word(low16(frame.target_x))
    frame = _position_strategy_move(state, frame, 'target_y', readiness)
    frame = _position_strategy_move(state, frame, 'unit', 0)
    frame = _standard_order_compare(frame, readiness, 70)
    if readiness >= 70:
        frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)
        frame = _standard_order_compare(frame, readiness, 90)
        if readiness >= 90:
            frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)
    frame = _position_strategy_call_fields(state, frame, 0x83D4,
        0x248FA if nearest else 0x24404, complete)
    sample = low16(frame.target_x)
    frame = first_replace(frame, target_x=sample)
    frame = _position_strategy_status(state, frame, sample, 32)
    shifted = u32(sample << 2)
    frame = first_replace(frame, target_x=shifted)
    frame = _position_strategy_status(state, frame, shifted, 32, False, False, False)
    swapped = swap_words(shifted)
    frame = first_replace(frame, target_x=swapped)
    frame = _position_strategy_status(state, frame, swapped, 32)
    frame = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))
    if low16(frame.target_x) < low16(frame.unit):
        frame = _position_strategy_call_fields(state, frame, 0x26560,
            0x2490E if nearest else 0x24418, complete)
        if frame.status & 1:
            return _position_strategy_done(state, frame, complete)
    if nearest:
        frame = _position_strategy_call_fields(state, frame, 0x24926, 0x24916, complete)
        frame = _position_order_shift(frame, 'target_y', 2)
        offset = low16(frame.target_y)
        frame = _position_strategy_move(state, frame, 'unit', frame.roster.word(offset))
        frame = _position_strategy_move(state, frame, 'count', frame.roster.word(offset, 2))
    else:
        frame = first_replace(frame, candidates=state.table_at(0xFF2C00).cursor())
        frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
        frame = _position_order_shift(frame, 'target_x', 2)
        frame = first_replace(frame, roster=state.table_at(0xFFFFA150).cursor())
        selected = state.read(0xFFFFF3A6, 2)
        frame = _position_strategy_move(state, frame, 'count', selected)
        frame = _position_order_shift(frame, 'count', 2)
        offset = low16(frame.count)
        frame = _position_strategy_move(state, frame, 'unit', frame.roster.word(offset))
        frame = _position_strategy_move(state, frame, 'distance', frame.roster.word(offset, 2))
    return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)


def evaluate_selected_contact_position_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed243DC..2443E: selected contact or real action response."""
    return _evaluate_position_contact_response_fields(state, frame, False, complete)


def evaluate_nearest_anchor_contact_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed248D2..24926: nearest anchor contact or real action response."""
    return _evaluate_position_contact_response_fields(state, frame, True, complete)


def _evaluate_anchor_position_body_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool) -> StandardPositionOrderFields:
    """Unique2483A tail for normal and alternate packed-destination inputs."""
    frame, allowed = _position_strategy_actor_gate(state, frame)
    if not allowed:
        return _position_strategy_done(state, frame, complete)
    stack = frame.stack_cursor.advance(-2)
    stack.set_word(0, low16(frame.unit))
    frame = first_replace(frame, stack_cursor=stack)
    frame = _position_strategy_call_fields(state, frame, 0x234D2, 0x24868, complete)
    stack = frame.stack_cursor
    packed = stack.word()
    frame = first_replace(frame, stack_cursor=stack.advance(2))
    frame = _position_strategy_move(state, frame, 'unit', packed)
    contacts = state.read(0xFFFFD300, 2)
    frame = _position_strategy_status(state, frame, contacts, 16)
    if not contacts & 32768:
        frame = _position_strategy_call_fields(state, frame, 0x248D2, 0x24876, complete)
        if frame.status & 1:
            return _position_strategy_done(state, frame, complete)
    else:
        frame = _position_strategy_call_fields(state, frame, 0x24990, 0x24882, complete)
        positions = state.table_at(0xFFFFA150).cursor()
        frame = first_replace(frame, roster=positions)
        frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
        frame = _position_order_shift(frame, 'target_x', 2)
        offset = low16(frame.target_x)
        frame = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))
        frame = _position_strategy_move(state, frame, 'target_x', positions.word(offset))
        frame = _position_strategy_move(state, frame, 'count', low16(frame.unit))
        masked = low16(frame.unit) & 65280
        frame = _position_strategy_move(state, frame, 'unit', masked)
        frame = _position_order_shift(frame, 'unit', 2)
        frame = _position_order_shift(frame, 'count', 7)
        frame = _position_order_shift(frame, 'count', 3)
        frame = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))
        if low16(frame.target_x) == low16(frame.unit):
            frame = _standard_order_compare(frame, low16(frame.target_y), low16(frame.count))
            if low16(frame.target_y) == low16(frame.count):
                return _position_strategy_done(state, frame, complete)
    return _commit_contact_position_fields(state, frame, 'count', 0x248D0, complete)


def evaluate_anchor_position_order_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed24834..248D2: contacts or formation-relative target update."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current position fields required')
    frame.validate(state, complete)
    frame = _position_strategy_move(state, frame, 'unit', state.read(0xFF3ECA, 2))
    return _evaluate_anchor_position_body_fields(state, frame, complete)


def evaluate_alternate_anchor_position_order_fields(state: SceneState,
        frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """confirmed24AAC..24AB6: alternate WORD read then BRA2483A, no extra call."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current alternate fields required')
    frame.validate(state, complete)
    frame = _position_strategy_move(state, frame, 'unit', state.read(0xFF3ECC, 2))
    return _evaluate_anchor_position_body_fields(state, frame, complete)


def evaluate_readiness_contact_action_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed23C3E..23C9A:50/70/90 readiness, real RNG, contacts then action."""
    from ..high_level_battle_ai.business_formation import _first_add_word
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('actual readiness-action fields required')
    frame.validate(state, complete)
    readiness_table = state.table_at(0xFFFFB600).cursor()
    frame = first_replace(frame, roster=readiness_table)
    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
    frame = _position_order_shift(frame, 'target_x', 1)
    frame = _position_strategy_move(state, frame, 'unit', 0)
    readiness = readiness_table.word(low16(frame.target_x))
    frame = _position_strategy_move(state, frame, 'target_y', readiness)
    for threshold in (50, 70, 90):
        frame = _standard_order_compare(frame, readiness, threshold)
        if readiness < threshold:
            break
        frame = _first_add_word(frame, 'unit', low16(frame.unit), 1)
    frame = _position_strategy_call_fields(state, frame, 0x83D4, 0x23C70, complete)
    sample = low16(frame.target_x)
    frame = first_replace(frame, target_x=sample)
    frame = _position_strategy_status(state, frame, sample, 32)
    shifted = u32(sample << 2)
    frame = first_replace(frame, target_x=shifted)
    frame = _position_strategy_status(state, frame, shifted, 32, False, False, False)
    swapped = swap_words(shifted)
    frame = first_replace(frame, target_x=swapped)
    frame = _position_strategy_status(state, frame, swapped, 32)
    frame = _standard_order_compare(frame, low16(frame.target_x), low16(frame.unit))
    if low16(frame.target_x) < low16(frame.unit):
        frame = _position_strategy_call_fields(state, frame, 0x234D2, 0x23C84, complete)
        first = state.read(0xFFFFD300, 2)
        frame = _position_strategy_status(state, frame, first, 16)
        if not first & 32768:
            frame = _position_strategy_call_fields(state, frame, 0x26560, 0x23C90, complete)
            return _position_strategy_done(state, frame, complete)
    return _position_order_carry(state, frame, frame.status & 15, False).validate(state, complete)


def _secondary_staging_policy_route_fields(state: SceneState, frame: FirstDeploymentFrame,
        target, continuation = None) -> FirstDeploymentFrame:
    """Actual fields project existing cores;24816/242F6 tails add no slot.

    This adapter has no retreat/trigger algorithm or copied State. The known
   23736/22756 callers continue to own their real outer return slots.
    """
    from ..high_level_main_flows.contexts_gameplay import BattlePolicy
    from ..high_level_main_flows.business_gameplay import (
        _primary_city_rectangle_call, _primary_other_city_retreat_call,
        _primary_retreat_mark_call, _primary_short_roster_tail,
        _primary_low_strength_fallback_tail, _primary_small_force_tail, _battle_policy_retained_frame,
    )
    frame.validate(state, True)
    state.sr = (state.sr & 65504) | frame.status
    policy = BattlePolicy(target_x=frame.target_x, target_y=frame.target_y,
        unit=frame.unit, count=frame.count, distance=frame.distance,
        offset_x=frame.offset_x, offset_y=frame.offset_y, choice=frame.choice,
        roster=frame.roster, candidates=frame.candidates, controller=frame.controller,
        scan=frame.scan, opponent=frame.opponent, scratch=frame.scratch,
        auxiliary=frame.auxiliary, stack_cursor=frame.stack_cursor).validate(state)
    if target == 0x23736:
        uint(continuation, 32)
        returned = _primary_city_rectangle_call(state, policy, continuation)
    elif target == 0x22756:
        uint(continuation, 32)
        returned = _primary_other_city_retreat_call(state, policy, continuation)
    elif target == 0x24816:
        if continuation is not None:
            raise ValueError('original BCS24816 has no additional continuation')
        returned = _primary_low_strength_fallback_tail(state, policy)
    elif target == 0x242F6:
        if continuation is not None:
            raise ValueError('original strategy5 fallthrough adds no continuation')
        returned = _primary_small_force_tail(state, policy)
    elif target == 0x22D30:
        uint(continuation, 32)
        returned = _primary_retreat_mark_call(state, policy, continuation)
    elif target == 0x23A76:
        if continuation is not None:
            raise ValueError('original23A76 branch adds no call slot')
        returned = _primary_short_roster_tail(state, policy)
    else:
        raise ValueError('only the actual existing staging policy routes are admitted')
    return _battle_policy_retained_frame(state, returned)


def evaluate_guarded_second_staging_order_fields(state: SceneState,
        frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """23CBC and its23CC2 branch entry now share the single attempt core."""
