def evaluate_second_staging_position_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed23CE0..23D54: second-side staging point or original sample."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current staging-position fields required')
    frame.validate(state, complete)
    frame, allowed = _position_strategy_actor_gate(state, frame)
    if not allowed:
        return _position_strategy_done(state, frame, complete)
    positions = state.table_at(0xFFFFA150).cursor()
    frame = first_replace(frame, roster=positions)
    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
    frame = _position_order_shift(frame, 'target_x', 2)
    offset = low16(frame.target_x)
    frame = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))
    frame = _position_strategy_move(state, frame, 'target_x', positions.word(offset))
    frame = _position_strategy_call_fields(state, frame, 0x23B08, 0x23D1C, complete)
    if frame.status & 1:
        frame = _position_strategy_call_fields(state, frame, 0x23D54, 0x23D2C, complete)
    else:
        frame = _position_strategy_call_fields(state, frame, 0x23BA6, 0x23D24, complete)
    return _commit_contact_position_fields(state, frame, 'distance', 0x23D52, complete)


def evaluate_first_staging_position_fields(state: SceneState, frame: FirstDeploymentFrame,
        complete: bool = False) -> StandardPositionOrderFields:
    """confirmed 23A94..23B08: first-side staging point or rectangle sample.

    Preserve the three ordered actor gates, the live rectangle result and
    caller-owned return slots. Position commit and city calculation share
    their existing cores; the final carry is the actual city return.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('sole current first-staging fields required')
    frame.validate(state, complete)
    frame, allowed = _position_strategy_actor_gate(state, frame)
    if not allowed:
        return _position_strategy_done(state, frame, complete)
    positions = state.table_at(0xFFFFA150).cursor()
    frame = first_replace(frame, roster=positions)
    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
    frame = _position_order_shift(frame, 'target_x', 2)
    offset = low16(frame.target_x)
    frame = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))
    frame = _position_strategy_move(state, frame, 'target_x', positions.word(offset))
    frame = _position_strategy_call_fields(state, frame, 0x23B08, 0x23AD0, complete)
    if frame.status & 1:
        frame = _position_strategy_call_fields(state, frame, 0x23BF4, 0x23AE0, complete)
    else:
        frame = _position_strategy_call_fields(state, frame, 0x23BA6, 0x23AD8, complete)
    return _commit_contact_position_fields(state, frame, 'distance', 0x23B06, complete)


# Indexed order3 reuses one first-region selector and current policy routes.
def evaluate_guarded_first_region_order_fields(state: SceneState,
        frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """confirmed23D9E..23DC4: indexed strategy3, existing four service routes."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('actual first-region order fields required')
    frame.validate(state, complete)
    frame = _position_strategy_call_fields(state, frame, 0x23C9A, 0x23DA2, complete)
    if frame.status & 1:
        frame = _secondary_staging_policy_route_fields(state, frame, 0x24816)
        return _position_strategy_done(state, frame, complete)
    frame = _secondary_staging_policy_route_fields(state, frame, 0x23736, 0x23DAA)
    if frame.status & 1:
        return _position_strategy_done(state, frame, complete)
    frame = _secondary_staging_policy_route_fields(state, frame, 0x22756, 0x23DB2)
    if frame.status & 1:
        return _position_strategy_done(state, frame, complete)
    frame = _position_strategy_call_fields(state, frame, 0x23C3E, 0x23DBA, complete)
    if frame.status & 1:
        return _position_strategy_done(state, frame, complete)
    frame = _position_strategy_call_fields(state, frame, 0x23DC4, 0x23DC2, complete)
    return _position_strategy_done(state, frame, complete)


