# Actual late indexed deployment entries: one shared core per responsibility.
def _evaluate_guarded_deployment_attempts_fields(state: SceneState,
        frame: FirstDeploymentFrame, family: int, complete: bool,
        skip_gate: bool = False) -> StandardPositionOrderFields:
    """One ordered policy-attempt chain; branch entries do not add a slot.

    Family2 preserves23CBC/23CC2. Families6/7/8 are24488/245CC/246C8;
    their third attempt is original22D30 rather than the readiness service.
    """
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool or type(skip_gate) is not bool:
        raise ValueError('actual deployment fields, entry and completeness required')
    frame.validate(state, complete)
    if family == 2:
        gate_return, tries = 0x23CBE, ((0x23736, 0x23CC6), (0x22756, 0x23CCE), (0x23C3E, 0x23CD6), (0x23CE0, 0x23CDE))
    elif family == 6:
        gate_return, tries = 0x2448C, ((0x23736, 0x24494), (0x22756, 0x2449C), (0x22D30, 0x244A4), (0x244AE, 0x244AC))
    elif family == 7:
        gate_return, tries = 0x245D0, ((0x23736, 0x245D8), (0x22756, 0x245E0), (0x22D30, 0x245E8), (0x245F2, 0x245F0))
    elif family == 8:
        gate_return, tries = 0x246CC, ((0x23736, 0x246D4), (0x22756, 0x246DC), (0x22D30, 0x246E4), (0x23A94, 0x246EC))
    else:
        raise ValueError('only the actual connected deployment families required')
    if not skip_gate:
        frame = _position_strategy_call_fields(state, frame, 0x23C9A, gate_return, complete)
        if frame.status & 1:
            frame = _secondary_staging_policy_route_fields(state, frame, 0x24816)
            return _position_strategy_done(state, frame, complete)
    for target, continuation in tries:
        if target in (0x23736, 0x22756, 0x22D30):
            frame = _secondary_staging_policy_route_fields(state, frame, target, continuation)
        else:
            frame = _position_strategy_call_fields(state, frame, target, continuation, complete)
        if frame.status & 1:
            break
    return _position_strategy_done(state, frame, complete)

