def evaluate_third_region_contact_position_fields(state: SceneState,
        frame: FirstDeploymentFrame, complete: bool = False) -> StandardPositionOrderFields:
    """confirmed244AE..2456E: pursue contact, otherwise third region point."""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame or type(complete) is not bool:
        raise ValueError('actual third-region contact fields required')
    frame.validate(state, complete)
    frame, allowed = _position_strategy_actor_gate(state, frame)
    if not allowed:
        return _position_strategy_done(state, frame, complete)
    positions = state.table_at(0xFFFFA150).cursor()
    frame = first_replace(frame, roster=positions)
    frame = _position_strategy_move(state, frame, 'target_x', low16(frame.choice))
    frame = _position_order_shift(frame, 'target_x', 2)
    offset = low16(frame.target_x)
    frame = _position_strategy_move(state, frame, 'target_y', positions.word(offset, 2))
    frame = _position_strategy_move(state, frame, 'target_x', positions.word(offset))
    frame = _position_strategy_call_fields(state, frame, 0x243A0, 0x244EA, complete)
    if frame.status & 1:
        selected = low16(frame.count)
        state.write(0xFFFFF3A6, 2, selected)
        frame = _position_strategy_status(state, frame, selected, 16)
        frame = _position_strategy_call_fields(state, frame, 0x243DC, 0x244F6, complete)
        if frame.status & 1:
            return _position_strategy_done(state, frame, complete)
        frame = _position_strategy_move(state, frame, 'count', low16(frame.unit))
        frame = _position_strategy_move(state, frame, 'offset_x', low16(frame.distance))
    else:
        frame = _select_region_position_fields(state, frame, 3, complete)
    return _commit_contact_position_fields(state, frame, 'offset_x', 0x2456C, complete, 'count')

