# C53 named Scene presentation roles; true hardware/callee boundaries retained.
def _highbank_story_legacy_entry_fields(state: SceneState, inputs, frame,
        observed: tuple, target: int) -> FirstDeploymentFrame:
    """The historical DTO carries only some registers and four flags, never A7/X.

    An explicit genuine frame is therefore required. Known DTO observations
    must agree with it; no zero or Python register snapshot supplies the gaps.
    """
    from ..high_level_scene_flows.contexts_scene import SceneRefreshMemory
    checked_state(state)
    if frame is None:
        raise Boundary('historical Scene presentation input lacks complete D/A/SR-X/SP; supply entry_frame')
    memory = SceneRefreshMemory(state)
    memory.frame(frame)
    if frame.stack_cursor is None:
        raise Boundary('complete Scene presentation entry_frame requires actual A7; no synthetic stack')
    roles = {'value':'target_x','field':'target_y','tile':'unit','row':'count',
        'offset':'distance','limit':'offset_x','member':'offset_y','remaining':'choice',
        'destination':'roster','source':'candidates','descriptor':'controller',
        'roster':'scratch','port':'auxiliary'}
    conditions = {'carry':1,'overflow':2,'zero':4,'negative':8}
    pointers = ('destination','source','descriptor','roster','port')
    for name in observed:
        actual = getattr(inputs,name)
        if name in conditions:
            if actual != bool(frame.status & conditions[name]):
                raise ValueError('historical CCR observation conflicts with entry_frame')
        elif name in pointers:
            if actual is None or actual.base != getattr(frame,roles[name]).base:
                raise ValueError('historical address observation conflicts with entry_frame')
        elif actual != frame.carrier(roles[name]):
            raise ValueError('historical data observation conflicts with entry_frame')
    return memory.sync_status(frame)


