# Current full-frame command/scenario successors, original whole bodies preserved.
"""Current Scene successor for scenario policy, leader choice and text packets.

Original whole owners 66C28..676C4, with foreign gaps excluded by source_scope.
The old public facades will project this one implementation. This is not a
device emulator: real unknown services retain their physical call boundary.
"""
from ..high_level_main_flows.business_movement_support import (
    _movement_binary_flags, _movement_fixed_shift_word)
from .business_city import (_settlement_store_word_fields,
    _settlement_write_byte_fields, execute_deployment_menu_fields)


def _command_policy_store_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        address: int, value: int, clear: bool=False) -> FirstDeploymentFrame:
    """Live WORD store, including the original CLR destination read."""
    return _settlement_store_word_fields(state, frame, state.table_at(address), 0, value, clear=clear)


def _command_policy_change_memory_fields(state: SceneState, frame: FirstDeploymentFrame,
        address: int, amount: int, width: int=16) -> FirstDeploymentFrame:
    """Actual memory RMW; arithmetic and X come from the existing sole kernel."""
    if width not in (8, 16):
        raise ValueError('actual command BYTE/WORD memory arithmetic required')
    old = state.read(address, width // 8)
    frame, changed = _movement_binary_flags(state, frame, old, -amount if amount < 0 else amount, width, amount < 0)
    state.write(address, width // 8, changed)
    return frame


def _command_policy_bit_fields(state: SceneState, frame: FirstDeploymentFrame,
        address: int, bit: int) -> FirstDeploymentFrame:
    """Memory BYTE BTST projects the shared sole Z-only flag primitive."""
    if (address, bit) not in ((0xFFFFF603, 5), (0xFFFFF3A4, 2)):
        raise ValueError('actual scenario policy flag role required')
    value = state.read(address, 1)
    frame = _postbattle_bit_fields(frame, bool(value & (1 << bit)))
    state.sr = (state.sr & 65504) | frame.status
    return frame


def _command_policy_store_long_fields(state: SceneState, frame: FirstDeploymentFrame,
        address: int, value: int, clear: bool=False) -> FirstDeploymentFrame:
    """Packet-pointer and summary-buffer LONG MOVE/CLR, with live observations."""
    if clear:
        state.read(address, 4)
    state.write(address, 4, uint(value, 32))
    return _movement_test_long(state, frame, value)


def _command_policy_call_fields(state: SceneState, frame: FirstDeploymentFrame,
        target: int, continuation: int) -> FirstDeploymentFrame:
    """One real BSR/JSR return LONG; no Python-only callee success."""
    frame = _resource_cost_frame(state, frame, target)
    if target == 0x1A44E:
        from ..high_level_battle_ai.business_actions import _deployment_terrain_lookup
        result, category = _deployment_terrain_lookup(BattlePolicyMemory(state), frame,
            low16(frame.target_y), low16(frame.unit), continuation=continuation)
        return _resource_cost_frame(state, result, target)
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, uint(continuation, 32))
    entered = first_replace(frame, stack_cursor=stack)
    result = _command_policy_child_fields(state, entered, target)
    result = _resource_cost_frame(state, result, target)
    returned = result.stack_cursor.long()
    if returned != continuation:
        raise FirstDeploymentReturnBoundary(returned, result, continuation)
    return first_replace(result, stack_cursor=result.stack_cursor.advance(4))


def select_scenario_leader_message_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66C28: advance phase, resolve the selected force's head and queue label 98."""
    frame = _resource_cost_frame(state, frame, 0x66C28)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, low16(frame.target_x))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_x))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, state.read(0xFFFFEFB0, 2))
    frame = _movement_move(state, frame, 'target_x', 0x98, 16)
    return _command_policy_call_fields(state, frame, 0x676F2, 0x66C52)


def remove_scenario_selected_force_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66CD2: erase one of three live force slots, then return exact carry availability."""
    frame = _resource_cost_frame(state, frame, 0x66CD2)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    for address in (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E):
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)
        if frame.status & 4:
            frame = _command_policy_store_word_fields(state, frame, address, 0x80)
            break
    remaining = False
    for address in (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F):
        frame = _movement_test(state, frame, state.read(address, 1), 8)
        if not frame.status & 8:
            remaining = True
            break
    status = frame.status | 1 if remaining else frame.status & 30
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, status=status)


def confirm_scenario_force_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66C54: button confirmation counts attempts and removes an exhausted force slot."""
    frame = _resource_cost_frame(state, frame, 0x66C54)
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4:
        return frame
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    matched = False
    for address in (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E):
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)
        if frame.status & 4:
            matched = True
            break
    if not matched:
        return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 4)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF590).cursor())
    address = frame.roster.address(low16(frame.target_x))
    frame = _command_policy_change_memory_fields(state, frame, address, 1, 8)
    frame = _movement_compare(state, frame, frame.roster.byte(low16(frame.target_x)), 3, 8)
    if frame.status & 5:
        frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
        return _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xCC)
    frame = _command_policy_call_fields(state, frame, 0x66CD2, 0x66CAC)
    if not frame.status & 1:
        return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 7)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 11)
    frame = _movement_move(state, frame, 'target_x', 0x98, 16)
    return _command_policy_call_fields(state, frame, 0x676F2, 0x66CD0)


def advance_scenario_force_result_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66D2E: move to the next phase or consume an empty selected force."""
    frame = _resource_cost_frame(state, frame, 0x66D2E)
    frame = _movement_test(state, frame, state.read(0xFFFFF636, 2), 16)
    if not frame.status & 4:
        return _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_call_fields(state, frame, 0x66CD2, 0x66D38)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 6 if frame.status & 1 else 7)


def reset_scenario_force_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66D56: restore the selection phase and clear its two counters."""
    frame = _resource_cost_frame(state, frame, 0x66D56)
    for address, value in ((0xFFFFF38C, 0x80), (0xFFFFF612, 0x208), (0xFFFFF362, 4)):
        frame = _command_policy_store_word_fields(state, frame, address, value)
    for address in (0xFFFFF386, 0xFFFFF388):
        frame = _command_policy_store_word_fields(state, frame, address, 0, True)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF65A, 0x11)


def rank_scenario_force_leader_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66DC6: rank all affiliated members by class and loyalty, retaining the last DBRA WORD."""
    frame = _resource_cost_frame(state, frame, 0x66DC6)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'distance', 2, 16)
    frame = _movement_move(state, frame, 'unit', 65535, 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor(),
        candidates=state.table_at(0xFFFFCC00).cursor(), controller=state.table_at(0xFFFFC700),
        scan=state.table_at(0xFFFFC300).cursor())
    frame = _movement_move(state, frame, 'count', 255, 16)
    while True:
        index = low16(frame.count)
        frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(index), 8)
        if not frame.status & 12:
            frame = _movement_move(state, frame, 'offset_x', low16(frame.offset_x) & 63, 16)
            frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.offset_x)), 8)
            if frame.status & 4:
                frame = _movement_move(state, frame, 'offset_y', 5, 16)
                frame = _movement_move(state, frame, 'choice', frame.scan.byte(index), 8)
                frame = _movement_compare(state, frame, low8(frame.choice), 90, 8)
                evaluate = not frame.status & 1
                if not evaluate:
                    frame = _movement_compare(state, frame, low8(frame.choice), 80, 8)
                    if not frame.status & 1:
                        frame = _movement_move(state, frame, 'offset_y', frame.controller.byte(index), 8)
                        frame = _movement_move(state, frame, 'offset_y', low16(frame.offset_y) & 7, 16)
                        frame = _movement_compare(state, frame, low16(frame.offset_y), low16(frame.distance), 16)
                        if not frame.status & 1:
                            evaluate = not frame.status & 4
                            if not evaluate:
                                frame = _movement_compare(state, frame, low8(frame.choice), low8(frame.target_y), 8)
                                evaluate = not frame.status & 5
                else:
                    # The >=90 branch skips the class comparison and lands at 66E2A.
                    frame = _movement_compare(state, frame, low8(frame.choice), low8(frame.target_y), 8)
                    evaluate = not frame.status & 5
                if evaluate:
                    frame = _movement_move(state, frame, 'target_y', low8(frame.choice), 8)
                    frame = _movement_move(state, frame, 'distance', low16(frame.offset_y), 16)
                    frame = _movement_move(state, frame, 'unit', index, 16)
        frame = first_replace(frame, count=replace_word(frame.count, u16(index - 1)))
        if low16(frame.count) == 65535:
            return frame


def commit_scenario_force_leader_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66E3C: commit the chosen head, reciprocal affiliation and initial leader class."""
    frame = _resource_cost_frame(state, frame, 0x66E3C)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), low16(frame.unit))
    frame = first_replace(frame, roster=state.table_at(0xFFFFF45E).cursor(), candidates=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.candidates.byte(low16(frame.unit)), 8)
    frame = _movement_compare(state, frame, low16(frame.target_y), 41, 16)
    if frame.status & 5:
        frame = _movement_fixed_shift_word(state, frame, 'target_y', 1)
        frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_y), low16(frame.unit))
    frame = first_replace(frame, roster=state.table_at(0xFFFFC300).cursor())
    frame = _settlement_write_byte_fields(state, frame, frame.roster, 100, low16(frame.unit))
    frame = first_replace(frame, roster=state.table_at(0xFFFFC700).cursor())
    return _settlement_write_byte_fields(state, frame, frame.roster, 4, low16(frame.unit))


def replace_scenario_force_leader_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66D78: count replacement attempts, rank a new head and queue the change notice."""
    frame = _resource_cost_frame(state, frame, 0x66D78)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF590).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    address = frame.roster.address(low16(frame.target_x))
    frame = _command_policy_change_memory_fields(state, frame, address, 1, 8)
    frame = _movement_compare(state, frame, frame.roster.byte(low16(frame.target_x)), 3, 8)
    if not frame.status & 1:
        return _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_call_fields(state, frame, 0x66DC6, 0x66D92)
    frame = _movement_test(state, frame, low16(frame.unit), 16)
    if frame.status & 8:
        return _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_call_fields(state, frame, 0x66E3C, 0x66D9C)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D2, low16(frame.unit))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, state.read(0xFFFFF3A6, 2))
    frame = _movement_move(state, frame, 'target_x', 0xA4, 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 9)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)
    return _command_policy_call_fields(state, frame, 0x676F2, 0x66DBC)


def advance_scenario_head_failure_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66E7C: retain the selected old head and queue replacement-failure text."""
    frame = _resource_cost_frame(state, frame, 0x66E7C)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, state.read(0xFFFFF3A6, 2))
    frame = _movement_move(state, frame, 'target_x', 0xA5, 16)
    return _command_policy_call_fields(state, frame, 0x676F2, 0x66E90)


def initialize_scenario_result_delay_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66E92: begin the delayed result phase, with a real CLR read."""
    frame = _resource_cost_frame(state, frame, 0x66E92)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xD0)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, 0, True)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 9)


def build_scenario_summary_buffers_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66EAA: clear four live pages and construct the force-pair/turn summary."""
    frame = _resource_cost_frame(state, frame, 0x66EAA)
    frame = _movement_move(state, frame, 'target_x', 511, 16)
    frame = first_replace(frame, roster=state.table_at(0x00FF7000).cursor(),
        candidates=state.table_at(0x00FF7800).cursor(), controller=state.table_at(0xFFFF8000),
        scan=state.table_at(0xFFFF8800).cursor())
    while True:
        for name in ('roster', 'candidates', 'controller', 'scan'):
            view = frame.roster if name == 'roster' else frame.candidates if name == 'candidates' else frame.controller if name == 'controller' else frame.scan
            frame = _command_policy_store_long_fields(state, frame, view.address() if name != 'controller' else view.base, 0, True)
            following = state.table_at(u32(view.base + 4)) if name == 'controller' else view.advance(4)
            frame = first_replace(frame, **{name: following})
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    frame = _command_policy_store_word_fields(state, frame, 0xFFFF80DA, 3)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    for address in (0xFFFF80DC, 0xFFFF80DE):
        frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFA622, 2), 16)
    if frame.status & 8:
        frame = _command_policy_store_word_fields(state, frame, 0xFFFF80DA, 4)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFEFB0, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        for address in (0xFFFF80DC, 0xFFFF80DE, 0xFFFF80E0, 0xFFFF80E2):
            frame = _command_policy_store_word_fields(state, frame, address, frame.roster.word(low16(frame.target_x)))
    else:
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 255, 16)
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFEFB0, 2), 16)
        if frame.status & 4:
            frame = _movement_fixed_shift_word(state, frame, 'target_y', 8, True)
            frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
        for address in (0xFFFF80E0, 0xFFFF80E2):
            frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF374, 1), 8)
    frame = _movement_add_word(state, frame, 'target_x', 0xB8)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFF80E4, low16(frame.target_x))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF375, 1), 8)
    frame = _movement_adjust_word(state, frame, 'target_x', 1)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFF80E6, low16(frame.target_x))
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF352, 0, True)


def step_scenario_summary_palette_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66F78: advance the real palette fade only on even live scene ticks."""
    frame = _resource_cost_frame(state, frame, 0x66F78)
    frame = _movement_compare(state, frame, state.read(0xFFFFF352, 2), 16, 16)
    if not frame.status & 1:
        return _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xE0)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF352, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 64, 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFFB80).cursor())
    frame = _command_policy_call_fields(state, frame, 0xDEA6, 0x66F9E)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF320, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 1, 16)
    if frame.status & 4:
        frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF352, 1)
    return frame


def wait_scenario_result_confirmation_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66FB0: a finite per-tick button/countdown transition, not a hardware poll."""
    frame = _resource_cost_frame(state, frame, 0x66FB0)
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4:
        frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF608, -1)
        if not frame.status & 4:
            return frame
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3C2, 0x201)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, 0x208)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 19)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF36A, 0, True)


def accept_scenario_saved_confirmation_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """66FDA: restore the saved command pair when the confirmation button is set."""
    frame = _resource_cost_frame(state, frame, 0x66FDA)
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4:
        return frame
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3C2, state.read(0xFFFFF3DA, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3C4, state.read(0xFFFFF3DC, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, 0x208)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 19)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF376, 65534)


def advance_scenario_result_countdown_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """67004: decrement the result timer; a button can take the same phase transition."""
    frame = _resource_cost_frame(state, frame, 0x67004)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF608, -1)
    if not frame.status & 4:
        frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
        if frame.status & 4:
            return frame
    return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 6)


def restore_scenario_saved_command_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """6724E: the shared real tail of text packet helpers; no invented call slot."""
    frame = _resource_cost_frame(state, frame, 0x6724E)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, state.read(0xFFFFF3C2, 2))
    return _command_policy_store_word_fields(state, frame, 0xFFFFF362, state.read(0xFFFFF3C4, 2))


def toggle_scenario_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """6725C: XOR the live choice WORD and clear its companion counter."""
    frame = _resource_cost_frame(state, frame, 0x6725C)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF37A, state.read(0xFFFFF37A, 2) ^ 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF37C, 0, True)


def _scenario_numeric_text_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """6726C: shared alternate-entry numeric packet body, without a new call slot."""
    frame = _movement_move_long(state, frame, 'target_y', 0x4100)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = first_replace(frame, auxiliary=state.table_at(0xFFFFD300))
    frame = _command_policy_call_fields(state, frame, 0x1270A, 0x6727E)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFD30C, 0x800C)
    frame = first_replace(frame, auxiliary=state.table_at(0xFFFFD300))
    while True:
        frame = _movement_test(state, frame, frame.auxiliary.word(), 16)
        frame = first_replace(frame, auxiliary=frame.auxiliary.advance(2))
        if not frame.status & 4:
            break
    frame = first_replace(frame, auxiliary=frame.auxiliary.advance(-2))
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3D4, state.read(0xFFFFF3BE, 4))
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3BE, frame.auxiliary.base)
    return _command_policy_child_fields(state, frame, 0x671B6)


def compose_scenario_numeric_text_fields(state: SceneState, frame: FirstDeploymentFrame,
        entry: int=0x67268) -> FirstDeploymentFrame:
    """67268 and its three true alternate entries share one numeric packet core."""
    frame = _resource_cost_frame(state, frame, entry)
    if entry in (0x67268, 0x6729C):
        frame = _movement_move_long(state, frame, 'target_x', state.read(0xFFFFF3C8 if entry == 0x67268 else 0xFFFFF3CC, 4))
    elif entry in (0x67338, 0x67346):
        frame = _movement_move_long(state, frame, 'target_x', 0)
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF374 if entry == 0x67338 else 0xFFFFF375, 1), 8)
        frame = _movement_add_word(state, frame, 'target_x', 0xB8 if entry == 0x67338 else 1)
    else:
        raise ValueError('actual numeric text entry required')
    return _scenario_numeric_text_fields(state, frame)


def compose_scenario_member_name_fields(state: SceneState, frame: FirstDeploymentFrame,
        entry: int=0x672A2) -> FirstDeploymentFrame:
    """672A2/672E6/672F6: three true entries sharing the live six-BYTE name table."""
    frame = _resource_cost_frame(state, frame, entry)
    if entry in (0x672A2, 0x672E6):
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3D0 if entry == 0x672A2 else 0xFFFFF3D2, 2), 16)
    elif entry == 0x672F6:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    else:
        raise ValueError('actual member name text entry required')
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(u32(0x8A504 + s16(low16(frame.target_x)))).cursor(),
        candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move(state, frame, 'target_x', 2, 16)
    while True:
        frame = _movement_move(state, frame, 'target_y', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_y) | 0x4000, 16)
        frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_y))
        frame = first_replace(frame, candidates=frame.candidates.advance(2),
            target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    while True:
        frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, 0x800C)
        frame = first_replace(frame, candidates=frame.candidates.advance(-2))
        frame = _movement_compare(state, frame, frame.candidates.word(), 0x403F, 16)
        if not frame.status & 4:
            break
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3D4, state.read(0xFFFFF3BE, 4))
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3BE, 0xFFFFD300)
    return _command_policy_child_fields(state, frame, 0x671B6)


def restore_scenario_previous_text_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """672EC: restore the prior packet pointer, then take the real scrolling-message tail."""
    frame = _resource_cost_frame(state, frame, 0x672EC)
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3BE, state.read(0xFFFFF3D4, 4))
    return _command_policy_child_fields(state, frame, 0x671B6)


def compose_scenario_status_pair_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """67306: append the current live status's two-word resource packet."""
    frame = _resource_cost_frame(state, frame, 0x67306)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF646, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = first_replace(frame, roster=state.table_at(u32(0x8A212 + s16(low16(frame.target_x)))).cursor(),
        candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move_long(state, frame, 'target_x', frame.roster.long())
    frame = first_replace(frame, roster=frame.roster.advance(4))
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x | 0x40004000)
    frame = _command_policy_store_long_fields(state, frame, frame.candidates.base, frame.target_x)
    frame = first_replace(frame, candidates=frame.candidates.advance(4))
    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, 0x800C)
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3D4, state.read(0xFFFFF3BE, 4))
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3BE, 0xFFFFD300)
    return _command_policy_child_fields(state, frame, 0x671B6)


def _scenario_panel_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int, displacement: int=0, advance: bool=False, clear: bool=False) -> FirstDeploymentFrame:
    """The packet writers' actual A0 destination, not a renderer or hidden buffer."""
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, value, displacement, clear)
    return first_replace(frame, roster=frame.roster.advance(2)) if advance else frame


def _scenario_panel_tile_fields(state: SceneState, frame: FirstDeploymentFrame,
        tile: int, carrier: str='count') -> FirstDeploymentFrame:
    """Tile construction keeps the actual high Dn WORD and shared logical flags."""
    if carrier not in ('count', 'target_y'):
        raise ValueError('actual panel tile carrier required')
    frame = _movement_move(state, frame, carrier, tile, 16)
    return _movement_move(state, frame, carrier, low16(frame.carrier(carrier)) | low16(frame.unit), 16)


def build_scenario_single_row_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """6751E: one full-width row, with its optional paired annotation subpanel."""
    frame = _resource_cost_frame(state, frame, 0x6751E)
    for value in (0x26, 0xCA02):
        frame = _scenario_panel_word_fields(state, frame, value, advance=True)
    frame = _scenario_panel_tile_fields(state, frame, 0x380)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
    frame = _movement_move(state, frame, 'target_x', 35, 16)
    frame = _scenario_panel_tile_fields(state, frame, 0x381)
    while True:
        frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    frame = _scenario_panel_tile_fields(state, frame, 0xB80)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
    frame = _scenario_panel_word_fields(state, frame, 0, clear=True)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, 0x50)
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF3A4, 2)
    if frame.status & 4:
        return frame
    frame = _scenario_panel_word_fields(state, frame, 13, 30)
    frame = _scenario_panel_word_fields(state, frame, 13, advance=True)
    frame = _scenario_panel_tile_fields(state, frame, 0x934)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)
    frame = _scenario_panel_tile_fields(state, frame, 0x9B4)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
    frame = _scenario_panel_tile_fields(state, frame, 0x1380)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)
    frame = _scenario_panel_word_fields(state, frame, 0x8000, advance=True)
    frame = _movement_move(state, frame, 'target_x', 10, 16)
    frame = _scenario_panel_tile_fields(state, frame, 0x1381)
    while True:
        frame = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)
        frame = _scenario_panel_word_fields(state, frame, 0x8000, advance=True)
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    frame = _scenario_panel_tile_fields(state, frame, 0x1B80)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), 30)
    frame = _scenario_panel_word_fields(state, frame, 0x8000, advance=True)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, 0x3C)
    return _scenario_panel_word_fields(state, frame, 0, 30, clear=True)


def _scenario_column_panel_fields(state: SceneState, frame: FirstDeploymentFrame,
        columns: int) -> FirstDeploymentFrame:
    """Two real adjacent packet layouts share only their identical tile-row traversal."""
    if columns not in (2, 3):
        raise ValueError('actual paired/triple scenario panel role required')
    for displacement in (80, 0) if columns == 2 else (160, 80, 0):
        frame = _scenario_panel_word_fields(state, frame, 0x26, displacement, displacement == 0)
    headers = ((80, 0xCB02), (0, 0xCA82)) if columns == 2 else ((160, 0xCC82), (80, 0xCC02), (0, 0xCB82))
    for displacement, header in headers:
        frame = _scenario_panel_word_fields(state, frame, header, displacement, displacement == 0)
    for displacement in (80, 0) if columns == 2 else (160, 80, 0):
        frame = _scenario_panel_tile_fields(state, frame, 0x382)
        frame = _scenario_panel_word_fields(state, frame, low16(frame.count), displacement, displacement == 0)
    frame = _scenario_panel_tile_fields(state, frame, 0x505 if columns == 2 else 0x54D, 'target_y')
    frame = _movement_move(state, frame, 'target_x', 35, 16)
    while True:
        for displacement in (0, 80) if columns == 2 else (0, 80, 160):
            frame = _scenario_panel_word_fields(state, frame, low16(frame.target_y), displacement)
            frame = _movement_adjust_word(state, frame, 'target_y', 1)
        frame = first_replace(frame, roster=frame.roster.advance(2),
            target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    for displacement in (80, 0) if columns == 2 else (160, 80, 0):
        frame = _scenario_panel_tile_fields(state, frame, 0xB82)
        frame = _scenario_panel_word_fields(state, frame, low16(frame.count), displacement, displacement == 0)
    frame = _scenario_panel_word_fields(state, frame, 0, 80 if columns == 2 else 160, clear=True)
    return _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, 0xA0 if columns == 2 else 0xF0)


def build_scenario_paired_columns_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """675B0: full paired-column scenario tile packet."""
    frame = _resource_cost_frame(state, frame, 0x675B0)
    return _scenario_column_panel_fields(state, frame, 2)


def build_scenario_triple_columns_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """6760E: full three-column scenario tile packet."""
    frame = _resource_cost_frame(state, frame, 0x6760E)
    return _scenario_column_panel_fields(state, frame, 3)


def build_scenario_alternate_row_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """67692: full-width alternate row using the upper tile bank."""
    frame = _resource_cost_frame(state, frame, 0x67692)
    for value in (0x26, 0xCD02):
        frame = _scenario_panel_word_fields(state, frame, value, advance=True)
    frame = _scenario_panel_tile_fields(state, frame, 0x1380)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
    frame = _movement_move(state, frame, 'target_x', 35, 16)
    frame = _scenario_panel_tile_fields(state, frame, 0x1381)
    while True:
        frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(low16(frame.target_x) - 1)))
        if low16(frame.target_x) == 65535:
            break
    frame = _scenario_panel_tile_fields(state, frame, 0x1B80)
    frame = _scenario_panel_word_fields(state, frame, low16(frame.count), advance=True)
    frame = _scenario_panel_word_fields(state, frame, 0, clear=True)
    return _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, 0x50)


"""Command-selection phases, confirmation, affiliation removal and reassignment.

Complete original 3130E..319D4 owners; PC-relative resource gaps stay resources.
Both menu variants share control rules, never an invented instruction machine.
"""
from ..high_level_main_flows.business_movement_support import (
    _movement_save_longs, _movement_restore_longs, _movement_arithmetic_long)
from .business_city import _duel_menu_byte_bit_fields


def _command_policy_sub_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        carrier: str, amount: int) -> FirstDeploymentFrame:
    """Named command role projects the existing sole SUB.W/X primitive."""
    return _special_action_sub_word(state, frame, carrier, amount)


def _command_policy_register_bit_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int, bit: int) -> FirstDeploymentFrame:
    if bit not in (0, 1, 4, 7, 14):
        raise ValueError('actual command register bit required')
    frame = _postbattle_bit_fields(frame, bool(uint(value, 32) & (1 << bit)))
    state.sr = (state.sr & 65504) | frame.status
    return frame


def _command_policy_carry_fields(state: SceneState, frame: FirstDeploymentFrame,
        carry: bool) -> FirstDeploymentFrame:
    if type(carry) is not bool:
        raise ValueError('actual command carry outcome required')
    status = frame.status | 1 if carry else frame.status & 30
    state.sr = (state.sr & 65504) | status
    return first_replace(frame, status=status)


def _command_policy_message_fields(state: SceneState, frame: FirstDeploymentFrame,
        message: int, continuation: int) -> FirstDeploymentFrame:
    frame = _movement_move(state, frame, 'target_x', message, 16)
    return _command_policy_call_fields(state, frame, 0x676F2, continuation)


def wait_command_intro_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3130E: per-tick timer/button transition to the command intro, not a poll loop."""
    frame = _resource_cost_frame(state, frame, 0x3130E)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF608, -1)
    if not frame.status & 4:
        frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
        if frame.status & 4: return frame
    return _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xB0)


def show_command_intro_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31328: advance the phase and queue message 9E."""
    frame = _resource_cost_frame(state, frame, 0x31328)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_message_fields(state, frame, 0x9E, 0x31336)


def reset_command_intro_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31338: set the intro transition command."""
    frame = _resource_cost_frame(state, frame, 0x31338)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xB0)


def confirm_command_map_origin_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31340: clamp cursor origin, query the real map target and acknowledge a valid point."""
    frame = _resource_cost_frame(state, frame, 0x31340)
    for carrier, address, amount in (('target_y', 0xFFFFF35E, 0x70), ('unit', 0xFFFFF360, 0xA0)):
        frame = _movement_move(state, frame, carrier, state.read(address, 2), 16)
        frame = _command_policy_sub_word_fields(state, frame, carrier, amount)
        if frame.status & 1: frame = _movement_move(state, frame, carrier, 0, 16)
    frame = _command_policy_call_fields(state, frame, 0x14D64, 0x3135E)
    frame = _movement_test(state, frame, low16(frame.distance), 16)
    if frame.status & 4:
        frame = _movement_move(state, frame, 'target_x', 0xAE, 16)
        frame = _command_policy_call_fields(state, frame, 0x808A, 0x3136C)
        frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
        frame = _command_policy_message_fields(state, frame, 2, 0x3137A)
    return frame


def open_command_selection_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3137C: invoke the actual campaign preparation before changing command phase."""
    frame = _resource_cost_frame(state, frame, 0x3137C)
    frame = _command_policy_call_fields(state, frame, 0x1228, 0x31382)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF362, 15)


def show_command_selected_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """313A6: copy the live selected member and queue its command-selection notice."""
    frame = _resource_cost_frame(state, frame, 0x313A6)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D2, state.read(0xFFFFF3A6, 2))
    return _command_policy_message_fields(state, frame, 0x8A, 0x313BA)


def _command_policy_descriptor_fields(state: SceneState, frame: FirstDeploymentFrame,
        resource: int, destination: int, rows: int, style: int, continuation: int) -> FirstDeploymentFrame:
    """Shared real descriptor setup; ownership remains with each original whole caller."""
    frame = first_replace(frame, roster=state.table_at(resource).cursor())
    frame = _movement_move_long(state, frame, 'target_x', destination)
    frame = _movement_move(state, frame, 'target_y', rows, 16)
    frame = _movement_move(state, frame, 'unit', style, 16)
    return _command_policy_call_fields(state, frame, 0x26BFA, continuation)


def initialize_command_choice_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """313BC: stage the original command menu descriptor and its debounce count."""
    frame = _resource_cost_frame(state, frame, 0x313BC)
    frame = _command_policy_descriptor_fields(state, frame, 0x313E0, 0xC0000006, 10, 0xC3A2, 0x313D4)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFCFD2, 8)


def _command_policy_debounce_fields(state: SceneState, frame: FirstDeploymentFrame) -> tuple[FirstDeploymentFrame, bool]:
    """The three menu callers' identical read/decrement/clamp tail; no BSR invented."""
    frame = _movement_test(state, frame, state.read(0xFFFFCFD2, 2), 16)
    if frame.status & 4: return frame, False
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFCFD2, -1)
    frame = _movement_compare(state, frame, state.read(0xFFFFCFD2, 2), 8, 16)
    if not frame.status & 5:
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFCFD2, 8)
    return frame, True


def process_command_choice_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31430: process direction, draw the selector, debounce and execute the selected action."""
    frame = _resource_cost_frame(state, frame, 0x31430)
    frame = _command_policy_call_fields(state, frame, 0x31472, 0x31434)
    frame = _command_policy_call_fields(state, frame, 0x314BE, 0x31438)
    frame, waiting = _command_policy_debounce_fields(state, frame)
    if waiting: return frame
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4: return frame
    frame = _command_policy_call_fields(state, frame, 0x3154C, 0x31466)
    frame = _movement_move(state, frame, 'target_x', 0xAC, 16)
    return _command_policy_call_fields(state, frame, 0x808A, 0x31470)


def step_command_choice_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31472: timed two-direction cursor constrained to the original three choices."""
    frame = _resource_cost_frame(state, frame, 0x31472)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF602, 1), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)
    if frame.status & 4:
        return _command_policy_store_word_fields(state, frame, 0xFFFFF608, 1)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF608, -1)
    if not frame.status & 4: return frame
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 12)
    frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 1)
    if frame.status & 4:
        frame = _movement_test(state, frame, state.read(0xFFFFF710, 2), 16)
        if not frame.status & 4:
            frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF710, -1)
    else:
        frame = _movement_compare(state, frame, state.read(0xFFFFF710, 2), 2, 16)
        if frame.status & 1:
            frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF710, 1)
    return frame


def _command_policy_draw_choice_fields(state: SceneState, frame: FirstDeploymentFrame,
        three_choices: bool) -> FirstDeploymentFrame:
    """Shared display admission; two callers retain their actual source/cursor roles."""
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if not frame.status & 4: return frame
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF602, 1), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)
    if frame.status & 4:
        frame = _duel_menu_byte_bit_fields(state, frame, 0xFFFFF321, 3)
        if not frame.status & 4: return frame
    frame = first_replace(frame, roster=state.table_at(0x31502 if three_choices else 0x3184A).cursor())
    address = 0xFFFFF710 if three_choices else 0xFFFFF386
    frame = _movement_move(state, frame, 'target_x', state.read(address, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_add_word(state, frame, 'target_x', state.read(address, 2))
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3)
    frame = _movement_add_word(state, frame, 'target_x', 0x38 if three_choices else 0x40)
    frame = _movement_move(state, frame, 'target_y', 0x88 if three_choices else 0x80, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    return _command_policy_call_fields(state, frame, 0xAC08, 0x31500 if three_choices else 0x31848)


def draw_command_choice_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """314BE: draw the current three-choice command cursor at its original coordinate."""
    frame = _resource_cost_frame(state, frame, 0x314BE)
    return _command_policy_draw_choice_fields(state, frame, True)


def dispatch_command_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3154C: actual live signed-WORD table displacement and original indexed JSR."""
    frame = _resource_cost_frame(state, frame, 0x3154C)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF710, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', state.table_at(0x3155C).word(low16(frame.target_x)), 16)
    return _command_policy_call_fields(state, frame, u32(0x31562 + s16(low16(frame.target_x))), 0x3155A)


def stage_member_command_panel_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3158E: stage the member-action descriptor without adding any phase updates."""
    frame = _resource_cost_frame(state, frame, 0x3158E)
    return _command_policy_descriptor_fields(state, frame, 0x315EA, 0xC0000006, 10, 0xC3A2, 0x315A6)


def detach_command_selected_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """315A8: mark the member detached and repair its old city's head if necessary."""
    frame = _resource_cost_frame(state, frame, 0x315A8)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_y)), 8)
    frame = _settlement_write_byte_fields(state, frame, frame.roster, 255, low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 63, 16)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF45E).cursor())
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 1)
    frame = _movement_compare(state, frame, low16(frame.unit), frame.candidates.word(low16(frame.target_y)), 16)
    if not frame.status & 4: return frame
    stack = frame.stack_cursor.advance(-2); stack.set_word(0, low16(frame.target_x))
    frame = first_replace(frame, stack_cursor=stack)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF630, 65535)
    frame = _command_policy_call_fields(state, frame, 0x5F48, 0x315E0)
    value = frame.stack_cursor.word()
    frame = first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))
    frame = _movement_move(state, frame, 'target_x', value, 16)
    return _command_policy_call_fields(state, frame, 0xE1F6, 0x315E8)


def _command_policy_member_notice_fields(state: SceneState, frame: FirstDeploymentFrame,
        message: int, continuation: int, member_address: int=0xFFFFF3D2) -> FirstDeploymentFrame:
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 1)
    frame = _command_policy_store_word_fields(state, frame, member_address, state.read(0xFFFFF3A6, 2))
    return _command_policy_message_fields(state, frame, message, continuation)


def execute_member_release_command_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31562: detach, acknowledge release, mark a map refresh and stage the member panel."""
    frame = _resource_cost_frame(state, frame, 0x31562)
    frame = _command_policy_call_fields(state, frame, 0x315A8, 0x31566)
    frame = _command_policy_member_notice_fields(state, frame, 0x11D, 0x31582)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF652, 1)
    return _command_policy_call_fields(state, frame, 0x3158E, 0x3158C)


def execute_member_discharge_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31612: queue the second discharge outcome and stage its command panel."""
    frame = _resource_cost_frame(state, frame, 0x31612)
    frame = _command_policy_member_notice_fields(state, frame, 0x11E, 0x3162E)
    return _command_policy_call_fields(state, frame, 0x3158E, 0x31632)


def execute_member_transfer_command_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31634: detach and count the destination roster before accepting or refusing transfer."""
    frame = _resource_cost_frame(state, frame, 0x31634)
    frame = _command_policy_call_fields(state, frame, 0x315A8, 0x31638)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A8, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 255, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    while True:
        frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.target_y)), 8)
        if frame.status & 4: frame = _movement_adjust_word(state, frame, 'unit', 1)
        frame = first_replace(frame, target_y=replace_word(frame.target_y, u16(low16(frame.target_y) - 1)))
        if low16(frame.target_y) == 65535: break
    frame = _movement_compare(state, frame, low16(frame.unit), 10, 16)
    if frame.status & 1:
        frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
        frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
        frame = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.target_y))
        frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
        frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3F2, frame.roster.word(low16(frame.target_x)))
        frame = _command_policy_call_fields(state, frame, 0x208CE, 0x31686)
        frame = _command_policy_member_notice_fields(state, frame, 0x11F, 0x316A2)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF652, 1)
        return _command_policy_call_fields(state, frame, 0x3158E, 0x316AC)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A6, 2), 16)
    frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 7)
    frame = first_replace(frame, target_x=frame.target_x | 128)
    frame = _settlement_write_byte_fields(state, frame, frame.roster, low8(frame.target_x), low16(frame.target_y))
    frame = _command_policy_member_notice_fields(state, frame, 0x9B, 0x316DC, 0xFFFFF3D0)
    return _command_policy_call_fields(state, frame, 0x3158E, 0x316E0)


def show_command_policy_notice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """316E2: queue the live policy message code."""
    frame = _resource_cost_frame(state, frame, 0x316E2)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_message_fields(state, frame, state.read(0xFFFFF740, 2), 0x316F0)


def _command_policy_initialize_binary_menu_fields(state: SceneState, frame: FirstDeploymentFrame,
        resource: int, continuation: int) -> FirstDeploymentFrame:
    frame = _command_policy_descriptor_fields(state, frame, resource, 0xC0000008, 7, 0xC420, continuation)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF386, 0, True)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFCFD2, 8)


def initialize_command_policy_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """316F2: stage the binary policy prompt and reset its selection."""
    frame = _resource_cost_frame(state, frame, 0x316F2)
    return _command_policy_initialize_binary_menu_fields(state, frame, 0x3171A, 0x3170A)


def step_command_binary_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """317DC: timed XOR choice update with the original twelve-tick repeat delay."""
    frame = _resource_cost_frame(state, frame, 0x317DC)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF602, 1), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)
    if frame.status & 4: return _command_policy_store_word_fields(state, frame, 0xFFFFF608, 1)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF608, -1)
    if not frame.status & 4: return frame
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 12)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF386, state.read(0xFFFFF386, 2) ^ 1)


def draw_command_binary_cursor_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31808: draw the binary command menu's actual selection row."""
    frame = _resource_cost_frame(state, frame, 0x31808)
    return _command_policy_draw_choice_fields(state, frame, False)


def process_command_policy_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3176A: binary cursor/debounce plus accept-or-cancel command action."""
    frame = _resource_cost_frame(state, frame, 0x3176A)
    frame = _command_policy_call_fields(state, frame, 0x317DC, 0x3176E)
    frame = _command_policy_call_fields(state, frame, 0x31808, 0x31772)
    frame, waiting = _command_policy_debounce_fields(state, frame)
    if waiting: return frame
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4: return frame
    frame = _movement_move(state, frame, 'target_x', 0xAC, 16)
    frame = _command_policy_call_fields(state, frame, 0x808A, 0x317A6)
    frame = _movement_test(state, frame, state.read(0xFFFFF386, 2), 16)
    if frame.status & 4:
        frame = _command_policy_call_fields(state, frame, 0x318AC, 0x317B2)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 1)
        frame = _command_policy_message_fields(state, frame, 0x85, 0x317C8)
        return _command_policy_call_fields(state, frame, 0x3191E, 0x317CC)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_call_fields(state, frame, 0x3191E, 0x317DA)


def stage_command_policy_result_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3191E: stage the real policy-result packet resource."""
    frame = _resource_cost_frame(state, frame, 0x3191E)
    return _command_policy_descriptor_fields(state, frame, 0x31938, 0xC0000008, 7, 0xC420, 0x31936)


def show_command_completion_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31954: advance and queue completion label A9."""
    frame = _resource_cost_frame(state, frame, 0x31954)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    return _command_policy_message_fields(state, frame, 0xA9, 0x31962)


def initialize_command_exit_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31964: use the original policy prompt resource for the exit-menu role."""
    frame = _resource_cost_frame(state, frame, 0x31964)
    return _command_policy_initialize_binary_menu_fields(state, frame, 0x3171A, 0x3197C)


def process_command_exit_menu_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3198C: cursor/debounce confirmation, sound request and result staging."""
    frame = _resource_cost_frame(state, frame, 0x3198C)
    frame = _command_policy_call_fields(state, frame, 0x317DC, 0x31990)
    frame = _command_policy_call_fields(state, frame, 0x31808, 0x31994)
    frame, waiting = _command_policy_debounce_fields(state, frame)
    if waiting: return frame
    frame = _command_policy_bit_fields(state, frame, 0xFFFFF603, 5)
    if frame.status & 4: return frame
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF600, 0xB0)
    frame = _movement_move(state, frame, 'target_x', 0xAC, 16)
    frame = _command_policy_call_fields(state, frame, 0x808A, 0x319CE)
    return _command_policy_call_fields(state, frame, 0x3191E, 0x319D2)


def refresh_command_map_on_input_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """319D4: refresh a changed map label, then always poll the original input tail."""
    frame = _resource_cost_frame(state, frame, 0x319D4)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF602, 2), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 0x2F, 16)
    if not frame.status & 4:
        frame = _movement_move_long(state, frame, 'target_x', 0xC0000026)
        frame = _movement_move(state, frame, 'target_y', 7, 16)
        frame = _movement_move(state, frame, 'unit', 0xCA02, 16)
        frame = first_replace(frame, roster=state.table_at(0x3138A).cursor())
        frame = _command_policy_call_fields(state, frame, 0x26BFA, 0x319F8)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, 0x201)
        frame = _duel_menu_byte_bit_fields(state, frame, 0xFFFFF3A4, 6, True)
    return _command_policy_call_fields(state, frame, 0xA14E, 0x31A0A)


"""Command policy dispatch, roster constraints, transfer choice and cost assembly.

Original complete owners 31A0C..320A0. Live sentinels and signed WORD indices
are not repaired; absent members can keep the original search from finishing.
"""
from .business_city import _special_action_sub_word


def dispatch_city_command_policy_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31A0C: repeat the live indexed command table until the actual state WORD is negative."""
    frame = _resource_cost_frame(state, frame, 0x31A0C)
    while True:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF728, 2), 16)
        if frame.status & 8: return frame
        frame = _movement_adjust_word(state, frame, 'target_x', -1)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_x', state.table_at(0x31A24).word(low16(frame.target_x)), 16)
        frame = _command_policy_call_fields(state, frame, u32(0x31A42 + s16(low16(frame.target_x))), 0x31A20)


def count_command_city_members_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31AB6: count all 256 affiliation BYTEs, with the original three-LONG MOVEM."""
    frame = _resource_cost_frame(state, frame, 0x31AB6)
    saved = ('offset_y', 'choice', 'scan')
    frame = _movement_save_longs(state, frame, saved)
    frame = first_replace(frame, scan=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'offset_y', 255, 16)
    frame = _movement_move(state, frame, 'distance', 0, 16)
    while True:
        frame = _movement_compare(state, frame, low8(frame.unit), frame.scan.byte(low16(frame.offset_y)), 8)
        if frame.status & 4: frame = _movement_adjust_word(state, frame, 'distance', 1)
        frame = first_replace(frame, offset_y=replace_word(frame.offset_y, u16(low16(frame.offset_y) - 1)))
        if low16(frame.offset_y) == 65535: break
    return _movement_restore_longs(state, frame, saved)


def rank_command_neighbor_city_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31A70: choose the highest-population available adjacent city, preserving seven LONGs."""
    frame = _resource_cost_frame(state, frame, 0x31A70)
    saved = ('target_x', 'unit', 'count', 'distance', 'roster', 'candidates', 'controller')
    frame = _movement_save_longs(state, frame, saved)
    frame = first_replace(frame, roster=state.table_at(0xD4BDA).cursor(), controller=state.table_at(0xFFFFEA37))
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3)
    frame = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.target_x))))
    frame = _movement_move(state, frame, 'count', state.read(0xFFFFF376, 2), 16)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'offset_x', 65535, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'unit', frame.roster.byte(), 8)
        frame = first_replace(frame, roster=frame.roster.advance(1))
        if frame.status & 8: break
        frame = _movement_test(state, frame, frame.controller.byte(low16(frame.unit)), 8)
        if not frame.status & 4: continue
        frame = _movement_compare(state, frame, low8(frame.count), frame.candidates.byte(low16(frame.unit)), 8)
        if frame.status & 4: continue
        frame = _command_policy_call_fields(state, frame, 0x31AB6, 0x31AA6)
        frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.target_y), 16)
        if frame.status & 5: continue
        frame = _movement_move(state, frame, 'target_y', low16(frame.distance), 16)
        frame = _movement_move(state, frame, 'offset_x', low16(frame.unit), 16)
    return _movement_restore_longs(state, frame, saved)


def select_command_population_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31A42: compare the current and best adjacent populations to choose action 2/3."""
    frame = _resource_cost_frame(state, frame, 0x31A42)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _command_policy_call_fields(state, frame, 0x31A70, 0x31A4A)
    frame = _movement_test(state, frame, low16(frame.offset_x), 16)
    action = 2
    if not frame.status & 8:
        frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF364, 2), 16)
        frame = _command_policy_call_fields(state, frame, 0x31AB6, 0x31A58)
        frame = _first_compare_long(frame, frame.distance, frame.target_y)
        state.sr = (state.sr & 65504) | frame.status
        action = 3 if frame.status & 1 else 2
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, action)


def test_command_city_near_group_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31AF2: search packed groups inside the original asymmetric city rectangle."""
    frame = _resource_cost_frame(state, frame, 0x31AF2)
    frame = first_replace(frame, roster=state.table_at(0xD4AC6).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x), 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 4, True)
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _command_policy_sub_word_fields(state, frame, 'target_y', 5)
    if frame.status & 1: frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_add_word(state, frame, 'unit', 5)
    frame = _movement_move(state, frame, 'count', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'distance', low16(frame.count), 16)
    frame = _command_policy_sub_word_fields(state, frame, 'count', 5)
    if frame.status & 1: frame = _movement_move(state, frame, 'count', 0, 16)
    frame = _movement_add_word(state, frame, 'distance', 5)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor())
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
        if frame.status & 4: return _command_policy_carry_fields(state, frame, False)
        inside = True
        for name, displacement, excluded in (('target_y', 1, 'higher'), ('unit', 1, 'lower'), ('count', 2, 'higher'), ('distance', 2, 'lower')):
            frame = _movement_compare(state, frame, low8(frame.carrier(name)), frame.roster.byte(0, displacement), 8)
            if excluded == 'higher': rejected = not frame.status & 5
            elif excluded == 'lower': rejected = bool(frame.status & 1)
            else: rejected = not frame.status & 1
            if rejected: inside = False; break
        if inside: return _command_policy_carry_fields(state, frame, True)
        frame = first_replace(frame, roster=frame.roster.advance(13 + s16(low16(frame.target_x))))


def select_command_proximity_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31AD8: choose the group-nearby or alternate city policy from real carry."""
    frame = _resource_cost_frame(state, frame, 0x31AD8)
    frame = _command_policy_call_fields(state, frame, 0x31AF2, 0x31ADC)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 3 if frame.status & 1 else 8)


def find_command_minimum_loyalty_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31BA6: nonzero minimum loyalty across the live WORD-sentinel member queue."""
    frame = _resource_cost_frame(state, frame, 0x31BA6)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFC300).cursor())
    frame = _movement_move(state, frame, 'target_y', 255, 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'distance', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: return frame
        frame = _movement_move(state, frame, 'unit', frame.candidates.byte(low16(frame.distance)), 8)
        if frame.status & 4: continue
        frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)
        if not frame.status & 1: continue
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)


def select_command_loyalty_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31B6A: select loyalty recovery at the original thresholds and real RNG odds."""
    frame = _resource_cost_frame(state, frame, 0x31B6A)
    frame = _command_policy_call_fields(state, frame, 0x31BA6, 0x31B6E)
    frame = _movement_compare(state, frame, low16(frame.target_y), 50, 16)
    recovery = bool(frame.status & 5)
    if not recovery:
        frame = _movement_compare(state, frame, low16(frame.target_y), 71, 16)
        if frame.status & 1:
            frame = _command_policy_call_fields(state, frame, 0x83D4, 0x31B84)
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF61C, 2), 16)
            frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)
            recovery = bool(frame.status & 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 9 if recovery else 4)


def test_command_member_class_shortfall_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31BEC: compare class against the exact growth thresholds 5/10/15/20."""
    frame = _resource_cost_frame(state, frame, 0x31BEC)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(),
        candidates=state.table_at(0xFFFFC700).cursor(), controller=state.table_at(0xFFFFC600))
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: return _command_policy_carry_fields(state, frame, False)
        frame = _movement_move(state, frame, 'target_y', frame.controller.byte(low16(frame.target_x)), 8)
        frame = _movement_move(state, frame, 'unit', 0, 16)
        frame = _movement_compare(state, frame, low16(frame.target_y), 5, 16)
        if frame.status & 1: continue
        for threshold in (10, 15, 20):
            frame = _movement_adjust_word(state, frame, 'unit', 1)
            frame = _movement_compare(state, frame, low16(frame.target_y), threshold, 16)
            if frame.status & 1: break
        else: frame = _movement_adjust_word(state, frame, 'unit', 1)
        frame = _movement_move(state, frame, 'count', frame.candidates.byte(low16(frame.target_x)), 8)
        frame = _movement_move(state, frame, 'count', low16(frame.count) & 7, 16)
        frame = _movement_compare(state, frame, low16(frame.count), low16(frame.unit), 16)
        if frame.status & 1: return _command_policy_carry_fields(state, frame, True)


def test_command_member_training_shortfall_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31C46: retain BYTE flags and WORD readiness/troop reads in the original order."""
    frame = _resource_cost_frame(state, frame, 0x31C46)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFC700).cursor(),
        controller=state.table_at(0xFFFFB600), scan=state.table_at(0xFFFFC000).cursor())
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: return _command_policy_carry_fields(state, frame, False)
        frame = _command_policy_register_bit_fields(state, frame, frame.candidates.byte(low16(frame.target_x)), 4)
        if not frame.status & 4: continue
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_y', frame.controller.word(low16(frame.target_x)), 16)
        frame = _movement_compare(state, frame, low16(frame.target_y), 100, 16)
        if not frame.status & 1: return _command_policy_carry_fields(state, frame, True)
        frame = _movement_compare(state, frame, low16(frame.target_y), 95, 16)
        if frame.status & 1: continue
        frame = _movement_compare(state, frame, frame.scan.word(low16(frame.target_x)), 150, 16)
        if not frame.status & 1: return _command_policy_carry_fields(state, frame, True)


def select_command_training_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31BCA: class/readiness shortage selects training; both checks use their real slots."""
    frame = _resource_cost_frame(state, frame, 0x31BCA)
    frame = _command_policy_call_fields(state, frame, 0x31BEC, 0x31BCE)
    needed = bool(frame.status & 1)
    if not needed:
        frame = _command_policy_call_fields(state, frame, 0x31C46, 0x31BD6)
        needed = bool(frame.status & 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 10 if needed else 5)


def select_command_city_order_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31C8C: city order/loyalty policy with original 50/66 thresholds and RNG choice."""
    frame = _resource_cost_frame(state, frame, 0x31C8C)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE31C).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x), 2), 16)
    frame = _movement_compare(state, frame, low16(frame.target_y), 50, 16)
    improve = bool(frame.status & 5)
    if not improve:
        frame = _movement_compare(state, frame, low16(frame.target_y), 66, 16)
        if frame.status & 1:
            frame = _command_policy_call_fields(state, frame, 0x83D4, 0x31CB0)
            frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), 5, 16)
            improve = bool(frame.status & 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 11 if improve else 6)


def calculate_command_roster_capacity_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31D6C: accumulate the live class-capacity WORD table and finish with LONG masking."""
    frame = _resource_cost_frame(state, frame, 0x31D6C)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFC700).cursor())
    frame = _movement_move(state, frame, 'distance', 0, 16)
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: break
        frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(low16(frame.target_x)), 8)
        frame = _movement_move(state, frame, 'offset_x', low16(frame.offset_x) & 7, 16)
        frame = _movement_fixed_shift_word(state, frame, 'offset_x', 1)
        frame = _movement_add_word(state, frame, 'distance', state.table_at(0x31D94).word(low16(frame.offset_x)))
    return _movement_move_long(state, frame, 'distance', frame.distance & 65535)


def calculate_command_city_population_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31D4E: derive the original recruitment factor and enter the actual population service."""
    frame = _resource_cost_frame(state, frame, 0x31D4E)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_adjust_word(state, frame, 'target_x', -1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE280).cursor())
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_move(state, frame, 'choice', 100, 16)
    frame = _command_policy_sub_word_fields(state, frame, 'choice', frame.roster.word(low16(frame.target_y), 2))
    return _command_policy_call_fields(state, frame, 0x16C72, 0x31D6A)


def select_command_recruitment_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31CCE: choose recruitment from population/capacity ratio and unchanged RNG thresholds."""
    frame = _resource_cost_frame(state, frame, 0x31CCE)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x31CD4)
    frame = _command_policy_call_fields(state, frame, 0x31D4E, 0x31CD8)
    frame = _command_policy_call_fields(state, frame, 0x31D6C, 0x31CDC)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF61C, 2), 16)
    frame = _movement_move_long(state, frame, 'offset_x', frame.distance)
    frame = _special_action_shift_long(state, frame, 'offset_x', 1)
    frame = _first_compare_long(frame, frame.count, frame.offset_x); state.sr = (state.sr & 65504) | frame.status
    recruit = True
    if not frame.status & 1:
        frame = _movement_arithmetic_long(state, frame, 'offset_x', frame.distance)
        frame = _first_compare_long(frame, frame.count, frame.offset_x); state.sr = (state.sr & 65504) | frame.status
        if frame.status & 1:
            frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)
            frame = _movement_compare(state, frame, low16(frame.target_x), 7, 16)
            recruit = not bool(frame.status & 4)
        else:
            frame = _special_action_shift_long(state, frame, 'distance', 1)
            frame = _movement_arithmetic_long(state, frame, 'offset_x', frame.distance)
            frame = _first_compare_long(frame, frame.count, frame.offset_x); state.sr = (state.sr & 65504) | frame.status
            if frame.status & 1:
                frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 3, 16)
                frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)
                recruit = bool(frame.status & 1)
            else:
                frame = _special_action_shift_long(state, frame, 'offset_x', 1)
                frame = _first_compare_long(frame, frame.count, frame.offset_x); state.sr = (state.sr & 65504) | frame.status
                if frame.status & 1:
                    frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 0)
                    recruit = not bool(frame.status & 4)
                else:
                    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 7, 16)
                    frame = _movement_compare(state, frame, low16(frame.target_x), 3, 16)
                    recruit = bool(frame.status & 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 12 if recruit else 7)


def calculate_command_roster_supply_cost_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31DEC: accumulate each selected member's LONG supply and the fixed 100 overhead."""
    frame = _resource_cost_frame(state, frame, 0x31DEC)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFC800).cursor())
    frame = _movement_move_long(state, frame, 'target_x', 0)
    while True:
        frame = _movement_move(state, frame, 'target_y', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: break
        frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.candidates.long(low16(frame.target_y)))
        frame = _movement_arithmetic_long(state, frame, 'target_x', 100)
    # DIVU's undefined overflow N/Z do not escape: the following MOVE.W
    # overwrites NZVC before any condition consumes them. X is retained.
    frame = first_replace(frame, target_x=divu_retained(frame.target_x, 50))
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    return _movement_add_word(state, frame, 'target_x', low16(frame.target_y))


def select_command_supply_action_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31D9E: compare city supply against threefold/sevenfold roster cost."""
    frame = _resource_cost_frame(state, frame, 0x31D9E)
    frame = _command_policy_call_fields(state, frame, 0x31DEC, 0x31DA2)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE09C).cursor())
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'unit', 2)
    frame = _movement_move_long(state, frame, 'unit', frame.roster.long(low16(frame.unit)))
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _first_compare_long(frame, frame.unit, frame.target_x); state.sr = (state.sr & 65504) | frame.status
    supply = bool(frame.status & 1)
    if not supply:
        frame = _special_action_shift_long(state, frame, 'target_y', 2)
        frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
        frame = _first_compare_long(frame, frame.unit, frame.target_x); state.sr = (state.sr & 65504) | frame.status
        if frame.status & 1:
            frame = _command_policy_call_fields(state, frame, 0x83D4, 0x31DD2)
            frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 1)
            supply = bool(frame.status & 4)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 14 if supply else 13)


def choose_command_strongest_transfer_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31E6E: select the largest eligible troop WORD, preserving marked member exclusion."""
    frame = _resource_cost_frame(state, frame, 0x31E6E)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFB400).cursor())
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, 65535)
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: return frame
        frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 14)
        if not frame.status & 4: continue
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x)), 16)
        frame = _movement_compare(state, frame, low16(frame.unit), low16(frame.target_y), 16)
        if frame.status & 5: continue
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_x))


def choose_command_transfer_destination_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31EA0: rank same-force available cities by adjacent pressure and roster capacity."""
    frame = _resource_cost_frame(state, frame, 0x31EA0)
    frame = _movement_move(state, frame, 'offset_y', state.read(0xFFFFF376, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF450).cursor(), candidates=state.table_at(0xFFFFEA37).cursor())
    frame = _movement_move(state, frame, 'choice', 0, 16)
    frame = _movement_move(state, frame, 'count', 0, 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, 0, True)
    frame = _movement_move(state, frame, 'target_x', 40, 16)
    while True:
        frame = first_replace(frame, roster=frame.roster.advance(-1))
        frame = _movement_compare(state, frame, low8(frame.offset_y), frame.roster.byte(), 8)
        eligible = bool(frame.status & 4)
        if eligible:
            frame = _movement_test(state, frame, frame.candidates.byte(low16(frame.target_x)), 8)
            eligible = bool(frame.status & 4)
        if eligible:
            frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF364, 2), 16)
            eligible = not frame.status & 4
        if eligible:
            frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)
            frame = _command_policy_call_fields(state, frame, 0x31AB6, 0x31ED4)
            frame = _movement_compare(state, frame, low16(frame.distance), 10, 16)
            eligible = bool(frame.status & 1)
        if eligible:
            frame = _command_policy_call_fields(state, frame, 0x31A70, 0x31EE0)
            frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.choice), 16)
            eligible = not frame.status & 1
            if eligible and frame.status & 4:
                frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.count), 16)
                eligible = bool(frame.status & 1)
            if eligible:
                frame = _movement_move(state, frame, 'count', low16(frame.distance), 16)
                frame = _movement_move(state, frame, 'choice', low16(frame.target_y), 16)
                frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, low16(frame.target_x))
        frame = _movement_adjust_word(state, frame, 'target_x', -1)
        if frame.status & 4: return frame


def replace_command_city_head_queue_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31EFE: if transferring the city head, build its survivors queue and repair the head."""
    frame = _resource_cost_frame(state, frame, 0x31EFE)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF45E).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF3A6, 2), 16)
    if not frame.status & 4: return frame
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFF500).cursor())
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: break
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF3A6, 2), 16)
        if frame.status & 4: continue
        frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, 65535)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    return _command_policy_call_fields(state, frame, 0xE1F6, 0x31F38)


def remove_command_member_queue_reference_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31F3A: find the selected member and shift the real sentinel queue left.

    The original search has no missing-member stop. No protective cap is added.
    """
    frame = _resource_cost_frame(state, frame, 0x31F3A)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    while True:
        value = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_compare(state, frame, low16(frame.target_x), value, 16)
        if frame.status & 4: break
    while True:
        value = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _settlement_store_word_fields(state, frame, frame.roster, 0, value, -4)
        if frame.status & 8: return frame


def replace_command_force_head_link_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31F4E: preserve D0/A0 while moving the selected force head to its destination city."""
    frame = _resource_cost_frame(state, frame, 0x31F4E)
    frame = _movement_save_longs(state, frame, ('target_x', 'roster'))
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF3A6, 2), 16)
    if frame.status & 4:
        frame = first_replace(frame, roster=state.table_at(0xFFFFF45E).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF392, 2), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
        frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), state.read(0xFFFFF3A6, 2))
    return _movement_restore_longs(state, frame, ('target_x', 'roster'))


def execute_command_member_transfer_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31E16: select a movable member and a destination, then repair all three references."""
    frame = _resource_cost_frame(state, frame, 0x31E16)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF364, 2), 16)
    frame = _command_policy_call_fields(state, frame, 0x31AB6, 0x31E1E)
    frame = _movement_compare(state, frame, low16(frame.distance), 1, 16)
    if not frame.status & 4:
        frame = _command_policy_call_fields(state, frame, 0x31E6E, 0x31E2A)
        frame = _movement_test(state, frame, state.read(0xFFFFF3A6, 2), 16)
        if not frame.status & 8:
            frame = _command_policy_call_fields(state, frame, 0x31EA0, 0x31E36)
            frame = _movement_test(state, frame, state.read(0xFFFFF392, 2), 16)
            if not frame.status & 4:
                frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor())
                frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
                frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))
                frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
                frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
                frame = _settlement_write_byte_fields(state, frame, frame.roster, state.read(0xFFFFF393, 1), low16(frame.target_x))
                frame = _command_policy_call_fields(state, frame, 0x31EFE, 0x31E5E)
                frame = _command_policy_call_fields(state, frame, 0x31F3A, 0x31E62)
                frame = _command_policy_call_fields(state, frame, 0x31F4E, 0x31E66)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 3)


def choose_command_loyalty_swap_member_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31FF6: choose a middle-loyalty minimum, falling back to the best low-loyalty member."""
    frame = _resource_cost_frame(state, frame, 0x31FF6)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor(), candidates=state.table_at(0xFFFFC300).cursor())
    for name, value in (('target_y', 255), ('unit', 65535), ('count', 0), ('distance', 65535)):
        frame = _movement_move(state, frame, name, value, 16)
    while True:
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8: break
        frame = _command_policy_register_bit_fields(state, frame, frame.target_x, 14)
        if not frame.status & 4: continue
        frame = _movement_move(state, frame, 'offset_x', frame.candidates.byte(low16(frame.target_x)), 8)
        frame = _movement_compare(state, frame, low8(frame.offset_x), 40, 8)
        if not frame.status & 1:
            frame = _movement_compare(state, frame, low8(frame.offset_x), low8(frame.target_y), 8)
            if frame.status & 1:
                frame = _movement_move(state, frame, 'target_y', low8(frame.offset_x), 8)
                frame = _movement_move(state, frame, 'unit', low16(frame.target_x), 16)
        else:
            frame = _movement_compare(state, frame, low8(frame.offset_x), low8(frame.count), 8)
            if not frame.status & 5:
                frame = _movement_move(state, frame, 'count', low16(frame.offset_x), 16)
                frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
    frame = _movement_compare(state, frame, low8(frame.target_y), 80, 8)
    selected = low16(frame.unit)
    if not frame.status & 5:
        frame = _movement_test(state, frame, low16(frame.count), 16)
        if not frame.status & 4: selected = low16(frame.distance)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, selected)


def execute_command_loyalty_swap_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31F7E: reserve two live heads, calculate their costs and commit the original swap service."""
    frame = _resource_cost_frame(state, frame, 0x31F7E)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF634, frame.candidates.word(low16(frame.target_x)))
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF45E).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 1)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF630, frame.candidates.word(low16(frame.target_x)))
    frame = _command_policy_call_fields(state, frame, 0x31FF6, 0x31FA2)
    frame = _movement_test(state, frame, state.read(0xFFFFF3A6, 2), 16)
    if not frame.status & 8:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF630, 2), 16)
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(0xFFFFF3A6, 2), 16)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF634, 2), 16)
        frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor())
        frame = _movement_test(state, frame, frame.roster.byte(low16(frame.target_x)), 8)
        if frame.status & 4:
            frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))
            frame = _command_policy_call_fields(state, frame, 0x320A0, 0x31FD0)
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
            frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))
            frame = _command_policy_call_fields(state, frame, 0x320A0, 0x31FDE)
            frame = _command_policy_call_fields(state, frame, 0x3205C, 0x31FE2)
            frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, state.read(0xFFFFF364, 2))
            frame = _command_policy_call_fields(state, frame, 0xE592, 0x31FEE)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, 4)


def calculate_command_random_supply_budget_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3205C: assemble the two-word supply product before the actual signed divide service."""
    frame = _resource_cost_frame(state, frame, 0x3205C)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x32062)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 10)
    frame = first_replace(frame, roster=state.table_at(0xFFFFDFFC).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_move_long(state, frame, 'target_y', frame.roster.long(low16(frame.target_y)))
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.unit)
    frame = _movement_move_long(state, frame, 'unit', 100)
    frame = _command_policy_call_fields(state, frame, 0x35760, 0x3209A)
    return _command_policy_store_long_fields(state, frame, 0xFFFFF39E, frame.target_y)


