# Current full-frame command/scenario successors, original whole bodies preserved.
"""Retreat candidate generation, contact fallbacks and target commitment.

The original left/right coordinate samples share one logical rule. Their
physical call continuations remain variant-specific. Multi-entry strategy
wrappers share ordered attempts, not a PC interpreter or invented stack slots.
"""
from .business_city import _settlement_write_byte_fields
from ..high_level_main_flows.business_movement_support import _movement_multiply_word


def _continuation_shift_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        carrier: str, amount: int, right: bool=False) -> FirstDeploymentFrame:
    """Project the existing bounded logical WORD shift, including actual X."""
    frame = _position_order_shift(frame, carrier, amount, right)
    state.sr = (state.sr & 65504) | frame.status
    return frame


def _retreat_attempts_fields(state: SceneState, frame: FirstDeploymentFrame,
        attempts) -> FirstDeploymentFrame:
    """Run actual calls in original order; carry is the original stop result."""
    for target, continuation in attempts:
        frame = _command_policy_call_fields(state, frame, target, continuation)
        if frame.status & 1: break
    return frame


def execute_first_retreat_continuation_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22740: original retreat decision, readiness fallback, then first-side target update."""
    frame = _resource_cost_frame(state, frame, 0x22740)
    return _retreat_attempts_fields(state, frame,
        ((0x22756, 0x22744), (0x2298A, 0x2274C), (0x227E8, 0x22754)))


def choose_retreat_side_boundary_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22892: original map-specific city anchor and asymmetric side boundary."""
    frame = _resource_cost_frame(state, frame, 0x22892)
    frame = first_replace(frame, roster=state.table_at(0xABDA8).cursor())
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF68A, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'unit', 5)
    frame = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.unit))),
        candidates=state.table_at(0xFFFF9FFF).cursor())
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF68A, 2), 16)
    frame = _movement_move(state, frame, 'count', 0, 16)
    frame = _movement_move(state, frame, 'count', frame.candidates.byte(low16(frame.unit)), 8)
    frame = _continuation_shift_word_fields(state, frame, 'count', 1)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.count)), 8)
    frame = _continuation_shift_word_fields(state, frame, 'unit', 3)
    frame = _continuation_shift_word_fields(state, frame, 'unit', 7)
    frame = _movement_move(state, frame, 'count', frame.roster.byte(low16(frame.count), 1), 8)
    frame = _movement_move(state, frame, 'count', low8(frame.count), 8)
    frame = _continuation_shift_word_fields(state, frame, 'count', 3)
    frame = _continuation_shift_word_fields(state, frame, 'count', 7)
    frame = _movement_move(state, frame, 'distance', low16(frame.count), 16)
    frame = _movement_compare(state, frame, low16(frame.distance), 0x5000, 16)
    upper_side = not bool(frame.status & 5)
    if upper_side:
        frame = _command_policy_sub_word_fields(state, frame, 'distance', 0x3400)
    else:
        frame = _movement_add_word(state, frame, 'distance', 0x3400)
    frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.distance), 16)
    rejected = not bool(frame.status & 5) if upper_side else bool(frame.status & 1)
    return _command_policy_carry_fields(state, frame, rejected)


def _sample_retreat_coordinate_fields(state: SceneState, frame: FirstDeploymentFrame,
        second_side: bool) -> FirstDeploymentFrame:
    """One mirrored horizontal sample with unchanged RNG and rounding owners."""
    if type(second_side) is not bool: raise ValueError('actual retreat side required')
    if second_side:
        frame = _movement_move(state, frame, 'offset_x', 0x5C00, 16)
        frame = _command_policy_sub_word_fields(state, frame, 'offset_x', low16(frame.unit))
    else:
        frame = _movement_move(state, frame, 'offset_x', low16(frame.unit), 16)
        frame = _command_policy_sub_word_fields(state, frame, 'offset_x', 0x1400)
    if frame.status & 1: return _command_policy_carry_fields(state, frame, True)
    frame = _movement_compare(state, frame, low16(frame.offset_x), 0x2000, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'offset_x', 0x2000, 16)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x22ACC if second_side else 0x2291E)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_multiply_word(state, frame, 'offset_x', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'offset_x')
    frame = _movement_move(state, frame, 'distance', low16(frame.unit), 16)
    if second_side:
        frame = _movement_add_word(state, frame, 'distance', 0x800)
        frame = _movement_add_word(state, frame, 'distance', low16(frame.offset_x))
    else:
        frame = _command_policy_sub_word_fields(state, frame, 'distance', 0x800)
        frame = _command_policy_sub_word_fields(state, frame, 'distance', low16(frame.offset_x))
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x22AE4 if second_side else 0x22936)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_multiply_word(state, frame, 'target_x', 0x1800)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_compare(state, frame, low16(frame.count), 0x5000, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'target_y', low16(frame.count), 16)
        frame = _command_policy_sub_word_fields(state, frame, 'target_y', 0x1C00)
        frame = _command_policy_sub_word_fields(state, frame, 'target_y', low16(frame.target_x))
        frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
    else:
        frame = _movement_add_word(state, frame, 'target_x', low16(frame.count))
        frame = _movement_add_word(state, frame, 'target_x', 0x1C00)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
    frame = _command_policy_call_fields(state, frame, 0x23198, 0x22B14 if second_side else 0x22966)
    frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)
    return _command_policy_carry_fields(state, frame, False)


def sample_first_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22902: full first-side horizontal retreat coordinate sampler."""
    frame = _resource_cost_frame(state, frame, 0x22902)
    return _sample_retreat_coordinate_fields(state, frame, False)


def sample_second_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22AB0: full second-side horizontal retreat coordinate sampler."""
    frame = _resource_cost_frame(state, frame, 0x22AB0)
    return _sample_retreat_coordinate_fields(state, frame, True)


def round_retreat_city_anchor_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22978: project the real coordinate rounding callee, without a random sample."""
    frame = _resource_cost_frame(state, frame, 0x22978)
    frame = _movement_move(state, frame, 'distance', low16(frame.unit), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
    frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
    frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
    frame = _command_policy_call_fields(state, frame, 0x23198, 0x22984)
    frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
    return _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)


def _constrain_retreat_fallback_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int) -> FirstDeploymentFrame:
    """Three original fallback entries share23198, not an extra CALL slot."""
    continuations = {0x22B26: 0x22B32, 0x22C78: 0x22C80, 0x22EE0: 0x22EE8}
    if entry not in continuations:
        raise ValueError('an actual retreat coordinate fallback entry is required')
    frame = _resource_cost_frame(state, frame, entry)
    if entry == 0x22B26:
        frame = _movement_move(state, frame, 'distance', low16(frame.unit), 16)
        frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
        frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
    else:
        frame = _movement_move(state, frame, 'target_x', low16(frame.unit), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.count), 16)
    frame = _command_policy_call_fields(state, frame, 0x23198, continuations[entry])
    frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
    return _movement_move(state, frame, 'target_x', low16(frame.target_y), 16)


def constrain_transposed_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22B26: retain the original D4 staging before the23198 coordinate call."""
    return _constrain_retreat_fallback_fields(state, frame, 0x22B26)


def constrain_contact_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22C78: constrain the live D2/D3 pair through the original22C80 return."""
    return _constrain_retreat_fallback_fields(state, frame, 0x22C78)


def constrain_second_contact_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22EE0: same original coordinate role with its distinct22EE8 return."""
    return _constrain_retreat_fallback_fields(state, frame, 0x22EE0)


def test_retreat_readiness_contact_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """2298A: unmarked actor readiness bands followed by real contact/first action."""
    frame = _resource_cost_frame(state, frame, 0x2298A)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA754).cursor())
    frame = _movement_test(state, frame, frame.roster.byte(low16(frame.choice)), 8)
    if not frame.status & 4: return _command_policy_carry_fields(state, frame, False)
    frame = first_replace(frame, roster=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _movement_move(state, frame, 'unit', 0, 16)
    for threshold in (50, 70, 90):
        frame = _movement_compare(state, frame, low16(frame.target_x), threshold, 16)
        if frame.status & 1: break
        frame = _movement_adjust_word(state, frame, 'unit', 1)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x229C8)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.unit), 16)
    if not frame.status & 1: return _command_policy_carry_fields(state, frame, False)
    frame = _command_policy_call_fields(state, frame, 0x234D2, 0x229DC)
    frame = _movement_test(state, frame, state.read(0xFFFFD300, 2), 16)
    if frame.status & 8: return _command_policy_carry_fields(state, frame, False)
    return _command_policy_call_fields(state, frame, 0x25FD2, 0x229E8)


def execute_second_retreat_continuation_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """229F2: original retreat decision, contact fallback and second-side target update."""
    frame = _resource_cost_frame(state, frame, 0x229F2)
    return _retreat_attempts_fields(state, frame,
        ((0x22756, 0x229F6), (0x2298A, 0x229FC), (0x22A06, 0x22A04)))


def _commit_retreat_target_fields(state: SceneState, frame: FirstDeploymentFrame,
        origin: int) -> FirstDeploymentFrame:
    """Shared target packet commit with each caller's real map/terrain slots."""
    profiles={0x227E8:(0x2285A,0x22874,0x22882,0x22890),
        0x22A06:(0x22A78,0x22A92,0x22AA0,0x22AAE),
        0x22B56:(0x22BE0,0x22BFA,0x22C08,0x22C16),
        0x22E22:(0x22EA8,0x22EC2,0x22ED0,0x22EDE),
        0x22F0C:(0x22F92,0x22FAC,0x22FBA,0x22FC8)}
    if origin not in profiles:raise ValueError('actual retreat packet variant required')
    map_return,terrain_return,city_return,duel_return=profiles[origin]
    frame = first_replace(frame, roster=state.table_at(0xFF2C00).cursor())
    frame = _movement_move(state, frame, 'target_y', low16(frame.choice), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_y', 2)
    frame = _continuation_shift_word_fields(state, frame, 'distance', 7, True)
    frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_y), low16(frame.distance))
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 7, True)
    frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_y), low16(frame.target_x), displacement=2)
    frame = first_replace(frame, roster=state.table_at(0xFFFFAE28).cursor())
    frame = _settlement_write_byte_fields(state, frame, frame.roster, value=1, offset=low16(frame.choice))
    frame = _command_policy_call_fields(state, frame, 0x1A438, map_return)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFA150).cursor())
    frame = _movement_move(state, frame, 'target_x', low16(frame.choice), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)
    frame = _movement_move(state, frame, 'target_y', frame.candidates.word(low16(frame.target_x)), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_y', 7, True)
    frame = _movement_move(state, frame, 'unit', frame.candidates.word(low16(frame.target_x), 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'unit', 7, True)
    frame = _command_policy_call_fields(state, frame, 0x1A44E, terrain_return)
    frame = _movement_compare(state, frame, low8(frame.target_x), 6, 8)
    if not frame.status & 4:
        return _command_policy_call_fields(state, frame, 0x1DCAA, city_return)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.choice))
    return _command_policy_call_fields(state, frame, 0x1DB7C, duel_return)


def _update_retreat_position_fields(state: SceneState, frame: FirstDeploymentFrame,
        origin: int) -> FirstDeploymentFrame:
    profiles={0x227E8:(0x22824,0x2282C,0x22978,0x22834,False),
        0x22A06:(0x22A42,0x22A4A,0x22B26,0x22A52,True),
        0x22B56:(0x22BAA,0x22BB2,0x22C78,0x22BBA,False),
        0x22E22:(0x22E72,0x22E7A,0x22EE0,0x22E82,True),
        0x22F0C:(0x22F5C,0x22F64,0x22B26,0x22F6C,True)}
    if origin not in profiles:raise ValueError('actual complete retreat update entry required')
    side_return,sample_return,fallback_target,fallback_return,second_side=profiles[origin]
    for carrier,address in (('roster',0xFFFFA654),('roster',0xFF3CC2),('candidates',0xFF3DC2)):
        frame=first_replace(frame,**{carrier:state.table_at(address).cursor()})
        frame=_movement_test(state,frame,(frame.roster if carrier == 'roster' else frame.candidates).byte(low16(frame.choice)),8)
        if not frame.status&4:return frame
    direct_sample=True
    if origin in (0x22B56,0x22E22,0x22F0C):
        first_return={0x22B56:0x22B82,0x22E22:0x22E4E,0x22F0C:0x22F38}[origin]
        frame=_command_policy_call_fields(state,frame,0x22C18,first_return)
        if frame.status&1:
            if origin==0x22B56:
                frame=_command_policy_store_word_fields(state,frame,0xFFFFF3A6,low16(frame.count))
            contact_return={0x22B56:0x22B8E,0x22E22:0x22E56,0x22F0C:0x22F40}[origin]
            frame=_command_policy_call_fields(state,frame,0x22C86,contact_return)
            if frame.status&1:return frame
            direct_sample=False
    if direct_sample:
        frame=first_replace(frame,roster=state.table_at(0xFFFFA150).cursor())
        frame=_movement_move(state,frame,'offset_y',low16(frame.choice),16)
        frame=_continuation_shift_word_fields(state,frame,'offset_y',2)
        frame=_movement_move(state,frame,'target_x',frame.roster.word(low16(frame.offset_y)),16)
        frame=_movement_move(state,frame,'target_y',frame.roster.word(low16(frame.offset_y),2),16)
        frame=_command_policy_call_fields(state,frame,0x22892,side_return)
        failed=bool(frame.status&1)
        if not failed:
            frame=_command_policy_call_fields(state,frame,0x22AB0 if second_side else 0x22902,sample_return)
            failed=bool(frame.status&1)
        if failed:
            frame=_command_policy_call_fields(state,frame,fallback_target,fallback_return)
    return _commit_retreat_target_fields(state,frame,origin)


def update_first_retreat_position_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """227E8: full actor eligibility, sampled target and real map action commitment."""
    return _update_retreat_position_fields(state,_resource_cost_frame(state,frame,0x227E8),0x227E8)


def update_second_retreat_position_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22A06: full mirrored actor eligibility, target and map action commitment."""
    return _update_retreat_position_fields(state,_resource_cost_frame(state,frame,0x22A06),0x22A06)


def update_contact_retreat_position_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int=0x22B56) -> FirstDeploymentFrame:
    """22B56: three true entries share contact-or-coordinate target commitment."""
    if entry not in (0x22B56,0x22E22,0x22F0C):raise ValueError('actual contact update alternate required')
    return _update_retreat_position_fields(state,_resource_cost_frame(state,frame,entry),entry)


def choose_contact_retreat_coordinate_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22C86: readiness gate then the actual selected member's coordinate rounding."""
    frame=_resource_cost_frame(state,frame,0x22C86)
    frame=_command_policy_call_fields(state,frame,0x22CB8,0x22C8A)
    if frame.status&1:return frame
    frame=first_replace(frame,candidates=state.table_at(0xFF2C00).cursor())
    frame=_movement_move(state,frame,'target_x',low16(frame.choice),16)
    frame=_continuation_shift_word_fields(state,frame,'target_x',2)
    frame=first_replace(frame,roster=state.table_at(0xFFFFA150).cursor())
    frame=_movement_move(state,frame,'count',state.read(0xFFFFF3A6,2),16)
    frame=_continuation_shift_word_fields(state,frame,'count',2)
    frame=_movement_move(state,frame,'target_x',frame.roster.word(low16(frame.count)),16)
    frame=_movement_move(state,frame,'target_y',frame.roster.word(low16(frame.count),2),16)
    frame=_command_policy_call_fields(state,frame,0x23198,0x22CAE)
    frame=_movement_move(state,frame,'distance',low16(frame.target_x),16)
    frame=_movement_move(state,frame,'target_x',low16(frame.target_y),16)
    return _command_policy_carry_fields(state,frame,False)


def try_contact_retreat_readiness_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """22CB8: original 70/90 readiness bands and the real first-side contact action."""
    frame=_resource_cost_frame(state,frame,0x22CB8)
    frame=first_replace(frame,roster=state.table_at(0xFFFFB600).cursor())
    frame=_movement_move(state,frame,'target_x',low16(frame.choice),16)
    frame=_continuation_shift_word_fields(state,frame,'target_x',1)
    frame=_movement_move(state,frame,'target_x',frame.roster.word(low16(frame.target_x)),16)
    frame=_movement_move(state,frame,'unit',0,16)
    for threshold in (70,90):
        frame=_movement_compare(state,frame,low16(frame.target_x),threshold,16)
        if frame.status&1:break
        frame=_movement_adjust_word(state,frame,'unit',1)
    frame=_command_policy_call_fields(state,frame,0x83D4,0x22CE0)
    frame=_movement_move_long(state,frame,'target_x',frame.target_x&65535)
    frame=_special_action_shift_long(state,frame,'target_x',2)
    frame=_special_action_swap(state,frame,'target_x')
    frame=_movement_compare(state,frame,low16(frame.target_x),low16(frame.unit),16)
    if frame.status&1:return _command_policy_call_fields(state,frame,0x25FD2,0x22CF4)
    return _command_policy_carry_fields(state,frame,False)


def execute_guarded_retreat_strategy_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int=0x22B38) -> FirstDeploymentFrame:
    """22B38: ten real wrapper entries share ordered original fallbacks, without an invented RTS."""
    frame=_resource_cost_frame(state,frame,entry)
    # These are semantic retry profiles. Calls retain their actual continuations;
    # a taken branch into another wrapper's tail creates no extra call slot.
    primary=((0x22756,0x22B44),(0x22D30,0x22B4C),(0x22B56,0x22B54))
    second=((0x22756,0x22E10),(0x22D30,0x22E18),(0x22E22,0x22E20))
    third=((0x22756,0x22EFA),(0x22D30,0x22F02),(0x22F0C,0x22F0A))
    fallback=((0x22756,0x22FD6),(0x22FE8,0x22FDE),(0x224F4,0x22FE6))
    simple={0x22B38:(0x22CFE,0x22B3C,primary,fallback),
        0x22E04:(0x22CFE,0x22E08,second,fallback),
        0x22EEE:(0x22CFE,0x22EF2,third,fallback),
        0x22FCA:(0x23046,0x22FCE,fallback,second),
        0x23072:(0x23046,0x23074,((0x22756,0x2307C),(0x22FE8,0x23084),(0x224F4,0x2308C)),third),
        0x2308E:(0x23046,0x23090,((0x22756,0x23098),(0x22FE8,0x230A0),(0x224F4,0x230A8)),primary)}
    if entry in simple:
        gate,slot,normal,failed=simple[entry]
        frame=_command_policy_call_fields(state,frame,gate,slot)
        return _retreat_attempts_fields(state,frame,failed if frame.status&1 else normal)
    complex_profiles={0x230AA:(0x230AC,0x230B4,0x230BC,primary,
        ((0x22756,0x230C4),(0x22D30,0x230CC),(0x2298A,0x230D4),(0x230DE,0x230DC))),
        0x23414:(0x23418,0x23420,0x23426,second,
        ((0x22756,0x2342E),(0x22D30,0x23436),(0x2298A,0x2343E),(0x23448,0x23446))),
        0x23452:(0x23456,0x2345E,0x23466,third,
        ((0x22756,0x2346E),(0x22D30,0x23476),(0x2298A,0x2347E),(0x23488,0x23486))),
        0x23492:(0x23496,0x2349E,0x234A6,primary,
        ((0x22756,0x234AE),(0x22D30,0x234B6),(0x2298A,0x234BE),(0x234C8,0x234C6)))}
    if entry not in complex_profiles:raise ValueError('actual complete retreat strategy entry required')
    first_slot,second_slot,third_slot,failed,attempts=complex_profiles[entry]
    frame=_command_policy_call_fields(state,frame,0x23046,first_slot)
    if frame.status&1:return _retreat_attempts_fields(state,frame,failed)
    frame=_command_policy_call_fields(state,frame,0x22CFE,second_slot)
    if frame.status&1:return _retreat_attempts_fields(state,frame,fallback)
    frame=_command_policy_call_fields(state,frame,0x233E2,third_slot)
    if frame.status&1:return _retreat_attempts_fields(state,frame,failed)
    return _retreat_attempts_fields(state,frame,attempts)


"""Current full-frame command assignments, loyalty, funds and menu dispatch.

Physical WORD saves belong to these owners. Child calls reuse the one existing
command-call service; unknown menu, display or device children stop with their
real return LONG still present. No policy result or hardware progress is guessed.
"""
from ..high_level_scene_flows.business_scene import _glyph_shift_long_fields
from ..high_level_gameplay_flow.contexts_services import SceneRefreshMemory
from ..high_level_main_flows.business_movement_support import _movement_arithmetic_long


def _command_detail_push_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        value: int) -> FirstDeploymentFrame:
    """One actual MOVE.W -(SP), including its flags, not a new call frame."""
    stack = frame.stack_cursor.advance(-2)
    frame = _settlement_store_word_fields(state, frame, stack, 0, value)
    return first_replace(frame, stack_cursor=stack)


def _command_detail_pop_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        destination) -> FirstDeploymentFrame:
    """One actual (SP)+ WORD; destination is a closed address or real D carrier."""
    value = frame.stack_cursor.word()
    if isinstance(destination, str):
        frame = _movement_move(state, frame, destination, value, 16)
    else:
        frame = _command_policy_store_word_fields(state, frame, destination, value)
    return first_replace(frame, stack_cursor=frame.stack_cursor.advance(2))


def _command_detail_compare_long_fields(state: SceneState, frame: FirstDeploymentFrame,
        destination: int, source: int) -> FirstDeploymentFrame:
    """Project the sole CMP.L primitive; its X is retained, not recomputed."""
    frame = _first_compare_long(frame, destination, source)
    state.sr = (state.sr & 65504) | frame.status
    return frame


def _command_detail_finish_fields(state: SceneState, frame: FirstDeploymentFrame,
        phase: int) -> FirstDeploymentFrame:
    return _command_policy_store_word_fields(state, frame, 0xFFFFF728, phase)


def _command_detail_member_byte_fields(state: SceneState, frame: FirstDeploymentFrame,
        selected: int) -> FirstDeploymentFrame:
    """Original CD00 record+1 lookup; D0.W and then D0.B retain their upper parts."""
    frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor())
    frame = _movement_move(state, frame, 'target_x', selected, 16)
    return _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x), 1), 8)


def _command_detail_player_byte_fields(state: SceneState, frame: FirstDeploymentFrame,
        selected: int, carrier: str='target_x') -> FirstDeploymentFrame:
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, carrier, selected, 16)
    return _movement_move(state, frame, carrier, frame.roster.byte(low16(frame.carrier(carrier))), 8)


def _command_detail_notice_fields(state: SceneState, frame: FirstDeploymentFrame,
        message: int, continuation: int) -> FirstDeploymentFrame:
    """Shared message tail with each owner's genuine BSR/JSR continuation."""
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, message)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 0, True)
    return _command_policy_call_fields(state, frame, 0x30A74, continuation)


def open_command_phase_dispatch_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3100C: true entry into the already-restored command phase selector."""
    frame = _resource_cost_frame(state, frame, 0x3100C)
    return _command_policy_call_fields(state, frame, 0x31A0C, 0x31012)


def open_assignment_menu_dispatch_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """31014: true assignment menu entry, preserving its original outer call."""
    frame = _resource_cost_frame(state, frame, 0x31014)
    return _command_policy_call_fields(state, frame, 0x3256A, 0x3101A)


def open_city_action_menu_dispatch_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3101C: true city-action menu entry and original dispatcher return."""
    frame = _resource_cost_frame(state, frame, 0x3101C)
    return _command_policy_call_fields(state, frame, 0x33040, 0x31022)


def advance_command_notice_phase_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """312F8: advance the message phase, present its live label and arm countdown."""
    frame = _resource_cost_frame(state, frame, 0x312F8)
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF362, 1)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF740, 2), 16)
    frame = _command_policy_call_fields(state, frame, 0x676F2, 0x31306)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF608, 300)


def _assign_command_project_fields(state: SceneState, frame: FirstDeploymentFrame,
        second_slot: bool) -> FirstDeploymentFrame:
    """Two assignment slots share their actual selected-record packet layout."""
    if type(second_slot) is not bool: raise ValueError('actual assignment slot required')
    choice_target, choice_return, amount_target, amount_return, relation_return = (
        (0x32340, 0x322F4, 0x3236E, 0x32302, 0x3231C) if second_slot else
        (0x32260, 0x32214, 0x3229C, 0x32222, 0x3223C))
    frame = _command_policy_call_fields(state, frame, choice_target, choice_return)
    frame = _movement_test(state, frame, low16(frame.target_y), 16)
    if not frame.status & 8:
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
        frame = _command_policy_call_fields(state, frame, amount_target, amount_return)
        frame = _movement_test_long(state, frame, state.read(0xFFFFF39E, 4))
        if not frame.status & 4:
            # 3222A..32232 / 3230A..32312: original indexed MOVE.B #1 store.
            frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor())
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
            state.write(frame.roster.address(low16(frame.target_x)), 1, 1)
            frame = _movement_test(state, frame, 1, 8)
            frame = _command_policy_call_fields(state, frame, 0x320A0, relation_return)
            frame = first_replace(frame, roster=state.table_at(0xFFFFE80C).cursor())
            frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
            frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
            frame = _movement_add_word(state, frame, 'target_x', state.read(0xFFFFF364, 2))
            frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)
            displacement = 0 if second_slot else 4
            frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x),
                state.read(0xFFFFF3A6, 2), displacement=displacement)
            frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x),
                state.read(0xFFFFF3A0, 2), displacement=displacement + 2)
    return _command_detail_finish_fields(state, frame, 7 if second_slot else 6)


def assign_city_second_project_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32210: select and commit the city's second paired project slot."""
    return _assign_command_project_fields(state, _resource_cost_frame(state, frame, 0x32210), False)


def assign_city_first_project_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """322F0: select and commit the city's first paired project slot."""
    return _assign_command_project_fields(state, _resource_cost_frame(state, frame, 0x322F0), True)


def select_city_assignment_replacement_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """323C2: conditional city assignment selection, head replacement and phase14."""
    frame = _resource_cost_frame(state, frame, 0x323C2)
    frame = first_replace(frame, roster=state.table_at(0xFFFFCDFC).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)
    frame = _movement_test(state, frame, frame.roster.byte(low16(frame.target_x)), 8)
    if frame.status & 4:
        frame = _command_policy_call_fields(state, frame, 0x32404, 0x323D8)
        frame = _movement_test(state, frame, low16(frame.target_x), 16)
        if not frame.status & 8:
            frame = _command_policy_store_word_fields(state, frame, 0xFFFFF688, low16(frame.target_x))
            frame = _command_policy_call_fields(state, frame, 0x3244A, 0x323E6)
            frame = _movement_test(state, frame, low16(frame.distance), 16)
            if not frame.status & 8:
                frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, low16(frame.distance))
                frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A8, state.read(0xFFFFF364, 2))
                frame = _command_policy_call_fields(state, frame, 0xE7B0, 0x323FC)
    return _command_detail_finish_fields(state, frame, 14)


def finish_city_assignment_selection_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """324EE: complete the real selection child and advance to phase15."""
    frame = _resource_cost_frame(state, frame, 0x324EE)
    frame = _command_policy_call_fields(state, frame, 0x324FA, 0x324F2)
    return _command_detail_finish_fields(state, frame, 15)


def close_city_assignment_menu_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32562: original negative phase exit marker."""
    return _command_detail_finish_fields(state, _resource_cost_frame(state, frame, 0x32562), 65535)


def _command_detail_dispatch_menu_fields(state: SceneState, frame: FirstDeploymentFrame,
        table_address: int, call_base: int, continuation: int) -> FirstDeploymentFrame:
    """Two live WORD-indexed menu loops; table/code remain real read operands."""
    if (table_address, call_base, continuation) not in ((0x32582, 0x32592, 0x3257E), (0x33058, 0x3306E, 0x33054)):
        raise ValueError('actual command menu dispatch geometry required')
    while True:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF728, 2), 16)
        if frame.status & 8: return frame
        frame = _movement_adjust_word(state, frame, 'target_x', -1)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_x', state.table_at(table_address).word(low16(frame.target_x)), 16)
        frame = _command_policy_call_fields(state, frame, u32(call_base + s16(low16(frame.target_x))), continuation)


def dispatch_city_assignment_phases_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3256A: full original assignment menu loop and signed WORD dynamic calls."""
    return _command_detail_dispatch_menu_fields(state, _resource_cost_frame(state, frame, 0x3256A), 0x32582, 0x32592, 0x3257E)


def execute_city_loyalty_change_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32936: select city/member, ownership notice and original loyalty outcome."""
    frame = _resource_cost_frame(state, frame, 0x32936)
    frame = _command_policy_call_fields(state, frame, 0x32A3A, 0x3293A)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_policy_call_fields(state, frame, 0x32A68, 0x32946)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3F2, low16(frame.target_y))
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A8, low16(frame.unit))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, state.read(0xFFFFF364, 2))
    frame = _command_detail_player_byte_fields(state, frame, low16(frame.unit))
    allied = False
    for address in (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F):
        frame = _movement_compare(state, frame, low8(frame.target_x), state.read(address, 1), 8)
        if frame.status & 4:
            allied = True
            break
    if allied:
        frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _movement_move(state, frame, 'target_x', frame.target_x & 255, 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, frame.roster.word(low16(frame.target_x)))
        frame = _command_detail_notice_fields(state, frame, 0x87, 0x329A0)
        frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3A8, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC300).cursor())
    frame = _movement_compare(state, frame, frame.roster.byte(low16(frame.unit)), 0x50, 8)
    if frame.status & 1: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x329BC)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _glyph_shift_long_fields(SceneRefreshMemory(state), frame, 'target_x', 3)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_test(state, frame, low16(frame.target_x), 16)
    if frame.status & 4:
        frame = _command_policy_call_fields(state, frame, 0xF088, 0x329F6)
        frame = _command_policy_call_fields(state, frame, 0x32B42, 0x329FA)
        notice = 0x89
    else:
        frame = _command_policy_call_fields(state, frame, 0xEE16, 0x329D2)
        frame = _movement_test(state, frame, state.read(0xFFFFF3C8, 2), 16)
        if frame.status & 4: return _command_detail_finish_fields(state, frame, 3)
        frame = _command_policy_call_fields(state, frame, 0x32B10, 0x329DE)
        notice = 0x88
    if not frame.status & 1: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, state.read(0xFFFFF3F2, 2))
    frame = _movement_move(state, frame, 'target_x', notice, 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, low16(frame.target_x))
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
    frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3F2, 2), 16)
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _settlement_write_byte_fields(state, frame, state.table_at(0xFFFFF377), value=frame.roster.byte(low16(frame.target_x)))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 0, True)
    frame = _command_policy_call_fields(state, frame, 0x30A74, 0x32A2E)
    frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    return _command_detail_finish_fields(state, frame, 3)


def execute_city_training_choice_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32B88: training selection, ownership notice, cost check and result."""
    frame = _resource_cost_frame(state, frame, 0x32B88)
    frame = _command_policy_call_fields(state, frame, 0x32C40, 0x32B8C)
    frame = _movement_test(state, frame, low16(frame.unit), 16)
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 8)
    frame = _movement_compare(state, frame, low16(frame.target_x), 70, 16)
    if not frame.status & 5: return _command_detail_finish_fields(state, frame, 8)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A8, low16(frame.target_y))
    frame = _command_policy_call_fields(state, frame, 0x32D72, 0x32BA2)
    frame = _movement_test(state, frame, low16(frame.target_y), 16)
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 8)
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A8, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x)), 8)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, low16(frame.target_y))
    frame = _continuation_shift_word_fields(state, frame, 'target_y', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, frame.roster.word(low16(frame.target_y)))
    frame = _command_detail_notice_fields(state, frame, 0x87, 0x32BDE)
    frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    for target, continuation in ((0xF7DA, 0x32BE8), (0xF82C, 0x32BEE), (0xFAE0, 0x32BF4)):
        frame = _command_policy_call_fields(state, frame, target, continuation)
    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.count), 16)
    if not frame.status & 1:
        frame = _command_policy_call_fields(state, frame, 0x32CA8, 0x32BFC)
    else:
        frame = _command_policy_call_fields(state, frame, 0xF990, 0x32C06)
        frame = _command_policy_call_fields(state, frame, 0xF9D0, 0x32C0C)
        frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
        frame = _command_detail_player_byte_fields(state, frame, state.read(0xFFFFF3A8, 2))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF646, state.read(0xFFFFF3A8, 2))
        frame = _command_detail_notice_fields(state, frame, 0x8C, 0x32C34)
        frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    return _command_detail_finish_fields(state, frame, 8)


def execute_city_funds_choice_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32DCE: selected city's funds relation, notice or actual transfer outcome."""
    frame = _resource_cost_frame(state, frame, 0x32DCE)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFE730, 2), 16)
    allied = False
    for address in (0xFFFFF67A, 0xFFFFF67C, 0xFFFFF67E):
        frame = _movement_compare(state, frame, low16(frame.target_x), state.read(address, 2), 16)
        if frame.status & 4:
            allied = True
            break
    if allied:
        frame = _command_policy_call_fields(state, frame, 0x32EA0, 0x32E62)
        if not frame.status & 1:
            frame = _command_policy_call_fields(state, frame, 0x32FC6, 0x32E6A)
    else:
        frame = _command_policy_call_fields(state, frame, 0x32E72, 0x32DEE)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
        if frame.status & 8:
            return _command_detail_finish_fields(state, frame, 2)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, state.read(0xFFFFF364, 2))
        frame = _command_policy_call_fields(state, frame, 0xEA38, 0x32E02)
        frame = first_replace(frame, roster=state.table_at(4294954240).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
        frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))
        frame = _command_policy_call_fields(state, frame, 0x320A0, 0x32E14)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE710).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
        frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFE730, 2), 16)
        frame = _postbattle_bit_fields(frame, bool(frame.target_x & 1 << (frame.target_y & 31)))
        state.sr = state.sr & 65504 | frame.status
        if not frame.status & 4:
            frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
            for source_address, output_address in ((0xFFFFF376, 0xFFFFF3D0), (0xFFFFE730, 0xFFFFF3D2)):
                frame = _movement_move(state, frame, 'target_x', state.read(source_address, 2), 16)
                frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
                frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
                frame = _command_policy_store_word_fields(state, frame, output_address, low16(frame.target_x))
            frame = _command_detail_notice_fields(state, frame, 0xA3, 0x32E5A)
    return _command_detail_finish_fields(state, frame, 2)


def allocate_city_random_funds_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32EA0: original compared-bank funds policy, notices and exact A1 debit."""
    frame = _resource_cost_frame(state, frame, 0x32EA0)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x32EA6)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)
    frame = first_replace(frame, roster=state.table_at(0xFFFFDFFC).cursor(), candidates=state.table_at(0xFFFFE09C).cursor())
    frame = _movement_move(state, frame, 'unit', 0, 16)
    frame = _movement_move_long(state, frame, 'target_y', frame.roster.long(low16(frame.target_x)))
    frame = _command_detail_compare_long_fields(state, frame, frame.target_y, frame.candidates.long(low16(frame.target_x)))
    if frame.status & 1:
        frame = _movement_move_long(state, frame, 'target_y', frame.candidates.long(low16(frame.target_x)))
        frame = _movement_adjust_word(state, frame, 'unit', 1)
    frame = _command_detail_compare_long_fields(state, frame, frame.target_y, 5000)
    if frame.status & 1:
        frame = _command_policy_call_fields(state, frame, 0x32E72, 0x32ED4)
        frame = _movement_test(state, frame, low16(frame.target_y), 16)
        if frame.status & 8: return _command_policy_carry_fields(state, frame, True)
        frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, low16(frame.target_x))
        frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, 0x81)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, state.read(0xFFFFE730, 2))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 0, True)
        frame = _command_policy_call_fields(state, frame, 0x30A74, 0x32F04)
        frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
        frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3C8, 0, True)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, 0x84)
        frame = first_replace(frame, roster=state.table_at(0xFFFFCD00).cursor())
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3D2, 2), 16)
        frame = _settlement_write_byte_fields(state, frame, frame.roster, 1, low16(frame.target_x))
        frame = _command_policy_call_fields(state, frame, 0x320A0, 0x32F24)
        return _command_policy_carry_fields(state, frame, False)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, low16(frame.target_x))
    frame = _command_detail_push_word_fields(state, frame, low16(frame.unit))
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, 0x81)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, state.read(0xFFFFE730, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 0, True)
    frame = _command_policy_call_fields(state, frame, 0x30A74, 0x32F54)
    frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    frame = _command_detail_pop_word_fields(state, frame, 'unit')
    frame = _movement_move_long(state, frame, 'target_y', 0)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF61C, 2), 16)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_y)
    frame = _continuation_shift_word_fields(state, frame, 'target_y', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_y', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_add_word(state, frame, 'target_y', 10)
    frame = _movement_multiply_word(state, frame, 'target_y', 100)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 2)
    frame = _command_policy_store_long_fields(state, frame, 0xFFFFF3C8, frame.target_y)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF742, low16(frame.unit))
    secondary_bank = not bool(frame.status & 4)
    # Original 32F98 changes A0 to E09F, but 32F9C deliberately uses A1.
    # This source fact is retained; natural game impact remains unknown.
    frame = first_replace(frame, roster=state.table_at(0xFFFFE09F if secondary_bank else 0xFFFFDFFC).cursor())
    destination = frame.candidates if secondary_bank else frame.roster
    old = destination.long(low16(frame.target_x))
    frame, changed = _movement_binary_flags(state, frame, old, frame.target_y, 32, True)
    destination.set_long(low16(frame.target_x), changed)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF740, 0x83 if secondary_bank else 0x82)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.word(low16(frame.target_x)), 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, low16(frame.target_x))
    return _command_policy_carry_fields(state, frame, False)


def dispatch_city_action_phases_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """33040: full city action phase loop with actual signed live WORD targets."""
    return _command_detail_dispatch_menu_fields(state, _resource_cost_frame(state, frame, 0x33040), 0x33058, 0x3306E, 0x33054)


def execute_city_resource_action_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3306E: command count gate, selected actor and actual resource sequence."""
    frame = _resource_cost_frame(state, frame, 0x3306E)
    frame = _command_policy_call_fields(state, frame, 0x330CC, 0x33072)
    frame = _movement_compare(state, frame, low16(frame.target_x), 10, 16)
    if not frame.status & 1: return _command_detail_finish_fields(state, frame, 2)
    frame = _movement_compare(state, frame, low16(frame.target_x), 1, 16)
    if frame.status & 4: return _command_detail_finish_fields(state, frame, 2)
    frame = _command_policy_call_fields(state, frame, 0x330DE, 0x33086)
    frame = _movement_test(state, frame, low16(frame.target_y), 16)
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 2)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _command_policy_call_fields(state, frame, 0x1108C, 0x3309A)
    frame = _movement_move(state, frame, 'choice', low16(frame.target_x), 16)
    if frame.status & 4: return _command_detail_finish_fields(state, frame, 2)
    for target, continuation in ((0x10AA8, 0x330A6), (0x10ADE, 0x330AC), (0x10C74, 0x330B2)):
        frame = _command_policy_call_fields(state, frame, target, continuation)
    frame = _movement_compare(state, frame, low16(frame.target_x), 4, 16)
    return _command_detail_finish_fields(state, frame, 2 if frame.status & 1 else 5)


def execute_city_member_transfer_detail_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """33322: full member transfer, saved selections and ownership-message rules."""
    frame = _resource_cost_frame(state, frame, 0x33322)
    frame = _movement_test(state, frame, state.read(0xFFFFF72C, 2), 16)
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 3)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF630, 65535)
    frame = _command_policy_call_fields(state, frame, 0x5F48, 0x3333A)
    frame = _movement_compare(state, frame, low16(frame.count), 10, 16)
    if not frame.status & 1: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_policy_call_fields(state, frame, 0x333F4, 0x33346)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, low16(frame.target_y))
    if frame.status & 8: return _command_detail_finish_fields(state, frame, 3)
    frame = _command_detail_player_byte_fields(state, frame, state.read(0xFFFFF3A8, 2))
    frame = _command_detail_push_word_fields(state, frame, low16(frame.target_x))
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF3A6, 2))
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF3F2, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF392, state.read(0xFFFFF364, 2))
    frame = _command_policy_call_fields(state, frame, 0x11624, 0x33370)
    frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF3F2)
    frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF3A6)
    frame = _command_detail_member_byte_fields(state, frame, state.read(0xFFFFF3A6, 2))
    frame = _command_policy_call_fields(state, frame, 0x320A0, 0x3338A)
    frame = _command_detail_pop_word_fields(state, frame, 'target_x')
    allied = False
    for address in (0xFFFFF67B, 0xFFFFF67D, 0xFFFFF67F):
        frame = _movement_compare(state, frame, low8(frame.target_x), state.read(address, 1), 8)
        if frame.status & 4:
            allied = True
            break
    skip_transfer_tail = False
    if allied:
        frame = first_replace(frame, roster=state.table_at(0xFFFFCC00).cursor())
        frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF3F2, 2), 16)
        frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF392, 2), 16)
        frame = _movement_compare(state, frame, low8(frame.target_y), frame.roster.byte(low16(frame.unit)), 8)
        show_notice = bool(frame.status & 4)
        if not show_notice:
            frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
            frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF3A8, 2), 16)
            frame = _movement_compare(state, frame, low8(frame.target_x), frame.roster.byte(low16(frame.target_y)), 8)
            skip_transfer_tail = bool(frame.status & 4)
            show_notice = not skip_transfer_tail
        if show_notice:
            frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
            frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
            frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3D0, state.read(0xFFFFF3F2, 2))
            frame = _command_detail_notice_fields(state, frame, 0x92, 0x333E4)
            frame = _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    if not skip_transfer_tail:
        frame = _command_policy_call_fields(state, frame, 0x33422, 0x333EC)
    return _command_detail_finish_fields(state, frame, 3)


def remove_command_object_members_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3471A: count the object, remove its remaining members and close the phase."""
    frame = _resource_cost_frame(state, frame, 0x3471A)
    frame = _command_policy_call_fields(state, frame, 0x3473A, 0x3471E)
    frame = _movement_move(state, frame, 'target_y', 10, 16)
    frame = _command_policy_sub_word_fields(state, frame, 'target_y', low16(frame.target_x))
    if not frame.status & 4:
        frame = _movement_move(state, frame, 'choice', low16(frame.target_y), 16)
        frame = _command_policy_call_fields(state, frame, 0x3477A, 0x3472E)
        frame = _command_policy_call_fields(state, frame, 0x34870, 0x34732)
    return _command_detail_finish_fields(state, frame, 65535)


def tail_remove_selected_object_member_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """34870: real object address setup and JMP1B24C; no invented return LONG."""
    frame = _resource_cost_frame(state, frame, 0x34870)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor())
    frame = first_replace(frame, roster=frame.roster.advance(s16(state.read(0xFFFFF75A, 2))))
    return _command_policy_child_fields(state, frame, 0x1B24C)


"""Command record hydration, glyph packet rows and complete display tails.

Real VDP writes remain real Scene operations, hence genuine device boundaries
when unsupplied. These source bodies include their complete original sequel.
The unusual 35264 forward DBRA and resource-coordinate arithmetic are retained.
"""


def _command_packet_store_long_fields(state: SceneState, frame: FirstDeploymentFrame,
        view, offset: int, value: int) -> FirstDeploymentFrame:
    view.set_long(offset, uint(value, 32))
    return _movement_test_long(state, frame, value)


def _command_packet_advance_dbcount_fields(frame: FirstDeploymentFrame,
        carrier: str) -> FirstDeploymentFrame:
    """Original DBRA updates only the named low WORD and no condition bit."""
    return first_replace(frame, **{carrier:replace_word(frame.carrier(carrier), u16(low16(frame.carrier(carrier)) - 1))})


def _command_packet_pattern_fill_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Shared original D300 32-LONG fill; the live D3 and A1 are consumed."""
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move(state, frame, 'count', 31, 16)
    while True:
        frame = _command_packet_store_long_fields(state, frame, frame.candidates, 0, 0x11111111)
        frame = first_replace(frame, candidates=frame.candidates.advance(4))
        frame = _command_packet_advance_dbcount_fields(frame, 'count')
        if low16(frame.count) == 65535: return frame


def _command_packet_upload_fields(state: SceneState, frame: FirstDeploymentFrame,
        count: int, wait_continuation: int) -> FirstDeploymentFrame:
    """Two actual VDP upload tails; no software device or invented IRQ advance."""
    if (count, wait_continuation) not in ((319, 0x32D26), (127, 0x33012)):
        raise ValueError('actual command glyph upload role required')
    frame = _command_policy_store_long_fields(state, frame, 0xC00004, 0x40200000)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move(state, frame, 'count', count, 16)
    while True:
        value = frame.candidates.long()
        frame = first_replace(frame, candidates=frame.candidates.advance(4))
        frame = _command_policy_store_long_fields(state, frame, 0xC00000, value)
        frame = _command_packet_advance_dbcount_fields(frame, 'count')
        if low16(frame.count) == 65535: break
    return _command_policy_call_fields(state, frame, 0x55B0, wait_continuation)


def apply_city_training_result_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32CA8: full protected-member check, graphic result or saturating training gain."""
    frame = _resource_cost_frame(state, frame, 0x32CA8)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _movement_move(state, frame, 'count', 15, 16)
    protected = False
    while True:
        value = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_compare(state, frame, low16(frame.target_x), value, 16)
        if frame.status & 4:
            protected = True
            break
        frame = _command_packet_advance_dbcount_fields(frame, 'count')
        if low16(frame.count) == 65535: break
    affordable = False
    if not protected:
        frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = first_replace(frame, roster=state.table_at(0xFFFFB400).cursor())
        frame = _movement_move(state, frame, 'count', frame.roster.word(low16(frame.target_x)), 16)
        frame = _continuation_shift_word_fields(state, frame, 'count', 1, True)
        frame = _command_policy_call_fields(state, frame, 0xFAE0, 0x32CD4)
        frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.count), 16)
        affordable = not bool(frame.status & 1)
    if not protected and affordable:
        frame = _command_packet_pattern_fill_fields(state, frame)
        frame = first_replace(frame, roster=state.table_at(0x6C168).cursor())
        frame = _movement_move(state, frame, 'target_x', 1, 16)
        frame = _movement_move(state, frame, 'target_y', 3, 16)
        frame = _movement_move(state, frame, 'count', 5, 16)
        frame = _command_policy_call_fields(state, frame, 0xAE8A, 0x32D04)
        frame = _command_packet_upload_fields(state, frame, 319, 0x32D26)
        frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
        frame = _command_detail_player_byte_fields(state, frame, state.read(0xFFFFF3A8, 2))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, low16(frame.target_x))
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 6)
        frame = _command_policy_call_fields(state, frame, 0x30A74, 0x32D44)
        return _command_detail_pop_word_fields(state, frame, 0xFFFFF376)
    frame = _movement_test(state, frame, low16(frame.unit), 16)
    if frame.status & 8: return frame
    frame = _movement_move_long(state, frame, 'unit', frame.unit & 65535)
    # DIVU's exceptional flags are immediately overwritten by the following
    # actual MOVE.W; the sole retained quotient/remainder numeric rule is reused.
    frame = first_replace(frame, unit=divu_retained(frame.unit, 10))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF3A6, 2), 16)
    frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFC000).cursor())
    frame = _command_policy_change_memory_fields(state, frame,
        frame.roster.address(low16(frame.target_x)), low16(frame.unit))
    if frame.status & 1:
        frame = _settlement_store_word_fields(state, frame, frame.roster, low16(frame.target_x), 65535)
    return frame


def show_city_funds_graphic_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32FC6: full funds graphic and message sequel with real display waits."""
    frame = _resource_cost_frame(state, frame, 0x32FC6)
    frame = _command_packet_pattern_fill_fields(state, frame)
    frame = first_replace(frame, roster=state.table_at(0x33032).cursor())
    frame = _movement_move(state, frame, 'target_x', 1, 16)
    frame = _movement_move(state, frame, 'target_y', 3, 16)
    frame = _movement_move(state, frame, 'count', 2, 16)
    frame = _command_policy_call_fields(state, frame, 0xAE8A, 0x32FF0)
    frame = _command_packet_upload_fields(state, frame, 127, 0x33012)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF3A6, state.read(0xFFFFF376, 2))
    frame = _command_detail_push_word_fields(state, frame, state.read(0xFFFFF376, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF376, state.read(0xFFFFE730, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 9)
    frame = _command_policy_call_fields(state, frame, 0x30A74, 0x3302C)
    return _command_detail_pop_word_fields(state, frame, 0xFFFFF376)


def load_command_object_route_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """34D52: hydrate route/status coordinates from two real object records."""
    frame = _resource_cost_frame(state, frame, 0x34D52)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF75A, 2), 16)
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    for displacement, address in ((1, 0xFFFFF63C), (2, 0xFFFFF63E), (13, 0xFFFFF74A), (3, 0xFFFFF744)):
        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x), displacement), 8)
        frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_y))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF748, 2), 16)
    for displacement, address in ((1, 0xFFFFF640), (2, 0xFFFFF642)):
        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(low16(frame.target_x), displacement), 8)
        frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_y))
    frame = _command_policy_call_fields(state, frame, 0x651C, 0x34D96)
    frame = _command_policy_call_fields(state, frame, 0x33CF2, 0x34D9A)
    return _command_detail_finish_fields(state, frame, 22)


def load_command_object_status_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """34DA2: current object's status packet, true placement and phase22."""
    frame = _resource_cost_frame(state, frame, 0x34DA2)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor())
    frame = first_replace(frame, roster=frame.roster.advance(s16(state.read(0xFFFFF75A, 2))))
    frame = _movement_move(state, frame, 'target_y', 0, 16)
    for displacement, address in ((3, 0xFFFFF744), (13, 0xFFFFF74A)):
        frame = _movement_move(state, frame, 'target_y', frame.roster.byte(displacement), 8)
        frame = _command_policy_store_word_fields(state, frame, address, low16(frame.target_y))
    frame = _command_policy_call_fields(state, frame, 0x6518, 0x34DC2)
    frame = _command_policy_call_fields(state, frame, 0x33CF2, 0x34DC6)
    return _command_detail_finish_fields(state, frame, 22)


def finish_command_object_removal_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """35210: full object removal/reset; original forward DBRA remains unchanged."""
    frame = _resource_cost_frame(state, frame, 0x35210)
    frame = _movement_move_long(state, frame, 'target_x', state.read(0xFF382C, 4))
    frame = _movement_arithmetic_long(state, frame, 'target_x', 0xFFFF9000, True)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF75A, low16(frame.target_x))
    frame = _command_policy_call_fields(state, frame, 0x3473A, 0x35224)
    frame = _movement_move(state, frame, 'target_y', 10, 16)
    frame = _command_policy_sub_word_fields(state, frame, 'target_y', low16(frame.target_x))
    if frame.status & 4: return _command_detail_finish_fields(state, frame, 65535)
    frame = _movement_move(state, frame, 'choice', low16(frame.target_y), 16)
    frame = _command_policy_call_fields(state, frame, 0x3477A, 0x35234)
    frame = _command_policy_call_fields(state, frame, 0x34870, 0x35238)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF772, 0, True)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF68A, state.read(0xFFFFF392, 2))
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFA5F8, 65535)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF612, 0x400)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF362, 0, True)
    frame = _command_policy_store_word_fields(state, frame, 0xFFFFF352, 0, True)
    frame = _movement_move(state, frame, 'target_x', 31, 16)
    frame = first_replace(frame, roster=state.table_at(0xFFFFFB00).cursor(), candidates=state.table_at(0xFFFFFB80).cursor())
    value = frame.roster.word()
    frame = first_replace(frame, roster=frame.roster.advance(2))
    frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, value)
    frame = first_replace(frame, candidates=frame.candidates.advance(2))
    frame = _command_packet_advance_dbcount_fields(frame, 'target_x')
    # Cached 35264 51C80018 is a FORWARD branch to3527E. It is not a
    # 32-WORD palette loop. This static original fact has unknown natural impact.
    if low16(frame.target_x) == 65535:
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFA550, 65535)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFA5A4, 65535)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF36A, 0, True)
        frame = _command_policy_call_fields(state, frame, 0x1B098, 0x3527E)
    return _command_detail_finish_fields(state, frame, 65535)


def _command_packet_mark_row_width_fields(state: SceneState,
        frame: FirstDeploymentFrame, enabled: bool) -> FirstDeploymentFrame:
    """Only the actual BSET/BCLR.L15 D0 glyph-row role, same sole Z primitive."""
    if type(enabled) is not bool: raise ValueError('actual row marker bit operation required')
    frame = _postbattle_bit_fields(frame, bool(frame.target_x & 32768))
    state.sr = (state.sr & 65504) | frame.status
    return first_replace(frame, target_x=frame.target_x | 32768 if enabled else frame.target_x & 4294934527)


def append_command_variable_glyph_row_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """354DE: two-panel glyph row, resource width, wrapping coordinates and terminator."""
    frame = _resource_cost_frame(state, frame, 0x354DE)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD100).cursor())
    frame = first_replace(frame, candidates=frame.candidates.advance(s16(state.read(0xFFFFF31A, 2))))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF342, 2), 16)
    frame = first_replace(frame, roster=state.table_at(0x8991C).cursor())
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(low16(frame.target_x)), 8)
    if frame.status & 8: return frame
    if not frame.status & 4:
        frame = _movement_move(state, frame, 'target_x', frame.target_x & 255, 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
        frame = _movement_add_word(state, frame, 'target_y', 2)
        frame = _continuation_shift_word_fields(state, frame, 'target_y', 2)
        frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, low16(frame.target_y))
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_y', 1)
        frame = _movement_add_word(state, frame, 'target_y', 5)
        frame = _continuation_shift_word_fields(state, frame, 'target_y', 3, True)
        frame = _continuation_shift_word_fields(state, frame, 'target_x', 1)
        frame = _movement_add_word(state, frame, 'target_x', low16(frame.target_y))
        frame = _movement_move(state, frame, 'target_y', low16(frame.target_x), 16)
        frame = _continuation_shift_word_fields(state, frame, 'target_y', 1)
        frame = _command_packet_mark_row_width_fields(state, frame, True)
        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), low16(frame.target_x), displacement=4)
        frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.target_x))
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _command_packet_mark_row_width_fields(state, frame, False)
        frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF33E, 2), 16)
        frame = _movement_add_word(state, frame, 'unit', 2)
        frame = _movement_compare(state, frame, low16(frame.unit), 0xC17E, 16)
        if not frame.status & 5:
            frame = _command_policy_sub_word_fields(state, frame, 'unit', 0x80)
        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), low16(frame.unit), displacement=4)
        frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, state.read(0xFFFFF33E, 2))
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _movement_move(state, frame, 'unit', state.read(0xFFFFF33C, 2), 16)
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_add_word(state, frame, 'count', low16(frame.target_x))
        frame = _movement_move(state, frame, 'distance', low16(frame.target_x), 16)
        frame = _movement_adjust_word(state, frame, 'distance', -1)
        while True:
            frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), low16(frame.count), displacement=4)
            frame = _settlement_store_word_fields(state, frame, frame.candidates, 0, low16(frame.unit))
            frame = first_replace(frame, candidates=frame.candidates.advance(2))
            frame = _movement_adjust_word(state, frame, 'count', 1)
            frame = _movement_adjust_word(state, frame, 'unit', 1)
            frame = _command_packet_advance_dbcount_fields(frame, 'distance')
            if low16(frame.distance) == 65535: break
        frame = _settlement_store_word_fields(state, frame, frame.candidates, low16(frame.target_y), 0, displacement=4, clear=True)
        frame = _command_policy_store_word_fields(state, frame, 0xFFFFF33C, low16(frame.count))
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF342, 1)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF33E, 2), 16)
    frame = _command_policy_sub_word_fields(state, frame, 'target_x', 6)
    frame = _movement_compare(state, frame, low16(frame.target_x), 0xC100, 16)
    if frame.status & 1:
        frame = _movement_add_word(state, frame, 'target_x', 0x80)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF33E, low16(frame.target_x))


def append_command_blank_glyph_row_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3557C: blank paired row packet, 13 LONG pairs and wrapped live baseline."""
    frame = _resource_cost_frame(state, frame, 0x3557C)
    frame = first_replace(frame, roster=state.table_at(0xFFFFD100).cursor())
    frame = first_replace(frame, roster=frame.roster.advance(s16(state.read(0xFFFFF31A, 2))))
    frame = _command_policy_change_memory_fields(state, frame, 0xFFFFF31A, 0x70)
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0x38, 0x801A)
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, 0x801A)
    frame = first_replace(frame, roster=frame.roster.advance(2))
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF340, 2), 16)
    frame = _movement_add_word(state, frame, 'target_x', 2)
    frame = _movement_compare(state, frame, low16(frame.target_x), 0xC17E, 16)
    if not frame.status & 5:
        frame = _command_policy_sub_word_fields(state, frame, 'target_x', 0x80)
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0x38, low16(frame.target_x))
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0, state.read(0xFFFFF340, 2))
    frame = first_replace(frame, roster=frame.roster.advance(2))
    frame = _movement_move(state, frame, 'target_y', 12, 16)
    frame = _movement_move_long(state, frame, 'target_x', 0)
    while True:
        frame = _command_packet_store_long_fields(state, frame, frame.roster, 0x38, frame.target_x)
        frame = _command_packet_store_long_fields(state, frame, frame.roster, 0, frame.target_x)
        frame = first_replace(frame, roster=frame.roster.advance(4))
        frame = _command_packet_advance_dbcount_fields(frame, 'target_y')
        if low16(frame.target_y) == 65535: break
    frame = _settlement_store_word_fields(state, frame, frame.roster, 0x38, 0, clear=True)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF340, 2), 16)
    frame = _command_policy_sub_word_fields(state, frame, 'target_x', 6)
    frame = _movement_compare(state, frame, low16(frame.target_x), 0xC100, 16)
    if frame.status & 1:
        frame = _movement_add_word(state, frame, 'target_x', 0x80)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF340, low16(frame.target_x))


