# B60 complete real-entry aliases and single observation cores.
def _highbank_recovery_frame(state: SceneState, frame: FirstDeploymentFrame,
        entry: int) -> FirstDeploymentFrame:
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual Scene recovery frame required')
    frame.validate(state, True)
    if frame.stack_cursor is None or frame.status is None:
        raise MovementContinuationBoundary(entry, frame, 'actual A7 and CCR required')
    return frame

def _highbank_recovery_sync(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    if frame.status is not None:
        state.sr = (state.sr & 65504) | frame.status
    return frame

def _highbank_recovery_memory_long(frame: FirstDeploymentFrame,
        value: int) -> FirstDeploymentFrame:
    """MOVE.L memory flags only; all data/address carriers are retained."""
    uint(value, 32)
    status = None if frame.status is None else (frame.status & 16) | (8 if value & 0x80000000 else 0) | (4 if value == 0 else 0)
    return first_replace(frame, status=status)

def _special_message_lookup_values(state: SceneState,
        frame: FirstDeploymentFrame):
    """677F0..67804: unique selector, A0 postincrement and final nonincrement read.

    The low WORD observations are returned beside the real frame solely for
    the preexisting partial WORD facade. An unobserved high WORD remains None.
    """
    if frame.roster is None:
        raise MovementContinuationBoundary(0x677F0, frame, 'actual A0 required')
    field = state.read(0xFFFFF38C, 2)
    frame = _first_word(frame, 'target_y', field)
    while True:
        tile = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _first_word(frame, 'unit', tile)
        if tile & 32768:
            break
        frame = _first_compare_word(frame, field, tile)
        if field == tile:
            break
        frame = first_replace(frame, roster=frame.roster.advance(2))
    value = frame.roster.word()
    frame = _first_word(frame, 'target_x', value)
    return _highbank_recovery_sync(state, frame), value, field, tile

def _special_message_lookup_call_values(state: SceneState,
        frame: FirstDeploymentFrame, continuation: int):
    if continuation not in (0x677BA,0x6780A,0x6781E,0x6785E,0x67886,
                            0x678D2,0x678E4,0x67914,0x67942,0x67988):
        raise ValueError('actual message WORD selector continuation required')
    if frame.stack_cursor is None:
        raise MovementContinuationBoundary(0x677F0, frame, 'actual selector return LONG slot required: ' + str(continuation))
    stack = frame.stack_cursor.advance(-4)
    stack.set_long(0, continuation)
    returned, value, field, tile = _special_message_lookup_values(
        state, first_replace(frame, stack_cursor=stack))
    actual = returned.stack_cursor.long()
    if actual != continuation:
        raise MovementContinuationBoundary(0x677F0, returned, 'selector return LONG mismatch: expected ' + str(continuation) + ' actual ' + str(actual))
    returned = first_replace(returned, stack_cursor=returned.stack_cursor.advance(4))
    return returned, value, field, tile

def _special_message_mode_commit_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Actual shared BRA tail677BA, not a second ordinary entry or outer CALL."""
    value = state.read(0xFFFFF612, 2)
    state.write(0xFFFFF3DA, 2, value)
    frame = _first_memory_word(frame, value)
    value = state.read(0xFFFFF362, 2)
    state.write(0xFFFFF3DC, 2, value)
    frame = _first_memory_word(frame, value)
    state.write(0xFFFFF612, 2, 0x0208)
    frame = _first_memory_word(frame, 0x0208)
    state.write(0xFFFFF362, 2, 0x0016)
    return _highbank_recovery_sync(state, _first_memory_word(frame, 0x0016))

def highbank_coordinate_live_state_178_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int = 0x677B2) -> FirstDeploymentFrame:
    """One logical owner/eight real entries, seven disjoint full physical spans."""
    if entry not in (0x677B2,0x67858,0x6787E,0x6791E,0x67926,0x6793A,0x67954,0x679B8):
        raise ValueError('actual special-message owner entry required')
    frame = _highbank_recovery_frame(state, frame, entry)
    if entry in (0x677B2,0x67858,0x6787E,0x6793A):
        if entry == 0x677B2:
            pointer, continuation = 0x677D4, 0x677BA
        elif entry == 0x67858:
            pointer, continuation = 0x67862, 0x6785E
        elif entry == 0x6787E:
            pointer, continuation = 0x6788A, 0x67886
        else:
            pointer, continuation = 0x67946, 0x67942
        frame = first_replace(frame, roster=state.table_at(pointer).cursor())
        frame, value, field, tile = _special_message_lookup_call_values(state, frame, continuation)
    else:
        if entry == 0x6791E:
            value = 0x0021
        elif entry == 0x67926:
            value = 0x0023
        elif entry == 0x67954:
            value = 0x001D
        else:
            value = 0x0000
        frame = _first_word(frame, 'target_x', value)
    return _special_message_mode_commit_fields(state, frame)

def highbank_select_live_state_43_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x677F0)
    returned, value, field, tile = _special_message_lookup_values(state, frame)
    return returned

