def _special_message_action_choice_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> tuple:
    selected = 0x0011
    frame = _first_word(frame, 'target_x', selected)
    value = state.read(0xFFFFF386, 2)
    frame = _first_memory_word(frame, value)
    if value != 0:
        selected = 0x0012
        frame = _first_word(frame, 'target_x', selected)
    return _highbank_recovery_sync(state, frame), value, selected

def highbank_select_live_state_44_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x678A8)
    returned, tested, selected = _special_message_action_choice_fields(state, frame)
    return returned

