def highbank_coordinate_live_state_182_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x678DC)
    frame = first_replace(frame, roster=state.table_at(0x678EC).cursor())
    frame, value, field, tile = _special_message_lookup_call_values(state, frame, 0x678E4)
    value = state.read(0xFFFFF39E, 4)
    state.write(0xFFFFF3C8, 4, value)
    return _highbank_recovery_sync(state, _highbank_recovery_memory_long(frame, value))

