def highbank_update_record_flags_11_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """665E6..66616: live status initialization, CLR prior reads and final BCLR."""
    frame = _highbank_recovery_frame(state, frame, 0x665E6)
    state.write(0xFFFFF600, 2, 0x0040)
    frame = _first_memory_word(frame, 0x0040)
    state.write(0xFFFFF612, 2, 0x0206)
    frame = _first_memory_word(frame, 0x0206)
    state.write(0xFFFFF362, 2, 0x0008)
    frame = _first_memory_word(frame, 0x0008)
    state.read(0xFFFFF36A, 2)
    state.write(0xFFFFF36A, 2, 0)
    frame = _first_memory_word(frame, 0)
    state.read(0xFFFFF658, 2)
    state.write(0xFFFFF658, 2, 0)
    frame = _first_memory_word(frame, 0)
    state.read(0xFFFFF36E, 2)
    state.write(0xFFFFF36E, 2, 0)
    frame = _first_memory_word(frame, 0)
    state.write(0xFFFFF378, 2, 0x0001)
    frame = _first_memory_word(frame, 0x0001)
    state.read(0xFFFFF656, 2)
    state.write(0xFFFFF656, 2, 0)
    frame = _first_memory_word(frame, 0)
    value = state.read(0xFFFFF3A4, 1)
    status = (frame.status & 27) | (4 if not value & 2 else 0)
    state.write(0xFFFFF3A4, 1, value & 253)
    return _highbank_recovery_sync(state, first_replace(frame, status=status))

def _highbank_existing_policy(state: SceneState, frame: FirstDeploymentFrame) -> BattlePolicy:
    frame = _highbank_recovery_frame(state, frame, 0x23610)
    _highbank_recovery_sync(state, frame)
    return BattlePolicy(frame.target_x, frame.target_y, frame.unit, frame.count,
        frame.distance, frame.offset_x, frame.offset_y, frame.choice,
        frame.roster, frame.candidates, frame.scan, frame.controller,
        frame.opponent, frame.scratch, frame.stack_cursor, frame.auxiliary).validate(state)

def highbank_coordinate_live_state_65_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int = 0x23610) -> FirstDeploymentFrame:
    """Eleven original entries project their established single algorithms."""
    frame = _highbank_recovery_frame(state, frame, entry)
    if entry == 0x23610:
        policy = execute_primary_standard_order(state, _highbank_existing_policy(state, frame))
        return _battle_policy_retained_frame(state, policy)
    if entry == 0x23A6E:
        policy = _primary_guarded_short_roster_tail(state, _highbank_existing_policy(state, frame))
        return _battle_policy_retained_frame(state, policy)
    if entry == 0x23CBC:
        return _highbank_recovery_sync(state, evaluate_guarded_second_staging_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x23D9E:
        return _highbank_recovery_sync(state, evaluate_guarded_first_region_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x240BE:
        return _highbank_recovery_sync(state, evaluate_guarded_second_region_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x242EE:
        return _highbank_recovery_sync(state, evaluate_guarded_small_force_region_tail_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x24488:
        return _highbank_recovery_sync(state, evaluate_guarded_third_region_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x245CC:
        return _highbank_recovery_sync(state, evaluate_guarded_west_contact_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x246C8:
        return _highbank_recovery_sync(state, evaluate_guarded_first_staging_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x24806:
        return _highbank_recovery_sync(state, evaluate_guarded_terrain_region_order_fields(state, frame, True).frame.validate(state, True))
    if entry == 0x24A7A:
        return _highbank_recovery_sync(state, evaluate_guarded_alternate_anchor_order_fields(state, frame, True).frame.validate(state, True))
    raise ValueError('actual indexed primary strategy entry required')

def highbank_coordinate_live_state_66_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """2363E uses the one established target-position order algorithm."""
    frame = _highbank_recovery_frame(state, frame, 0x2363E)
    return _highbank_recovery_sync(state, evaluate_standard_position_order_fields(state, frame, True).frame.validate(state, True))

