def _highbank_response_word_fields(state: SceneState, frame: FirstDeploymentFrame,
        offset: int) -> tuple:
    value = frame.roster.word(0, offset)
    return _first_memory_word(frame, value), value

def _highbank_response_sample_fields(state: SceneState, frame: FirstDeploymentFrame,
        continuation: int, mask: int) -> FirstDeploymentFrame:
    """The original caller's real RNG slot and one actual ANDI.W result."""
    frame.validate(state, True)
    frame = sample_battle_action_random_fields(BattlePolicyMemory(state), frame, continuation)
    return _first_word(frame, 'target_x', low16(frame.target_x) & mask)

def _highbank_complete_response_fields(state: SceneState,
        frame: FirstDeploymentFrame, mode) -> FirstDeploymentFrame:
    actor = frame.roster
    if mode is not None:
        actor.set_word(0, mode, 0x0C)
        frame = _first_memory_word(frame, mode)
        actor.set_word(0, 1, 0x40)
        frame = _first_memory_word(frame, 1)
    previous = actor.word(0, 0x3E)
    value = u16(previous + 1)
    actor.set_word(0, value, 0x3E)
    status = (17 if previous == 65535 else 0) | (8 if value & 32768 else 0) | (4 if value == 0 else 0) | (2 if previous == 32767 else 0)
    frame = first_replace(frame, status=status)
    # Both original TST.W $003A.w branches contain the same MOVEM pair.
    # This is actual low ROM, not FF003A RAM; the read is retained in order.
    frame = _first_memory_word(frame, state.read(0x3A, 2))
    if frame.stack_cursor is None:
        raise MovementContinuationBoundary(0x27BF4, frame, 'actual MOVEM stack cursor required')
    frame = _movement_save_longs(state, frame, ('target_x', 'roster'))
    frame = _movement_restore_longs(state, frame, ('target_x', 'roster'))
    value = frame.roster.word(0, 0x3E)
    frame = _first_compare_word(frame, value, 1)
    if value < 1:
        frame = _first_long(frame, 'offset_y', 0)
    else:
        frame = _first_word(frame, 'offset_y', 128)
    return _highbank_recovery_sync(state, frame)

def _highbank_choose_response_fields(state: SceneState, frame: FirstDeploymentFrame,
        entry: int) -> FirstDeploymentFrame:
    """Structured capability/readiness choices and shared completion.

All tests preserve their real read order. Pressure has one RNG call (27CC0),
not the former scalar facade's second hypothetical sample. Range/randomized
mode choices follow their encoded BRA targets rather than inferred names.
"""
    checked_state(state)
    if type(frame) is not FirstDeploymentFrame:
        raise ValueError('actual actor response fields required')
    frame.validate(state, False)
    if frame.roster is None:
        raise MovementContinuationBoundary(entry, frame, 'actual actor A0 required')
    if entry not in (0x27BCC, 0x27C22, 0x27C8A, 0x27CA4, 0x27CD2, 0x27CFC):
        raise ValueError('actual response capability entry required')
    frame, value = _highbank_response_word_fields(state, frame, 0x40)
    if value:
        return _highbank_complete_response_fields(state, frame, None)
    if entry == 0x27BCC:
        frame, value = _highbank_response_word_fields(state, frame, 0x2E)
        if value:
            mode = 2
        else:
            frame, value = _highbank_response_word_fields(state, frame, 0x2A)
            mode = 1 if value else 0
    elif entry == 0x27C22:
        frame, first = _highbank_response_word_fields(state, frame, 0x2A)
        frame, second = _highbank_response_word_fields(state, frame, 0x2E)
        if not first:
            if not second:
                mode = 0
            else:
                frame = _highbank_response_sample_fields(state, frame, 0x27C82, 3)
                mode = 0 if low16(frame.target_x) else 2
        elif not second:
            mode = 1
        else:
            frame = _highbank_response_sample_fields(state, frame, 0x27C62, 1)
            mode = 2 if low16(frame.target_x) else 1
    elif entry == 0x27C8A:
        frame, value = _highbank_response_word_fields(state, frame, 0x2A)
        if value:
            mode = 1
        else:
            frame, value = _highbank_response_word_fields(state, frame, 0x2C)
            mode = 0 if value else 2
    elif entry == 0x27CA4:
        frame, value = _highbank_response_word_fields(state, frame, 0x2A)
        if not value:
            mode = 0
        else:
            frame, value = _highbank_response_word_fields(state, frame, 0x2C)
            if not value:
                mode = 1
            else:
                frame = _highbank_response_sample_fields(state, frame, 0x27CC6, 1)
                mode = 0 if low16(frame.target_x) else 1
    elif entry == 0x27CD2:
        frame, value = _highbank_response_word_fields(state, frame, 0x2C)
        if not value:
            mode = 1
        else:
            frame, value = _highbank_response_word_fields(state, frame, 0x2A)
            if not value:
                mode = 0
            else:
                frame = _highbank_response_sample_fields(state, frame, 0x27CF0, 3)
                mode = 0 if low16(frame.target_x) else 1
    else:
        frame, value = _highbank_response_word_fields(state, frame, 0x2C)
        if value:
            mode = 0
        else:
            frame, value = _highbank_response_word_fields(state, frame, 0x2A)
            mode = 1 if value else 2
    return _highbank_complete_response_fields(state, frame, mode)

def highbank_coordinate_live_state_92_fields(state: SceneState,
        frame: FirstDeploymentFrame, entry: int = 0x27BCC) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, entry)
    return _highbank_choose_response_fields(state, frame, entry)

def _highbank_response_observations(state: SceneState, context: DuelResponseInput,
        entry: int) -> DuelResponseResult:
    """Known original scalar carriers only; no fabricated D2-D5/D7/A1-A6/X."""
    _checked_response(state, context)
    frame = first_replace(FirstDeploymentFrame.unobserved(), target_x=context.sample,
        target_y=context.seed, offset_y=context.response, roster=context.actor.cursor(),
        stack_cursor=context.stack)
    frame = _highbank_choose_response_fields(state, frame, entry)
    return DuelResponseResult(frame.target_x, frame.target_y, frame.offset_y,
        state.table_at(frame.roster.base), frame.stack_cursor, bool(frame.status & 1),
        bool(frame.status & 4), bool(frame.status & 8), bool(frame.status & 2),
        bool(frame.status & 16)).validate(state)

def _highbank_device_write_fields(state: SceneState, frame: FirstDeploymentFrame,
        address: int, value: int, width: int = 2) -> FirstDeploymentFrame:
    if width not in (2, 4):
        raise ValueError('original hardware WORD or LONG required')
    try:
        state.write(address, width, value)
    except Boundary:
        raise MovementContinuationBoundary(address, frame, 'actual device write requires hardware authority')
    frame = _first_memory_word(frame, value) if width == 2 else _highbank_recovery_memory_long(frame, value)
    return _highbank_recovery_sync(state, frame)

def _highbank_device_shift_long_fields(frame: FirstDeploymentFrame,
        name: str, count: int, right: bool = False) -> FirstDeploymentFrame:
    if count not in (2, 3) or type(right) is not bool:
        raise ValueError('actual device LONG shift required')
    original = frame.carrier(name)
    carry = bool(original & (1 << (count - 1))) if right else bool(original & (1 << (32 - count)))
    value = original >> count if right else u32(original << count)
    status = (17 if carry else 0) | (8 if value & 0x80000000 else 0) | (4 if value == 0 else 0)
    return first_replace(frame, **{name: value}, status=status)

def _highbank_device_divide_fields(frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Original DIVS.W D3,D1; undefined overflow flags stay a true boundary."""
    dividend = frame.target_y if frame.target_y < 0x80000000 else frame.target_y - 0x100000000
    divisor = s16(low16(frame.count))
    if divisor == 0:
        raise MovementContinuationBoundary(0x28A48, frame, 'actual DIVS zero-divisor exception')
    quotient = abs(dividend) // abs(divisor)
    if (dividend < 0) != (divisor < 0):
        quotient = -quotient
    if not -32768 <= quotient <= 32767:
        raise MovementContinuationBoundary(0x28A48, frame, 'original DIVS overflow has undefined N/Z; no invented flags')
    remainder = dividend - quotient * divisor
    value = (u16(remainder) << 16) | u16(quotient)
    status = (frame.status & 16) | (8 if quotient < 0 else 0) | (4 if quotient == 0 else 0)
    return first_replace(frame, target_y=value, status=status)

def _highbank_device_bus_fields(state: SceneState, frame: FirstDeploymentFrame,
        first_pattern: bool) -> FirstDeploymentFrame:
    """The original two DMA command groups, with the actual A6 and D7."""
    frame = first_replace(frame, auxiliary=state.table_at(0xC00004))
    frame = _first_word(frame, 'choice', state.read(0xFFFFF606, 2))
    frame = _first_byte(frame, 'choice', low8(frame.choice) | 16)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.choice))
    frame = _highbank_device_write_fields(state, frame, 0xA11100, 256)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 0x94019340 if first_pattern else 0x94009340, 4)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 0x96FC9500 if first_pattern else 0x96FD9580, 4)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 0x977F)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 0x5800 if first_pattern else 0xC000)
    frame = _highbank_device_write_fields(state, frame, 0xFFFFF620, 0x83 if first_pattern else 0x80)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, state.read(0xFFFFF620, 2))
    value = state.read(0xFFFF3F00, 1)
    frame = _movement_test(state, frame, value, 8)
    if value == 0:
        frame = _highbank_device_write_fields(state, frame, 0xA11100, 0)
    return _highbank_device_write_fields(state, frame, frame.auxiliary.base, state.read(0xFFFFF606, 2))

def highbank_process_device_control_2_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x28936)
    frame = _highbank_recovery_memory_increment_fields(state, frame, 0x00FF7008)
    frame = _highbank_recovery_memory_increment_fields(state, frame, 0x00FF70FA)
    frame = _highbank_recovery_call_fields(state, frame, 0x67CA, 0x28948)
    frame = _highbank_device_bus_fields(state, frame, True)
    frame = _first_word(frame, 'target_x', 0x60)
    for index in range(97):
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(0x60 - index - 1)))
    frame = _highbank_device_bus_fields(state, frame, False)
    frame = _highbank_recovery_call_fields(state, frame, 0xAD06, 0x289EA)
    frame = _first_word(frame, 'target_x', state.read(0xFFFFF606, 2))
    frame = _first_byte(frame, 'target_x', low8(frame.target_x) | 64)
    frame = _highbank_device_write_fields(state, frame, 0xC00004, low16(frame.target_x))
    frame = first_replace(frame, auxiliary=state.table_at(0xC00000))
    frame = _first_word(frame, 'target_x', state.read(0x00FF70AE, 2))
    frame = _first_add_word(frame, 'target_x', low16(frame.target_x), state.read(0x00FF705E, 2))
    frame = _first_right_word(frame, 'target_x', low16(frame.target_x), 1)
    frame = _first_sub_word(frame, 'target_x', low16(frame.target_x), 160)
    frame = _highbank_device_write_fields(state, frame, 0x00FF7006, low16(frame.target_x))
    frame = _first_sub_word(frame, 'target_x', 0, low16(frame.target_x))
    frame = _first_word(frame, 'target_y', low16(frame.target_x))
    frame = _first_right_word(frame, 'target_y', low16(frame.target_y), 5)
    frame = _first_word(frame, 'unit', state.read(0x00FF7008, 2))
    frame = _first_right_word(frame, 'unit', low16(frame.unit), 3)
    frame = _highbank_device_write_fields(state, frame, 0xC00004, 0x5C000003, 4)
    frame = _first_word(frame, 'choice', 95)
    for index in range(96):
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.target_y))
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.unit))
        frame = first_replace(frame, choice=replace_word(frame.choice, u16(95 - index - 1)))
    frame = _first_word(frame, 'choice', 55)
    for index in range(56):
        frame = _first_long(frame, 'target_y', 0)
        frame = _first_word(frame, 'target_y', low16(frame.target_x))
        frame = _first_word(frame, 'count', low16(frame.choice))
        frame = _first_right_word(frame, 'count', low16(frame.count), 3)
        frame = _first_add_word(frame, 'count', low16(frame.count), 1)
        frame = _highbank_device_divide_fields(frame)
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.target_y))
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.unit))
        frame = first_replace(frame, choice=replace_word(frame.choice, u16(55 - index - 1)))
    frame = _first_word(frame, 'choice', 15)
    for index in range(16):
        frame = _first_long(frame, 'target_y', 0)
        frame = _first_word(frame, 'target_y', low16(frame.target_x))
        frame = _first_word(frame, 'count', 15)
        frame = _first_sub_word(frame, 'count', low16(frame.count), low16(frame.choice))
        frame = _first_add_word(frame, 'count', low16(frame.count), 8)
        frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.count))
        frame = _highbank_device_shift_long_fields(frame, 'target_y', 3, True)
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.target_y))
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.unit))
        frame = first_replace(frame, choice=replace_word(frame.choice, u16(15 - index - 1)))
    frame = _highbank_device_write_fields(state, frame, 0xC00004, 0x40000010, 4)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 0)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, 256)
    frame = _highbank_device_write_fields(state, frame, 0x00FF7002, 0xFFFFF800, 4)
    state.read(0x00FF7000, 2)
    frame = _highbank_device_write_fields(state, frame, 0x00FF7000, 0)
    state.read(0xFFFFF612, 2)
    frame = _highbank_device_write_fields(state, frame, 0xFFFFF612, 0)
    return _highbank_recovery_call_fields(state, frame, 0x28A9E, 0x28A98)

def highbank_process_device_control_3_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x28A9E)
    frame = _first_word(frame, 'target_y', state.read(0xFFFFEFD8, 2))
    frame = _first_word(frame, 'target_x', state.read(0xFFFFF320, 2))
    masked = low8(frame.target_x) & state.table_at(0x28A9A).byte(low16(frame.target_y))
    frame = _first_byte(frame, 'target_x', masked)
    if masked != 0:
        return _highbank_recovery_sync(state, frame)
    value = state.read(0x00FF700C, 2)
    frame = _first_memory_word(frame, value)
    if value == 0:
        return _highbank_recovery_sync(state, frame)
    frame = _first_long(frame, 'unit', 0)
    frame = _first_word(frame, 'unit', state.read(0x00FF700C, 2))
    frame = _highbank_device_shift_long_fields(frame, 'unit', 2)
    frame = _first_right_word(frame, 'unit', low16(frame.unit), 2)
    frame = _first_word(frame, 'unit', low16(frame.unit) | 0x4000)
    frame = _first_long(frame, 'unit', swap_words(frame.unit))
    frame = _highbank_device_write_fields(state, frame, 0xC00004, frame.unit, 4)
    frame = first_replace(frame, roster=state.table_at(state.read(0x00FF700E, 4)).cursor())
    frame = _first_word(frame, 'target_x', frame.roster.word())
    frame = _first_word(frame, 'choice', state.read(0x00FF706A, 2))
    frame = _first_compare_word(frame, low16(frame.target_x), 0xFF00)
    special = low16(frame.target_x) == 0xFF00
    if not special:
        frame = _first_word(frame, 'choice', state.read(0x00FF7070, 2))
        frame = _first_compare_word(frame, low16(frame.target_x), 0xFF01)
        special = low16(frame.target_x) == 0xFF01
    if not special:
        frame = _first_word(frame, 'choice', state.read(0x00FF70BA, 2))
        frame = _first_compare_word(frame, low16(frame.target_x), 0xFF02)
        special = low16(frame.target_x) == 0xFF02
    if not special:
        frame = _first_word(frame, 'choice', state.read(0x00FF70C0, 2))
        frame = _first_compare_word(frame, low16(frame.target_x), 0xFF03)
        special = low16(frame.target_x) == 0xFF03
    if special:
        frame = _first_word(frame, 'target_x', state.read(0x00FF7014, 2))
        frame = _first_word(frame, 'target_y', state.read(0x00FF7016, 2))
        frame = _highbank_recovery_call_fields(state, frame, 0x27D1C, 0x28B18)
        frame = _first_word(frame, 'unit', state.read(0x00FF700C, 2))
        frame = _first_add_word(frame, 'unit', low16(frame.unit), 0x180)
    else:
        frame = first_replace(frame, candidates=state.table_at(0xFFFFD300).cursor())
        frame = _first_word(frame, 'target_x', state.read(0x00FF7014, 2))
        frame = _first_word(frame, 'target_y', state.read(0x00FF7016, 2))
        frame = _first_word(frame, 'count', 0)
        frame = _highbank_recovery_call_fields(state, frame, 0xAE8A, 0x28B3E)
        frame = first_replace(frame, roster=state.table_at(0xFFFFD300).cursor(), auxiliary=state.table_at(0xC00000))
        frame = _first_word(frame, 'target_x', 31)
        for index in range(32):
            value = frame.roster.long()
            frame = first_replace(frame, roster=frame.roster.advance(4))
            frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, value, 4)
            frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(31 - index - 1)))
        frame = _first_word(frame, 'unit', state.read(0x00FF700C, 2))
        frame = _first_add_word(frame, 'unit', low16(frame.unit), 128)
    frame = first_replace(frame, roster=state.table_at(state.read(0x00FF700E, 4)).cursor().advance(2))
    frame = _first_word(frame, 'target_x', frame.roster.word())
    if low16(frame.target_x) & 32768:
        frame = _first_compare_word(frame, low16(frame.target_x), 0xFF20)
        if low16(frame.target_x) == 0xFF20:
            frame = _first_add_word(frame, 'unit', low16(frame.unit), 64)
            frame = first_replace(frame, roster=frame.roster.advance(2))
        else:
            frame = _first_compare_word(frame, low16(frame.target_x), 0xFF0A)
            if low16(frame.target_x) == 0xFF0A:
                frame = _first_word(frame, 'unit', 0xCB00)
                frame = first_replace(frame, roster=frame.roster.advance(2))
            else:
                frame = _first_compare_word(frame, low16(frame.target_x), 0xFFFF)
                if low16(frame.target_x) == 0xFFFF:
                    frame = _first_word(frame, 'unit', 0)
    frame = _highbank_device_write_fields(state, frame, 0x00FF700C, low16(frame.unit))
    return _highbank_device_write_fields(state, frame, 0x00FF700E, frame.roster.base, 4)

def highbank_process_device_control_4_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    frame = _highbank_recovery_frame(state, frame, 0x2B2FE)
    frame = _highbank_recovery_call_fields(state, frame, 0x67CA, 0x2B304)
    frame = _highbank_recovery_call_fields(state, frame, 0x4998, 0x2B30A)
    frame = first_replace(frame, auxiliary=state.table_at(0xC00004))
    frame = _first_word(frame, 'choice', state.read(0xFFFFF606, 2))
    frame = _first_byte(frame, 'choice', low8(frame.choice) | 16)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, low16(frame.choice))
    frame = _highbank_device_write_fields(state, frame, 0xA11100, 256)
    for value in (0x94019340, 0x96FC9500):
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, value, 4)
    for value in (0x977F, 0x7C00):
        frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, value)
    frame = _highbank_device_write_fields(state, frame, 0xFFFFF620, 0x83)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, state.read(0xFFFFF620, 2))
    value = state.read(0xFFFF3F00, 1)
    frame = _movement_test(state, frame, value, 8)
    if value == 0:
        frame = _highbank_device_write_fields(state, frame, 0xA11100, 0)
    frame = _highbank_device_write_fields(state, frame, frame.auxiliary.base, state.read(0xFFFFF606, 2))
    frame = _first_word(frame, 'target_x', 96)
    for index in range(97):
        frame = first_replace(frame, target_x=replace_word(frame.target_x, u16(96 - index - 1)))
    frame = _highbank_device_bus_fields(state, frame, False)
    state.read(0xFFFFF612, 2)
    frame = _highbank_device_write_fields(state, frame, 0xFFFFF612, 0)
    state.read(0xFFFFF300, 2)
    frame = _highbank_device_write_fields(state, frame, 0xFFFFF300, 0)
    frame = _first_word(frame, 'target_x', state.read(0xFFFFF606, 2))
    frame = _first_byte(frame, 'target_x', low8(frame.target_x) | 64)
    frame = _highbank_device_write_fields(state, frame, 0xC00004, low16(frame.target_x))
    return _highbank_recovery_call_fields(state, frame, 0x3FFAA, 0x2B3C2)

