def select_welfare_officer_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32260..3229C: maximum welfare plus development score in the live roster."""
    frame = _resource_cost_frame(state, frame, 0x32260)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = first_replace(frame, controller=state.table_at(0xFFFFC200))
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    while True:
        # 32272: the sentinel itself is observed and A0 still advances by two.
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'unit', token, 16)
        if frame.status & 8:
            return frame
        frame = _command_policy_register_bit_fields(state, frame, frame.unit, 14)
        if not frame.status & 4:
            continue
        # ANDI.W and CLR.W retain their respective high WORDs and incoming X.
        frame = _movement_move(state, frame, 'unit', low16(frame.unit) & 255, 16)
        frame = _movement_move(state, frame, 'distance', 0, 16)
        frame = _movement_move(state, frame, 'distance', frame.controller.byte(low16(frame.unit)), 8)
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_add_word(state, frame, 'distance', frame.candidates.word(low16(frame.count)))
        frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.target_x), 16)
        if frame.status & 5:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def select_development_officer_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32340..3236E: maximum development WORD; the token is not masked to BYTE."""
    frame = _resource_cost_frame(state, frame, 0x32340)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    while True:
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'unit', token, 16)
        if frame.status & 8:
            return frame
        frame = _command_policy_register_bit_fields(state, frame, frame.unit, 14)
        if not frame.status & 4:
            continue
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_move(state, frame, 'distance', frame.candidates.word(low16(frame.count)), 16)
        frame = _movement_compare(state, frame, low16(frame.distance), low16(frame.target_x), 16)
        if frame.status & 5:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.distance), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def plan_city_defense_target_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """324FA..32562: actual random seed scaling and signed defense LONG store."""
    frame = _resource_cost_frame(state, frame, 0x324FA)
    # The original JSR owns this physical return LONG, never a scalar RNG call.
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x32500)
    frame = first_replace(frame, roster=state.table_at(0x311FC).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF376, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _movement_move(state, frame, 'target_y', frame.roster.word(low16(frame.target_x)), 16)
    frame = _special_action_sub_word(state, frame, 'target_y', 5)
    frame = _movement_compare(state, frame, low16(frame.target_y), 3, 16)
    if not frame.status & 5:
        frame = _movement_move(state, frame, 'target_y', 3, 16)
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_add_word(state, frame, 'target_y', low16(frame.unit))
    frame = _movement_move(state, frame, 'unit', 0x37, 16)
    frame = _special_action_sub_word(state, frame, 'unit', low16(frame.target_y))
    # 3252A MOVEQ overwrites all D0, unlike the immediately following MOVE.W.
    frame = _movement_move_long(state, frame, 'target_x', 0)
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF61C, 2), 16)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 1)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'unit', low16(frame.target_x))
    frame = first_replace(frame, roster=state.table_at(0xFFFFE3BC).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFE31C).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _command_detail_compare_long_fields(state, frame, frame.candidates.long(low16(frame.target_x)), 0x28)
    if frame.status & 1:
        frame = _special_action_sub_word(state, frame, 'unit', 10)
    # 3255A EXT.L sign-extends WORD and sets LONG logical flags, retaining X.
    frame = _movement_move_long(state, frame, 'unit', u32(s16(low16(frame.unit))))
    return _command_policy_store_long_fields(state, frame,
        frame.roster.address(low16(frame.target_x)), frame.unit)

def count_economy_roster_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """330CC..330DE: TST.W postincrement count, without clobbering D2."""
    frame = _resource_cost_frame(state, frame, 0x330CC)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    while True:
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_test(state, frame, token, 16)
        if frame.status & 8:
            return frame
        frame = _movement_adjust_word(state, frame, 'target_x', 1)

def count_linked_force_officers_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3473A..3477A: descending 256-record linked-force scan and full CCR."""
    frame = _resource_cost_frame(state, frame, 0x3473A)
    frame = first_replace(frame, roster=state.table_at(0xFFFFA050).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF427).cursor())
    frame = first_replace(frame, controller=state.table_at(0xFFFFCC00))
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF392, 2), 16)
    frame = _movement_move(state, frame, 'count', state.read(0xFFFFF376, 2), 16)
    frame = _movement_move(state, frame, 'unit', 255, 16)
    while True:
        frame = _movement_move(state, frame, 'distance', frame.roster.byte(low16(frame.unit)), 8)
        frame = _movement_move(state, frame, 'distance', low16(frame.distance) & 0x3F, 16)
        frame = _movement_compare(state, frame, low8(frame.distance), low8(frame.target_y), 8)
        if frame.status & 4:
            frame = _movement_move(state, frame, 'distance', frame.controller.byte(low16(frame.unit)), 8)
            frame = _movement_move(state, frame, 'distance', low16(frame.distance) & 0x3F, 16)
            frame = _movement_compare(state, frame, low8(frame.count), frame.candidates.byte(low16(frame.distance)), 8)
            if frame.status & 4:
                frame = _movement_adjust_word(state, frame, 'target_x', 1)
        # 34774 DBRA replaces only the counter WORD and changes no CCR bit.
        frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))
        if low16(frame.unit) == 65535:
            return frame

def select_roster_attribute_max_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32A3A..32A68: maximum attribute, retaining the shifted losing D2 token."""
    frame = _resource_cost_frame(state, frame, 0x32A3A)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    while True:
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'unit', token, 16)
        if frame.status & 8:
            return frame
        frame = _command_policy_register_bit_fields(state, frame, frame.unit, 14)
        if not frame.status & 4:
            continue
        frame = _movement_fixed_shift_word(state, frame, 'unit', 1)
        frame = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.unit)), 16)
        frame = _movement_compare(state, frame, low16(frame.count), low16(frame.target_x), 16)
        if frame.status & 5:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
        frame = _movement_fixed_shift_word(state, frame, 'unit', 1, True)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def select_player_neighbor_head_attribute_min_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32C40..32CA8: player-neighbor head minimum with short-circuit BYTE reads."""
    frame = _resource_cost_frame(state, frame, 0x32C40)
    frame = first_replace(frame, roster=state.table_at(0xD4BDA).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3)
    # 32C4C ADDA.W changes no flags; the signed, wrapped WORD biases A0.
    frame = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.target_x))))
    frame = first_replace(frame, candidates=state.table_at(0xFFFFF427).cursor())
    frame = first_replace(frame, controller=state.table_at(0xFFFFB600))
    frame = first_replace(frame, scan=state.table_at(0xFFFFF45E).cursor())
    frame = first_replace(frame, opponent=state.table_at(0xFFFFEA37))
    frame = _movement_move(state, frame, 'target_x', 65535, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    # 32C66 clears D2.W once, not at the start of each neighbor iteration.
    frame = _movement_move(state, frame, 'unit', 0, 16)
    while True:
        neighbor = frame.roster.byte()
        frame = first_replace(frame, roster=frame.roster.advance(1))
        frame = _movement_move(state, frame, 'unit', neighbor, 8)
        if frame.status & 8:
            return frame
        frame = _movement_test(state, frame, frame.opponent.byte(low16(frame.unit)), 8)
        if not frame.status & 4:
            continue
        frame = _movement_move(state, frame, 'count', frame.candidates.byte(low16(frame.unit)), 8)
        frame = _movement_compare(state, frame, low8(frame.count), state.read(0xFFFFF67B, 1), 8)
        if not frame.status & 4:
            frame = _movement_compare(state, frame, low8(frame.count), state.read(0xFFFFF67D, 1), 8)
            if not frame.status & 4:
                frame = _movement_compare(state, frame, low8(frame.count), state.read(0xFFFFF67F, 1), 8)
                if not frame.status & 4:
                    continue
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_move(state, frame, 'count', frame.scan.word(low16(frame.count)), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_move(state, frame, 'count', frame.controller.word(low16(frame.count)), 16)
        frame = _movement_compare(state, frame, low16(frame.count), low16(frame.target_x), 16)
        if not frame.status & 1:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def select_roster_attribute_max_preserving_id_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32E72..32EA0: maximum attribute with D2 token retained and D3 WORD index."""
    frame = _resource_cost_frame(state, frame, 0x32E72)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    while True:
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'unit', token, 16)
        if frame.status & 8:
            return frame
        frame = _command_policy_register_bit_fields(state, frame, frame.unit, 14)
        if not frame.status & 4:
            continue
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.count)), 16)
        frame = _movement_compare(state, frame, low16(frame.count), low16(frame.target_x), 16)
        if frame.status & 5:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def mark_selected_roster_bit14_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """320A0: retain the actual saved A0 LONG and mark one matching live WORD."""
    frame = _resource_cost_frame(state, frame, 0x320A0)
    frame = _movement_save_longs(state, frame, ('roster',))
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    while True:
        token = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'target_y', token, 16)
        if frame.status & 8:
            break
        frame = _movement_compare(state, frame, low16(frame.target_y), low16(frame.target_x), 16)
        if not frame.status & 4:
            continue
        # 320B2 BSET register uses D1.L and preserves every CCR bit except Z.
        frame = _command_policy_register_bit_fields(state, frame, frame.target_y, 14)
        frame = first_replace(frame, target_y=u32(frame.target_y | (1 << 14)))
        state.write(frame.roster.address(0, -2), 2, low16(frame.target_y))
        frame = _movement_test(state, frame, low16(frame.target_y), 16)
        break
    return _movement_restore_longs(state, frame, ('roster',))

def plan_welfare_budget_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3229C: random ratio times full city funds, signed divide, capped LONG."""
    frame = _resource_cost_frame(state, frame, 0x3229C)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x322A2)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 20)
    frame = first_replace(frame, roster=state.table_at(0xFFFFDFFC).cursor())
    frame = _movement_move(state, frame, 'target_y', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_y', 2)
    frame = _movement_move_long(state, frame, 'target_y', frame.roster.long(low16(frame.target_y)))
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.unit)
    frame = _movement_move_long(state, frame, 'unit', 100)
    frame = _command_policy_call_fields(state, frame, 0x35760, 0x322DA)
    frame = _command_detail_compare_long_fields(state, frame, frame.target_y, 9999)
    if not frame.status & 5:
        frame = _movement_move_long(state, frame, 'target_y', 9999)
    return _command_policy_store_long_fields(state, frame, 0xFFFFF39E, frame.target_y)

def plan_development_budget_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3236E: preserve city-index overwrite of random factor before MULU."""
    frame = _resource_cost_frame(state, frame, 0x3236E)
    frame = _command_policy_call_fields(state, frame, 0x83D4, 0x32374)
    frame = _movement_move_long(state, frame, 'target_x', frame.target_x & 65535)
    frame = _movement_move_long(state, frame, 'target_y', frame.target_x)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_shift_long(state, frame, 'target_x', 2)
    frame = _movement_arithmetic_long(state, frame, 'target_x', frame.target_y)
    frame = _special_action_swap(state, frame, 'target_x')
    frame = _movement_add_word(state, frame, 'target_x', 30)
    frame = first_replace(frame, roster=state.table_at(0xFFFFDFFC).cursor())
    # Actual 3238E/32392 replace only the WORD, retaining the prior high WORD.
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
    frame = _movement_move_long(state, frame, 'target_y', frame.roster.long(low16(frame.target_x)))
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _movement_multiply_word(state, frame, 'unit', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_multiply_word(state, frame, 'target_y', low16(frame.target_x))
    frame = _special_action_swap(state, frame, 'target_y')
    frame = _movement_arithmetic_long(state, frame, 'target_y', frame.unit)
    frame = _movement_move_long(state, frame, 'unit', 100)
    frame = _command_policy_call_fields(state, frame, 0x35760, 0x323AC)
    frame = _command_detail_compare_long_fields(state, frame, frame.target_y, 9999)
    if not frame.status & 5:
        frame = _movement_move_long(state, frame, 'target_y', 9999)
    return _command_policy_store_long_fields(state, frame, 0xFFFFF39E, frame.target_y)

def select_foreign_nonruler_attribute_sum_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32A68: unprocessed foreign-neighbor selection using the original scan."""
    frame = _resource_cost_frame(state, frame, 0x32A68)
    frame = first_replace(frame, roster=state.table_at(0xD4BDA).cursor())
    frame = _movement_move(state, frame, 'target_x', state.read(0xFFFFF364, 2), 16)
    frame = _movement_fixed_shift_word(state, frame, 'target_x', 3)
    frame = first_replace(frame, roster=frame.roster.advance(s16(low16(frame.target_x))))
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = first_replace(frame, controller=state.table_at(0xFFFFB400))
    frame = first_replace(frame, scan=state.table_at(0xFFFFF427).cursor())
    frame = first_replace(frame, scratch=state.table_at(0xFFFFEA37))
    frame = first_replace(frame, auxiliary=state.table_at(0xFFFFC300))
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    frame = _movement_move(state, frame, 'unit', 65535, 16)
    # D3.W is cleared once: subsequent BYTE reads retain its other bits.
    frame = _movement_move(state, frame, 'count', 0, 16)
    while True:
        neighbor = frame.roster.byte()
        frame = first_replace(frame, roster=frame.roster.advance(1))
        frame = _movement_move(state, frame, 'count', neighbor, 8)
        if frame.status & 8:
            return frame
        frame = _movement_move(state, frame, 'distance', 0, 16)
        frame = _movement_move(state, frame, 'distance', frame.scan.byte(low16(frame.count)), 8)
        if frame.status & 8:
            continue
        frame = _movement_compare(state, frame, low16(frame.distance), state.read(0xFFFFF376, 2), 16)
        if frame.status & 4:
            continue
        frame = _movement_test(state, frame, frame.scratch.byte(low16(frame.count)), 8)
        if not frame.status & 4:
            continue
        frame = _command_policy_call_fields(state, frame, 0x32AB8, 0x32AB4)

def select_roster_intelligence_max_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """330DE: unsigned intelligence maximum; all roster tokens are considered."""
    frame = _resource_cost_frame(state, frame, 0x330DE)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF72A).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFB600).cursor())
    frame = _movement_move(state, frame, 'target_x', 0, 16)
    frame = _movement_move(state, frame, 'target_y', 65535, 16)
    while True:
        officer = frame.roster.word()
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_move(state, frame, 'unit', officer, 16)
        if frame.status & 8:
            return frame
        frame = _movement_move(state, frame, 'count', low16(frame.unit), 16)
        frame = _movement_fixed_shift_word(state, frame, 'count', 1)
        frame = _movement_move(state, frame, 'count', frame.candidates.word(low16(frame.count)), 16)
        frame = _movement_compare(state, frame, low16(frame.count), low16(frame.target_x), 16)
        if frame.status & 5:
            continue
        frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
        frame = _movement_move(state, frame, 'target_y', low16(frame.unit), 16)

def build_limited_packet_roster_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """3477A: reverse packet roster, optional ranking, and marked/unmarked output."""
    frame = _resource_cost_frame(state, frame, 0x3477A)
    frame = first_replace(frame, roster=state.table_at(0xFFFF9000).cursor())
    frame = first_replace(frame, roster=frame.roster.advance(s16(state.read(0xFFFFF75A, 2))))
    frame = _movement_move(state, frame, 'target_x', frame.roster.byte(), 8)
    frame = _movement_move(state, frame, 'target_x', low16(frame.target_x) & 15, 16)
    frame = _movement_move(state, frame, 'count', low16(frame.target_x), 16)
    frame = _movement_adjust_word(state, frame, 'count', -1)
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move(state, frame, 'unit', 0, 16)
    # The original DBRA loop runs once even when packet count is zero.
    while True:
        frame = _movement_move(state, frame, 'unit', frame.roster.byte(low16(frame.count), 13), 8)
        frame = _command_policy_store_word_fields(state, frame, frame.candidates.address(0), low16(frame.unit))
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = first_replace(frame, count=replace_word(frame.count, u16(low16(frame.count) - 1)))
        if low16(frame.count) == 65535:
            break
    frame = _command_policy_store_word_fields(state, frame, frame.candidates.address(0), 65535)
    frame = _command_policy_store_word_fields(state, frame, frame.candidates.address(0, 2), 65535)
    frame = _movement_compare(state, frame, low16(frame.target_x), low16(frame.target_y), 16)
    if not frame.status & 5:
        frame = _command_policy_call_fields(state, frame, 0x347DE, 0x347B0)
        frame = _command_policy_call_fields(state, frame, 0x34854, 0x347B4)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF500).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD300).cursor())
    frame = _movement_move(state, frame, 'unit', 0, 16)
    while True:
        officer = frame.candidates.word()
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _movement_move(state, frame, 'count', officer, 16)
        if frame.status & 8:
            break
        # BSET14 on D3 changes only Z; it is not a logical OR flags update.
        frame = _command_policy_register_bit_fields(state, frame, frame.count, 14)
        frame = first_replace(frame, count=u32(frame.count | 16384))
        frame = _command_policy_store_word_fields(state, frame, frame.roster.address(0), low16(frame.count))
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = _movement_adjust_word(state, frame, 'unit', 1)
    # First separator is consumed but not copied; later WORDs include sentinel.
    while True:
        officer = frame.candidates.word()
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _command_policy_store_word_fields(state, frame, frame.roster.address(0), officer)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8:
            break
        frame = _movement_adjust_word(state, frame, 'unit', 1)
    return _command_policy_store_word_fields(state, frame, 0xFFFFF636, low16(frame.unit))

def scan_nonruler_city_attribute_sum_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """32AB8: exclude the ruler, scan shifted memberships, and retain best score."""
    frame = _resource_cost_frame(state, frame, 0x32AB8)
    saved = ('choice', 'roster')
    frame = _movement_save_longs(state, frame, saved)
    frame = first_replace(frame, roster=state.table_at(0xFFFFF427).cursor())
    frame = _movement_move(state, frame, 'choice', 0, 16)
    frame = _movement_move(state, frame, 'choice', frame.roster.byte(low16(frame.count)), 8)
    frame = _movement_fixed_shift_word(state, frame, 'choice', 1)
    frame = first_replace(frame, roster=state.table_at(0xFFFFE640).cursor())
    frame = _movement_move(state, frame, 'choice', frame.roster.word(low16(frame.choice)), 16)
    frame = first_replace(frame, opponent=state.table_at(0xFFFFCD00))
    frame = _movement_move(state, frame, 'distance', 255, 16)
    while True:
        frame = _movement_compare(state, frame, low16(frame.choice), low16(frame.distance), 16)
        if not frame.status & 4:
            # The ruler skip happens before predecrement, shifting later reads.
            frame = first_replace(frame, opponent=frame.opponent.advance(-1))
            frame = _movement_compare(state, frame, low8(frame.count), frame.opponent.byte(), 8)
            if frame.status & 4:
                frame = _movement_compare(state, frame, frame.auxiliary.byte(low16(frame.distance)), 95, 8)
                if frame.status & 1:
                    frame = _movement_move(state, frame, 'offset_x', low16(frame.distance), 16)
                    frame = _movement_fixed_shift_word(state, frame, 'offset_x', 1)
                    frame = _movement_move(state, frame, 'offset_y', frame.candidates.word(low16(frame.offset_x)), 16)
                    frame = _movement_add_word(state, frame, 'offset_y', frame.controller.word(low16(frame.offset_x)))
                    frame = _movement_compare(state, frame, low16(frame.offset_y), low16(frame.target_x), 16)
                    if not frame.status & 5:
                        frame = _movement_move(state, frame, 'target_x', low16(frame.offset_y), 16)
                        frame = _movement_move(state, frame, 'target_y', low16(frame.distance), 16)
                        frame = _movement_move(state, frame, 'unit', low16(frame.count), 16)
        frame = first_replace(frame, distance=replace_word(frame.distance, u16(low16(frame.distance) - 1)))
        if low16(frame.distance) == 65535:
            break
    return _movement_restore_longs(state, frame, saved)

def rank_packet_roster_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """347DE: original strength/attribute insertion, including both pointer quirks."""
    frame = _resource_cost_frame(state, frame, 0x347DE)
    saved = ('target_x', 'target_y', 'unit', 'count', 'distance', 'offset_x', 'roster', 'candidates')
    frame = _movement_save_longs(state, frame, saved)
    frame = first_replace(frame, roster=state.table_at(0xFFFFD300).cursor())
    frame = first_replace(frame, opponent=state.table_at(0xFFFFC800))
    frame = first_replace(frame, scratch=state.table_at(0xFFFFB400))
    # This initial sentinel uses incoming A1, not the later ranked-list LEA.
    frame = _command_policy_store_word_fields(state, frame, frame.candidates.address(0), 65535)
    while True:
        # Original MOVE.W (A0),D0 does not increment the candidate source.
        frame = _movement_move(state, frame, 'target_x', frame.roster.word(), 16)
        if frame.status & 8:
            return _movement_restore_longs(state, frame, saved)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 2)
        # Raw 32343002 indexes strength by live D3.W, not shifted D0.W.
        frame = _movement_move(state, frame, 'target_y', frame.opponent.word(low16(frame.count), 2), 16)
        frame = _movement_compare(state, frame, low16(frame.target_y), 10000, 16)
        if not frame.status & 5:
            frame = _movement_move(state, frame, 'target_y', 10000, 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)
        frame = _movement_move(state, frame, 'unit', frame.scratch.word(low16(frame.target_x)), 16)
        frame = _movement_fixed_shift_word(state, frame, 'target_x', 1, True)
        frame = first_replace(frame, candidates=state.table_at(0xFFFFD320).cursor())
        frame = first_replace(frame, controller=state.table_at(0xFFFFD340))
        frame = first_replace(frame, scan=state.table_at(0xFFFFD360).cursor())
        while True:
            frame = _movement_test(state, frame, frame.candidates.word(), 16)
            if frame.status & 8:
                break
            frame = _movement_compare(state, frame, low16(frame.target_y), frame.controller.word(), 16)
            if not frame.status & 1:
                frame = _movement_compare(state, frame, low16(frame.unit), frame.scan.word(), 16)
                if not frame.status & 1:
                    break
            # ADDQ to address registers does not alter CCR or its X.
            frame = first_replace(frame, candidates=frame.candidates.advance(2))
            frame = first_replace(frame, controller=frame.controller.advance(2))
            frame = first_replace(frame, scan=frame.scan.advance(2))
        while True:
            frame = _movement_move(state, frame, 'count', frame.candidates.word(), 16)
            frame = _command_policy_store_word_fields(state, frame, frame.candidates.address(0), low16(frame.target_x))
            frame = first_replace(frame, candidates=frame.candidates.advance(2))
            if frame.status & 8:
                break
            frame = _movement_move(state, frame, 'distance', frame.controller.word(), 16)
            frame = _command_policy_store_word_fields(state, frame, frame.controller.address(0), low16(frame.target_y))
            frame = first_replace(frame, controller=frame.controller.advance(2))
            displaced_attribute = frame.scan.word()
            frame = first_replace(frame, scan=frame.scan.advance(2))
            frame = _movement_move(state, frame, 'offset_x', displaced_attribute, 16)
            # Both source and destination use A3 postincrement: total four.
            frame = _command_policy_store_word_fields(state, frame, frame.scan.address(0), low16(frame.unit))
            frame = first_replace(frame, scan=frame.scan.advance(2))
            frame = _movement_move(state, frame, 'target_x', low16(frame.count), 16)
            frame = _movement_move(state, frame, 'target_y', low16(frame.distance), 16)
            frame = _movement_move(state, frame, 'unit', low16(frame.offset_x), 16)

def partition_ranked_packet_roster_fields(state: SceneState,
        frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """34854: DBRA-limited first partition, separator, then copied remainder."""
    frame = _resource_cost_frame(state, frame, 0x34854)
    frame = first_replace(frame, roster=state.table_at(0xFFFFD300).cursor())
    frame = first_replace(frame, candidates=state.table_at(0xFFFFD320).cursor())
    frame = _movement_move(state, frame, 'unit', low16(frame.target_y), 16)
    frame = _movement_adjust_word(state, frame, 'unit', -1)
    # A zero limit retains the original 65536-iteration WORD-counter behavior.
    while True:
        officer = frame.candidates.word()
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _command_policy_store_word_fields(state, frame, frame.roster.address(0), officer)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        frame = first_replace(frame, unit=replace_word(frame.unit, u16(low16(frame.unit) - 1)))
        if low16(frame.unit) == 65535:
            break
    frame = _command_policy_store_word_fields(state, frame, frame.roster.address(0), 65535)
    frame = first_replace(frame, roster=frame.roster.advance(2))
    while True:
        officer = frame.candidates.word()
        frame = first_replace(frame, candidates=frame.candidates.advance(2))
        frame = _command_policy_store_word_fields(state, frame, frame.roster.address(0), officer)
        frame = first_replace(frame, roster=frame.roster.advance(2))
        if frame.status & 8:
            return frame
